INSERT INTO `lessons` (`id`, `section_id`, `title_ru`, `slug`, `lesson_order`, `content`) VALUES
(2, 1, '1.1. Знакомство с Google Таблицами, датасетом и интерфейсом', 'google-sheets-intro', 1, '{\"theory\":\"<p>Google Таблицы — это облачный табличный процессор.&nbsp;<br>Он позволяет хранить рабочие данные в интернете, открывать их с разных устройств и совместно работать с ними.&nbsp;<br>В этом курсе Google Таблицы будут использоваться как простая облачная база данных для службы доставки еды.<\\/p><p>В следующих уроках на этих же данных мы будем рассчитывать показатели продаж, связывать информацию между листами, строить сводные таблицы и создавать диаграммы.&nbsp;<br>Поэтому сейчас главная задача — научиться уверенно работать с файлом и понимать, где находятся нужные данные.<\\/p><p>&nbsp;<\\/p><p><strong>Google&nbsp;Таблицы и Microsoft&nbsp;Excel<\\/strong><\\/p><p>Если вы раньше работали с Microsoft Excel, интерфейс Google Таблиц покажется знакомым.&nbsp;<br>В обоих инструментах есть строки, столбцы, ячейки, листы и формулы.<\\/p><p>Главное отличие связано с местом хранения и способом совместной работы.<\\/p><p>Microsoft Excel обычно используется как программа на компьютере.&nbsp;<br>Файл можно сохранить на компьютере, отправить другому человеку или разместить в облачном хранилище.<\\/p><p>Google Таблицы изначально работают в браузере и сохраняют документ в Google Диске. Благодаря этому изменения обычно сохраняются автоматически.&nbsp;<br>Не нужно постоянно нажимать кнопку «Сохранить».<\\/p><p>Ещё одно важное преимущество — совместный доступ.&nbsp;<br>Один файл можно открыть нескольким пользователям и работать с ним совместно, если владелец предоставил соответствующие права доступа.<\\/p><p>Для бизнеса это удобно, например, когда один сотрудник заносит заказы, другой проверяет оплату, а руководитель просматривает показатели.<\\/p><p>В этом курсе мы будем использовать именно облачный подход:&nbsp;<br>каждый студент получит готовый учебный файл и сделает его собственную копию в своём Google Диске.<\\/p><p>&nbsp;<\\/p><p><strong>Учебный датасет службы доставки<\\/strong><\\/p><p>Для практических занятий подготовлен единый датасет службы доставки еды.&nbsp;<\\/p><p>Он содержит данные, похожие на те, которые могут использоваться небольшим бизнесом в ежедневной работе.<\\/p><p>Готовый датасет доступен в облаке.<\\/p><p>Важно: работать нужно не с исходным учебным файлом, а со своей копией.<\\/p><p>&nbsp;<\\/p><p><strong>Как сделать копию учебного датасета<\\/strong><\\/p><p>Войдите в свой Google аккаунт.<\\/p><p>(В конце пары не забудьте выйти из своего Google аккаунта.)<\\/p><p>Откройте учебный датасет по адресу:<\\/p><p><a href=\\\"https:\\/\\/docs.google.com\\/spreadsheets\\/d\\/1lZAOKx9pjVMnFsK8Qc57382igG85OxQVbqTvTG0i7oE\\/edit?usp=sharing\\\">https:\\/\\/docs.google.com\\/spreadsheets\\/d\\/1lZAOKx9pjVMnFsK8Qc57382igG85OxQVbqTvTG0i7oE\\/edit?usp=sharing<\\/a><\\/p><p>&nbsp;<\\/p><p>Вам нужна собственная копия файла, потому что исходный документ является готовым учебным датасетом.&nbsp;<br>Изменения в своей копии не будут мешать другим студентам.<\\/p><p>После открытия файла найдите команду создания копии документа в меню Google Таблиц.<\\/p><p>Создайте копию.<\\/p><p>Переименуйте копию файла с названия \\\"Копия Сервис доставки - Копия\\\"<\\/p><p>на \\\"Сервис доставки - &lt;ваше Фамилия Имя&gt;\\\" ,<br>например: \\\"Сервис доставки - Трамп Доналд\\\"<\\/p><p>Сохраните копию на своём Google Диске.<\\/p><p>После копирования проверьте, что работаете именно с копией, а не с исходным файлом.<\\/p><p>&nbsp;<\\/p><p><strong>Описание учебного датасета<\\/strong><\\/p><p>В учебном датасете три листа:<\\/p><p>«Клиенты» — сведения о клиентах;<\\/p><p>«Меню и Товары» — сведения о товарах меню и ценах;<\\/p><p>«Заказы» — сведения о заказах.<\\/p><p>&nbsp;<\\/p><p>Лист «Клиенты»<\\/p><p>На этом листе находятся сведения о клиентах.<\\/p><p>В учебном датасете используются столбцы:<\\/p><p>ID_Клиента — уникальный идентификатор клиента;<\\/p><p>ФИО — имя клиента;<\\/p><p>Телефон — контактный номер;<\\/p><p>Адрес_Доставки — адрес доставки;<\\/p><p>Статус — например, статус постоянного клиента;<\\/p><p>Дата_Регистрации — дата регистрации клиента.<\\/p><p>ID нужен для однозначного определения конкретной записи.&nbsp;<br>Например, CUST-001 — это не имя человека, а уникальный идентификатор записи клиента.<\\/p><p>&nbsp;<\\/p><p>Лист «Меню и Товары»<\\/p><p>Этот лист содержит информацию о товарах.<\\/p><p>В нём есть:<\\/p><p>ID_Товара — уникальный идентификатор товара;<\\/p><p>Наименование — название блюда или другого товара;<\\/p><p>Категория — категория товара;<\\/p><p>Себестоимость_Тг — себестоимость;<\\/p><p>Цена_Продажи_Тг — цена, по которой товар продаётся клиенту.<\\/p><p>Например, для каждого товара можно отдельно увидеть его себестоимость и цену продажи.<\\/p><p>Эти данные понадобятся в следующих уроках, когда мы будем анализировать продажи и связывать информацию между листами.<\\/p><p>&nbsp;<\\/p><p>Лист «Заказы»<\\/p><p>Это основной рабочий лист для анализа заказов.<\\/p><p>В учебном датасете он содержит 100 записей и следующие столбцы:<\\/p><p>ID_Заказа — идентификатор заказа;<\\/p><p>ID_Клиента — идентификатор клиента;<\\/p><p>ID_Товара — идентификатор товара;<\\/p><p>Количество — количество единиц товара в заказе;<\\/p><p>Сумма_Заказа_Тг — сумма заказа;<\\/p><p>Канал_Поступления — откуда поступил заказ;<\\/p><p>Статус_Оплаты — состояние оплаты;<\\/p><p>Статус_Заказа — состояние выполнения заказа;<\\/p><p>Курьер — назначенный курьер;<\\/p><p>Дата_Заказа — дата и время заказа.<\\/p><p>Обратите внимание: одна строка таблицы соответствует одной записи о заказе.<\\/p><p>Например, в первой строке данных находится заказ ORD-001.&nbsp;<br>Для него указаны клиент CUST-016, товар PROD-009, количество 2 и сумма заказа 6200 тенге.<\\/p><p>&nbsp;<\\/p><p><strong>Основные элементы интерфейса&nbsp;Google&nbsp;таблиц<\\/strong><\\/p><p>Обратите внимание на основные части интерфейса.<\\/p><p>В верхней части находится название документа.&nbsp;<\\/p><p>Ниже расположено основное меню с командами работы с таблицей.<\\/p><p>Под меню находится панель инструментов.&nbsp;<br>На ней расположены часто используемые команды форматирования и работы с данными.<\\/p><p>Центральную часть экрана занимает рабочая область с ячейками.<\\/p><p>Слева находятся номера строк, а сверху — обозначения столбцов.<\\/p><p>В нижней части окна расположены вкладки листов.&nbsp;<br>Именно здесь можно переключаться между «Клиенты», «Меню и Товары» и «Заказы».<\\/p><p>&nbsp;<\\/p><p><strong>Автоматическое сохранение<\\/strong><\\/p><p>В Google Таблицах изменения сохраняются в облаке автоматически.<\\/p><p>Это отличается от привычной работы с локальным файлом Excel, где пользователь может вручную сохранять документ.<\\/p><p>Несмотря на автоматическое сохранение, полезно следить за тем, что изменения действительно записались.&nbsp;<br>Особенно это важно при нестабильном интернет-соединении.<\\/p><p>Главное правило лабораторной работы:&nbsp;<br>после выполнения задания не закрывайте таблицу сразу. Убедитесь, что изменения сохранились.<\\/p><p>&nbsp;<\\/p><p><strong>Ячейка, строка и столбец<\\/strong><\\/p><p>Основной элемент Google Таблиц — ячейка.<\\/p><p>Ячейка находится на пересечении столбца и строки.&nbsp;<br>У каждой ячейки есть адрес.<\\/p><p>Например:<\\/p><p>A1<\\/p><p>означает:<\\/p><p>A — столбец A;<\\/p><p>1 — первая строка.<\\/p><p>Если выбрать ячейку D2, это означает столбец D и строку 2.<\\/p><p>Столбцы обозначаются буквами: A, B, C, D и далее.<\\/p><p>Строки обозначаются числами: 1, 2, 3, 4 и далее.<\\/p><p>Первая строка учебной таблицы обычно содержит названия столбцов.&nbsp;<br>Поэтому первая запись данных начинается со второй строки.<\\/p><p>&nbsp;<\\/p><p>Например, на листе «Заказы»:<\\/p><p>D1 содержит название столбца Количество.<\\/p><p>А значение количества в первой записи находится в D2.<\\/p><p>Это правило адресации понадобится нам при работе с формулами.<\\/p><p>&nbsp;<\\/p><p>При выборе ячейки вокруг неё появляется рамка.&nbsp;<br>Это означает, что ячейка активна и готова для ввода или редактирования данных.<\\/p><p>Если нужно изменить значение ячейки, её можно выбрать и начать вводить новое значение.<\\/p><p>&nbsp;<\\/p><p><strong>Первая простая формула<\\/strong><\\/p><p>Формула в Google Таблицах начинается со знака =.<\\/p><p>Например:<\\/p><p>=2+3<\\/p><p>после ввода даст результат 5.<\\/p><p>Но для бизнес-задач интереснее использовать значения из ячеек.<\\/p><p>На листе «Заказы» в первой записи:<\\/p><p>количество находится в D2;<\\/p><p>сумма заказа уже указана в E2.<\\/p><p>Чтобы потренироваться с формулами, добавим рядом с таблицей временный расчёт.<\\/p><p>В первой строке заказа количество равно 2.&nbsp;<br>Для товара PROD-009 на листе «Меню и Товары» цена продажи составляет 3100 тенге.<\\/p><p>Поэтому итоговую стоимость можно рассчитать так:<\\/p><p>=D2*3100<\\/p><p>Результат будет равен 6200.<\\/p><p>Здесь D2 — количество товара, а 3100 — цена одной единицы товара.<\\/p><p>Знак * означает умножение.<\\/p><p>В дальнейшем мы научимся автоматически получать цену товара из листа меню с помощью функции XLOOKUP.&nbsp;<\\/p><p>Сейчас этого делать не нужно - функция XLOOKUP будет изучаться в уроке 1.3.<\\/p><p>На этом этапе важно понять только базовый принцип:<\\/p><p>= сообщает Google Таблицам, что начинается формула;<\\/p><p>D2 позволяет использовать значение из ячейки;<\\/p><p>* выполняет умножение.<\\/p><p>Формула не является обычным текстом.&nbsp;<\\/p><p>Google Таблицы вычисляют её и показывают полученный результат.<\\/p><p>Если изменить количество товара, результат формулы, использующей ячейку D2, также изменится автоматически.<\\/p><p>&nbsp;<\\/p><p><strong>Что нужно запомнить<\\/strong><\\/p><p>Google Таблицы — облачный инструмент для работы с табличными данными.<\\/p><p>В нашем курсе таблица используется как простая база данных службы доставки.<\\/p><p>Учебный файл содержит три листа: «Клиенты», «Меню и Товары» и «Заказы».<\\/p><p>Каждый лист предназначен для своего типа информации.<\\/p><p>Ячейка определяется буквой столбца и номером строки, например D2.<\\/p><p>Формула начинается со знака =.<\\/p><p>Для умножения используется знак *.<\\/p><p>Исходный учебный файл нужно сначала скопировать на свой Google Диск, после чего выполнять практические задания в своей копии.<\\/p>\",\"tests\":[{\"question\":\"Какое главное преимущество Google Таблиц особенно важно при совместной работе?\",\"answers\":[\"Можно работать без подключения к интернету  \",\"Файл автоматически превращается в презентацию\",\"Несколько пользователей могут работать с одним документом при наличии доступа ✓\",\"Каждый пользователь обязан создавать отдельный файл\"],\"correct\":0},{\"question\":\"Где хранятся изменения в обычной работе с Google Таблицами?\",\"answers\":[\"В облаке Google Диска и документ обновляется автоматически ✓  \",\"В оперативной памяти компьютера до закрытия браузера\",\"В отдельном текстовом файле на рабочем столе\",\"На флеш-накопителе пользователя\"],\"correct\":0},{\"question\":\"Что обозначает адрес ячейки D2?\",\"answers\":[\"Второй столбец и строку D  \",\"Столбец D и вторую строку ✓\",\"Четвёртый лист и вторую запись\",\"Диапазон от D до 2\"],\"correct\":0},{\"question\":\"С какого символа должна начинаться формула в Google Таблицах?\",\"answers\":[\"#  \",\"$\",\"= ✓\",\"@\"],\"correct\":0},{\"question\":\"Какой оператор используется для умножения в формуле?\",\"answers\":[\"•  \",\"˟\",\"×\",\"*✓\"],\"correct\":0},{\"question\":\"Что означает D2 в формуле =D2*3100?\",\"answers\":[\"Название товара  \",\"Цена товара\",\"Количество товара из ячейки D2 ✓\",\"Номер листа\"],\"correct\":0},{\"question\":\"Почему студенту нужно создать собственную копию учебного датасета?\",\"answers\":[\"Чтобы изменения исходного учебного файла были видны всем студентам  \",\"Чтобы работать со своими данными, не изменяя исходный учебный файл ✓\",\"Чтобы удалить все остальные листы\",\"Чтобы отключить автоматическое сохранение Google Таблиц\"],\"correct\":0}],\"lab\":\"<p>Изучите листы учебного датасета.<\\/p><p>По очереди откройте три листа:<\\/p><p>Клиенты<\\/p><p>Меню и Товары<\\/p><p>Заказы<\\/p><p>Для каждого листа определите, какую информацию он содержит.<\\/p><p>На листе «Клиенты» найдите:<\\/p><p>ID клиента;<\\/p><p>ФИО;<\\/p><p>адрес доставки;<\\/p><p>статус;<\\/p><p>дату регистрации.<\\/p><p>На листе «Меню и Товары» найдите:<\\/p><p>ID товара;<\\/p><p>название товара;<\\/p><p>категорию;<\\/p><p>себестоимость;<\\/p><p>цену продажи.<\\/p><p>На листе «Заказы» найдите:<\\/p><p>ID заказа;<\\/p><p>ID клиента;<\\/p><p>ID товара;<\\/p><p>количество;<\\/p><p>сумму заказа;<\\/p><p>канал поступления;<\\/p><p>статус оплаты;<\\/p><p>статус заказа;<\\/p><p>курьера;<\\/p><p>дату заказа.<\\/p>\"}'),
(3, 1, '1.2. Формулы и функции для бизнес-анализа продаж', 'formulas-and-functions', 2, '{\"theory\":\"<p>После первого урока у вас уже есть копия учебной таблицы службы доставки и вы умеете работать с листом «Заказы».&nbsp;<br>Теперь начнём использовать Google Таблицы не просто для хранения данных, а для получения ответов на бизнес-вопросы.<\\/p><p>Например:<\\/p><p>сколько денег принесли все заказы;<\\/p><p>какой средний чек;<\\/p><p>сколько было заказов;<\\/p><p>какой заказ был самым крупным;<\\/p><p>какая сумма продаж приходится на определённый способ оплаты;<\\/p><p>сколько заказов относится к выбранному условию.<\\/p><p>&nbsp;<\\/p><p>В учебном датасете лист «Заказы» содержит 100 заказов и, среди прочего, следующие поля: ID_Заказа, Количество, Сумма_Заказа_Тг, Статус_Оплаты, Статус_Заказа, Курьер, Дата_Заказа. Эти данные будем использовать для расчётов.<\\/p><p>&nbsp;<\\/p><p>В этом уроке мы изучим функции SUM, AVERAGE, COUNTIF, MIN, MAX&nbsp;и SUMIF.<\\/p><p>&nbsp;<\\/p><p><strong>Формулы и функции<\\/strong><\\/p><p>Формулы и функции для этого урока можете писать в любой свободной ячейке справа от имеющихся данных датасета.<\\/p><p>Формула в Google Таблицах начинается со знака =.<\\/p><p>Например:<\\/p><p><code>=2+3<\\/code><\\/p><p>После нажатия Enter таблица покажет результат 5.<\\/p><p>Но в бизнес-таблицах редко приходится складывать несколько чисел вручную.&nbsp;<br>Обычно нужно обработать целый диапазон ячеек.&nbsp;<br>Для этого используются функции.<\\/p><p>Функция — это готовая команда, которая выполняет определённое действие над данными.<\\/p><p>Общий вид функции:<\\/p><p><code>=НАЗВАНИЕ_ФУНКЦИИ(аргумент)<\\/code><\\/p><p>Аргумент — это данные, которые функция должна обработать.<\\/p><p>Например:<\\/p><p><code>=SUM(E2:E101)<\\/code><\\/p><p>Здесь:<\\/p><p>SUM — название функции;<\\/p><p>E2:E101 — диапазон ячеек;<\\/p><p>E2:E101 означает все ячейки от E2 до E101;<\\/p><p>результатом будет сумма всех значений в этом диапазоне.<\\/p><p>&nbsp;<\\/p><p>В нашем датасете столбец Сумма_Заказа_Тг находится в столбце E листа «Заказы».&nbsp;<br>Поэтому диапазон E2:E101 содержит суммы 100 заказов.<\\/p><p>Важно: диапазон нужно выбирать по фактическому расположению данных.&nbsp;<br>Если в вашей копии таблицы строки или столбцы расположены иначе, ориентируйтесь на заголовки.<\\/p><p>В зависимости от региональных настроек Google Таблиц аргументы функции могут разделяться запятой или точкой с запятой.&nbsp;<\\/p><p>Например:<\\/p><p><code>=SUM(E2:E101)<\\/code><\\/p><p>Функция с несколькими аргументами может выглядеть так:<\\/p><p><code>=SUMIF(G2:G101,\\\"Оплачено Kaspi\\\",E2:E101)<\\/code><\\/p><p>Если ваша таблица требует точку с запятой, используйте:<\\/p><p><code>=SUMIF(G2:G101;\\\"Оплачено Kaspi\\\";E2:E101)<\\/code><\\/p><p>Смысл функции при этом не меняется.<\\/p><p>&nbsp;<\\/p><p><strong>SUM — общая сумма<\\/strong><\\/p><p>SUM используется, когда нужно сложить значения.<\\/p><p>Для расчёта общей суммы заказов:<\\/p><p><code>=SUM(E2:E101)<\\/code><\\/p><p>В учебном датасете результат составляет 404 550 тг.<\\/p><p>Такой расчёт отвечает на простой вопрос:&nbsp;<br>«Какова сумма всех значений в выбранном столбце?»<\\/p><p>SUM можно применять не только к продажам.&nbsp;<\\/p><p>Например, с её помощью можно сложить количество товаров, расходы, количество часов и другие числовые показатели.<\\/p><p>Главное правило: в качестве диапазона выбирайте именно тот столбец, показатель которого хотите суммировать.<\\/p><p>&nbsp;<\\/p><p><strong>AVERAGE — среднее значение<\\/strong><\\/p><p>AVERAGE рассчитывает среднее арифметическое.<\\/p><p>Для суммы заказов:<\\/p><p><code>=AVERAGE(E2:E101)<\\/code><\\/p><p>В учебном датасете средняя сумма заказа составляет 4 045,50 тг.<\\/p><p>Средний чек помогает оценить типичный размер заказа.&nbsp;<br>Если общее количество заказов увеличилось, но средний чек уменьшился, бизнес получает другую картину, чем при одновременном росте количества заказов и среднего чека.<\\/p><p>Важно понимать разницу:<\\/p><p>SUM отвечает на вопрос «сколько всего?».<\\/p><p>AVERAGE отвечает на вопрос «сколько в среднем на один показатель?».<\\/p><p>Не нужно складывать значения вручную и затем самостоятельно делить на количество строк. AVERAGE делает это автоматически.<\\/p><p>&nbsp;<\\/p><p><strong>COUNTIF — подсчёт по условию<\\/strong><\\/p><p>COUNTIF используется, когда нужно посчитать количество ячеек, соответствующих определённому условию.<\\/p><p>Общий вид:<\\/p><p><code>=COUNTIF(диапазон, условие)<\\/code><\\/p><p>&nbsp;<\\/p><p>Например, если мы хотим узнать, сколько заказов оплачено через Kaspi:<\\/p><p><code>=COUNTIF(G2:G101,\\\"Оплачено Kaspi\\\")<\\/code><\\/p><p>Здесь:<\\/p><p>G2:G101 — диапазон, в котором выполняется поиск;<\\/p><p>\\\"Оплачено Kaspi\\\" — условие;<\\/p><p>функция считает, сколько раз это значение встречается в диапазоне.<\\/p><p>В учебном датасете таких заказов 61.<\\/p><p>&nbsp;<\\/p><p>Для наличных:<\\/p><p><code>=COUNTIF(G2:G101,\\\"Наличными курьеру\\\")<\\/code><\\/p><p>В датасете таких записей 25.<\\/p><p>&nbsp;<\\/p><p>Обратите внимание:&nbsp;<br>COUNTIF считает количество подходящих ячеек, а не сумму денег.<\\/p><p>Если в столбце находятся суммы заказов и вы напишете COUNTIF, функция будет отвечать на вопрос «сколько ячеек соответствует условию», а не «сколько денег в них находится».<\\/p><p>&nbsp;<\\/p><p><strong>MIN и MAX — минимальное и максимальное значение<\\/strong><\\/p><p>MIN позволяет найти наименьшее значение.<\\/p><p>Например:<\\/p><p><code>=MIN(E2:E101)<\\/code><\\/p><p>Эта формула ищет самый маленький размер заказа в столбце Сумма_Заказа_Тг.<\\/p><p>В учебном датасете минимальная сумма заказа — 700 тг.<\\/p><p>MAX работает наоборот:<\\/p><p><code>=MAX(E2:E101)<\\/code><\\/p><p>Она находит самое большое значение.<\\/p><p>В учебном датасете максимальная сумма заказа — 13 600 тг.<\\/p><p>Таким образом:<\\/p><p>MIN — минимум;<\\/p><p>MAX — максимум.<\\/p><p>Эти функции особенно полезны для быстрого поиска крайних значений без просмотра всех строк вручную.<\\/p><p>При этом MIN и MAX показывают само значение, но не сообщают автоматически, в какой именно строке оно находится.<\\/p><p>&nbsp;<\\/p><p><strong>SUMIF — сумма по условию<\\/strong><\\/p><p>SUMIF нужна, когда требуется не просто сложить весь столбец, а сложить только те значения, которые соответствуют определённому условию.<\\/p><p>Общий вид:<\\/p><p><code>=SUMIF(диапазон_условия, условие, диапазон_суммы)<\\/code><\\/p><p>&nbsp;<\\/p><p>Рассмотрим задачу из нашего датасета.<\\/p><p>Нужно узнать, сколько составила сумма заказов, оплаченных через Kaspi.<\\/p><p>Условие находится в столбце G Статус_Оплаты, а деньги находятся в столбце E Сумма_Заказа_Тг.<\\/p><p>Формула:<\\/p><p><code>=SUMIF(G2:G101,\\\"Оплачено Kaspi\\\",E2:E101)<\\/code><\\/p><p>Если используются точки с запятой:<\\/p><p><code>=SUMIF(G2:G101;\\\"Оплачено Kaspi\\\";E2:E101)<\\/code><\\/p><p>Здесь первый диапазон отвечает на вопрос:&nbsp;<br>«Где искать условие?»<\\/p><p>Условие отвечает на вопрос:&nbsp;<br>«Что именно искать?»<\\/p><p>Последний диапазон отвечает на вопрос:&nbsp;<\\/p><p>«Какие значения складывать?»<\\/p><p>Результат для учебного датасета — 245 900 тг.<\\/p><p>Для наличных:<\\/p><p><code>=SUMIF(G2:G101,\\\"Наличными курьеру\\\",E2:E101)<\\/code><\\/p><p>Результат — 92 050 тг.<\\/p><p>Это уже настоящий бизнес-анализ:&nbsp;<\\/p><p>вместо просмотра 100 строк мы получаем сумму продаж по конкретному способу оплаты одной формулой.<\\/p><p>&nbsp;<\\/p><p><strong>Разница между COUNTIF и SUMIF<\\/strong><\\/p><p>Эти функции похожи тем, что обе работают с условием, но выполняют разные действия.<\\/p><p>COUNTIF считает количество подходящих записей.<\\/p><p>SUMIF складывает значения, связанные с подходящими записями.<\\/p><p>Например:<\\/p><p><code>=COUNTIF(G2:G101,\\\"Оплачено Kaspi\\\")<\\/code><\\/p><p>отвечает на вопрос:<\\/p><p>«Сколько заказов оплачено через Kaspi?»<\\/p><p>А:<\\/p><p><code>=SUMIF(G2:G101,\\\"Оплачено Kaspi\\\",E2:E101)<\\/code><\\/p><p>отвечает на вопрос:<\\/p><p>«На какую сумму оформлены заказы с оплатой через Kaspi?»<\\/p><p>Для бизнес-анализа это принципиально разные показатели.<\\/p><p>&nbsp;<\\/p><p><strong>Как читать функцию по частям<\\/strong><\\/p><p>Когда формула становится длиннее, не нужно пытаться запомнить её целиком.&nbsp;<br>Разбирайте её слева направо.<\\/p><p>Например:<\\/p><p><code>=SUMIF(G2:G101,\\\"Оплачено Kaspi\\\",E2:E101)<\\/code><\\/p><p>Шаг 1. SUMIF — понимаем, что хотим получить сумму по условию.<\\/p><p>Шаг 2. G2:G101 — определяем, где находится условие.<\\/p><p>Шаг 3. \\\"Оплачено Kaspi\\\" — определяем само условие.<\\/p><p>Шаг 4. E2:E101 — определяем, какие значения нужно сложить.<\\/p><p>Такой способ разбора помогает не только создавать формулы, но и находить ошибки.<\\/p><p>&nbsp;<\\/p><p><strong>Типичные ошибки<\\/strong><\\/p><p>Одна из распространённых ошибок — выбрать не тот столбец.<\\/p><p>Например, если условие «Оплачено Kaspi» искать в столбце E с суммами, функция не сможет правильно выполнить задачу.&nbsp;<br>Значение Оплачено Kaspi находится в столбце G.<\\/p><p>Другая ошибка — перепутать COUNTIF и SUMIF.<\\/p><p>Если требуется количество заказов, используйте COUNTIF.<\\/p><p>Если требуется сумма денег по условию, используйте SUMIF.<\\/p><p>Ещё одна ошибка — забыть знак = в начале формулы.&nbsp;<br>Без него Google Таблицы не воспринимают запись как формулу.<\\/p><p>Также важно точно писать текстовое условие.&nbsp;<\\/p><p>Например, Оплачено Kaspi и Оплачено — это разные значения.<\\/p><p>Поэтому при использовании текстовых условий лучше копировать значение непосредственно из таблицы, чтобы не допустить опечатку.<\\/p><p>&nbsp;<\\/p><p><strong>Что мы умеем после этого урока<\\/strong><\\/p><p>Теперь с помощью нескольких функций можно быстро получить базовые показатели продаж:<\\/p><p><code>=SUM(E2:E101) <\\/code>— общая сумма заказов;<\\/p><p><code>=AVERAGE(E2:E101)<\\/code> — средняя сумма заказа;<\\/p><p><code>=COUNTIF(G2:G101,\\\"Оплачено Kaspi\\\")<\\/code> — количество заказов с оплатой Kaspi;<\\/p><p><code>=MIN(E2:E101)<\\/code> — минимальная сумма заказа;<\\/p><p><code>=MAX(E2:E101)<\\/code> — максимальная сумма заказа;<\\/p><p><code>=SUMIF(G2:G101,\\\"Оплачено Kaspi\\\",E2:E101)<\\/code> — сумма заказов с оплатой Kaspi.<\\/p><p>В следующем уроке эти расчёты будут использоваться вместе с другими возможностями Google Таблиц для связывания данных между листами и создания сводных отчётов.<\\/p>\",\"tests\":[{\"question\":\"Какой символ должен стоять в начале формулы Google Таблиц?\",\"answers\":[\":\",\"= ✓\",\":=\",\"==\"],\"correct\":null},{\"question\":\"Что делает функция SUM?\",\"answers\":[\"Считает количество строк с данными\",\"Находит сумму всех чисел в таблице\",\"Складывает значения выбранного диапазона ✓\",\"Преобразует текст в сумму\"],\"correct\":null},{\"question\":\"Какая функция используется для расчёта среднего значения?\",\"answers\":[\"MIDDLE\",\"COUNTIF\",\"SUMIF\",\"AVERAGE ✓\"],\"correct\":null},{\"question\":\"Какую задачу решает COUNTIF?\",\"answers\":[\"Считает ячейки, соответствующие условию ✓\",\"Складывает все числа в таблице\",\"Находит самый большой заказ\",\"Удаляет строки, которые не соответствуют условию\"],\"correct\":null},{\"question\":\"Что делает формула =MIN(E2:E101)?\",\"answers\":[\"Находит наименьшее значение в таблице\",\"Находит наименьшее значение в диапазоне ✓\",\"Считает количество заказов\",\"Складывает значения в столбце E\"],\"correct\":null},{\"question\":\"Какая функция нужна, чтобы получить сумму только тех заказов, которые соответствуют определённому условию?\",\"answers\":[\"AVERAGE\",\"COUNTIF\",\"IFSUM\",\"SUMIF ✓\"],\"correct\":null},{\"question\":\"В формуле =SUMIF(G2:G101,\\\"Оплачено Kaspi\\\",E2:E101) что означает диапазон G2:G101?\",\"answers\":[\"Диапазон, в котором находятся суммы заказов\",\"Диапазон, в котором проверяется условие ✓\",\"Диапазон клиентов Kaspi\",\"Диапазон с датами регистрации клиентов\"],\"correct\":null},{\"question\":\"Что делает формула =COUNTIF(G2:G101,\\\"Оплачено Kaspi\\\")?\",\"answers\":[\"Складывает суммы заказов Kaspi\",\"Находит самый дорогой заказ\",\"Считает количество заказов с указанным способом оплаты ✓\",\"Рассчитывает средний чек Kaspi\"],\"correct\":null},{\"question\":\"Какой показатель можно получить с помощью =AVERAGE(E2:E101)?\",\"answers\":[\"Среднюю сумму заказа ✓\",\"Количество заказов\",\"Самую маленькую сумму заказа\",\"Общую сумму всех заказов в диапазоне\"],\"correct\":null}],\"lab\":\"<p>В этой лабораторной работе не будут повторяться расчёты, разобранные в теоретической части.&nbsp;<\\/p><p>Ваша задача — самостоятельно выбрать подходящую функцию из изученных SUM, AVERAGE, COUNTIF, MIN, MAX и SUMIF, определить нужный диапазон и получить ответ на бизнес-вопрос.<\\/p><p>Для части заданий используйте лист Заказы, а для части — лист Меню и Товары.&nbsp;<\\/p><p>&nbsp;<\\/p><p>Задача 1. Анализ каналов поступления заказов<\\/p><p>Руководитель хочет понять, через какие каналы чаще всего поступают заказы.<\\/p><p>Используя лист Заказы, определите количество заказов, поступивших через:<\\/p><p>WhatsApp;<\\/p><p>Telegram-бот;<\\/p><p>Звонок;<\\/p><p>Приложение\\/Сайт.<\\/p><p>Самостоятельно определите, какую функцию использовать и в каком столбце искать условие.<\\/p><p>В конце укажите, какой канал оказался самым распространённым.<\\/p><p>&nbsp;<\\/p><p>Задача 2. Сравнение продаж по каналам<\\/p><p>Теперь руководителю нужно сравнить не количество заказов, а их денежный объём.<\\/p><p>Для каждого из четырёх каналов из предыдущей задачи определите общую сумму заказов.<\\/p><p>Используйте ту же логику анализа, но самостоятельно выберите функцию, которая позволяет суммировать значения только для записей, соответствующих заданному условию.<\\/p><p>Сравните результаты и определите канал с наибольшей суммой заказов.<\\/p><p>&nbsp;<\\/p><p>Задача 3. Анализ работы курьеров<\\/p><p>Определите количество заказов, которые были назначены каждому из курьеров:<\\/p><p>Алихан (Курьер #1);<\\/p><p>Дмитрий (Курьер #2);<\\/p><p>Руслан (Курьер #3);<\\/p><p>Ерлан (Курьер #4).<\\/p><p>После расчёта определите, у какого курьера больше всего заказов.<\\/p><p>Обратите внимание, что в таблице встречаются отменённые заказы без назначенного курьера. Не включайте их в результаты для конкретных курьеров.<\\/p><p>&nbsp;<\\/p><p>Задача 4. Средняя стоимость товаров в категории<\\/p><p>Перейдите к листу Меню и Товары.<\\/p><p>Для категории Пицца определите среднюю цену продажи товаров.<\\/p><p>Затем выполните такой же расчёт для категории Суши и Роллы.<\\/p><p>Сравните два результата и определите, в какой из этих категорий средняя цена продажи выше.<\\/p><p>Здесь вам потребуется самостоятельно определить, как применить изученную функцию среднего значения к данным, отобранным по условию.<\\/p><p>&nbsp;<\\/p><p>Задача 5. Размер ассортимента по категориям<\\/p><p>На листе Меню и Товары определите, сколько товаров относится к каждой из следующих категорий:<\\/p><p>Пицца;<\\/p><p>Суши и Роллы;<\\/p><p>Бургеры;<\\/p><p>Напитки.<\\/p><p>После расчёта определите категорию с наибольшим количеством позиций.<\\/p><p>&nbsp;<\\/p><p>Задача 6. Анализ ценового диапазона<\\/p><p>На листе Меню и Товары найдите:<\\/p><p>самую низкую себестоимость товара;<\\/p><p>самую высокую цену продажи.<\\/p><p>Насколько отличается самая высокая цена продажи от самой низкой?<\\/p><p>&nbsp;<\\/p><p>Задача 7. Анализ количества проданных единиц<\\/p><p>В листе Заказы есть столбец Количество.<\\/p><p>Определите:<\\/p><p>общее количество единиц товаров во всех заказах;<\\/p><p>среднее количество единиц товара в одном заказе;<\\/p><p>максимальное количество единиц товара в одном заказе.<\\/p><p>Для каждого показателя самостоятельно выберите подходящую изученную функцию.<\\/p><p>Обратите внимание: здесь анализируется не денежная сумма заказа, а количество товаров.<\\/p><p>&nbsp;<\\/p><p>Задача 8. Анализ ассортимента по себестоимости<\\/p><p>На листе Меню и Товары определите, сколько товаров имеют себестоимость ниже 1000 тг.<\\/p><p>Затем определите, сколько товаров имеют цену продажи выше 3000 тг.<\\/p><p>Для решения самостоятельно определите:<\\/p><p>какой столбец нужно анализировать;<\\/p><p>какое условие использовать;<\\/p><p>какую функцию применить.<\\/p><p>&nbsp;<\\/p><p>Задача 9. Мини-отчёт руководителю<\\/p><p>На основании выполненных расчётов подготовьте небольшой набор показателей для руководителя службы доставки.<\\/p><p>Самостоятельно выберите и рассчитайте:<\\/p><p>канал, через который поступает больше всего заказов;<\\/p><p>канал с наибольшей суммой заказов;<\\/p><p>курьера с наибольшим количеством назначенных заказов;<\\/p><p>максимальную цену продажи товара;<\\/p><p>среднюю цену продажи пиццы.<\\/p><p>Рядом с каждым показателем укажите полученное значение.<\\/p><p>В конце сформулируйте 2–3 предложения с выводами о продажах и ассортименте.<\\/p><p>&nbsp;<\\/p><p>Главная цель лабораторной работы — не получить конкретный набор чисел, а научиться самостоятельно переводить бизнес-вопрос в последовательность действий: определить показатель, найти нужный столбец, выбрать подходящую функцию, указать условие и проверить полученный результат.<\\/p>\"}'),
(4, 1, '1.3. Связывание листов через XLOOKUP и сводные таблицы', 'xlookup-and-pivot-table', 3, '{\"theory\":\"<p>В предыдущем уроке мы использовали функции для анализа уже имеющихся данных.&nbsp;<br>Теперь сделаем следующий шаг:&nbsp;<br>научимся брать информацию из одного листа и автоматически подставлять её в другой.<\\/p><p>В учебном датасете службы доставки для этого особенно удобно использовать два листа:<\\/p><p>«Заказы» — здесь хранится информация о заказах;<\\/p><p>«Меню и Товары» — здесь находится справочник товаров:&nbsp;<br>ID товара, название, категория, себестоимость и цена продажи.<\\/p><p>В таблице «Заказы» есть ID_Товара, но нет отдельного названия блюда.&nbsp;<br>Это хороший пример ситуации, когда данные хранятся в разных таблицах, а пользователю нужно видеть их вместе.&nbsp;<br>В листе «Заказы» также есть количество товара, сумма заказа, статус заказа и курьер. Структура этих полей подтверждается учебным датасетом.<\\/p><p>&nbsp;<\\/p><p><strong>Зачем связывать листы<\\/strong><\\/p><p>Откройте в датасете лист Заказы и посмотрите на первые три колонки:<\\/p><p>ORD-001 | CUST-016 | PROD-009 | 2 | ...<\\/p><p>По значению PROD-009 оператору не сразу понятно, какое именно блюдо заказано.<\\/p><p>На листе «Меню и Товары» этот же код связан с конкретным товаром.&nbsp;<\\/p><p>В справочнике есть, например, PROD-001 — Пицца Пепперони (30 см) и PROD-002 — Пицца Маргарита (30 см), а также категории, себестоимость и цены продажи.<\\/p><p>Получается простая логика:<\\/p><p>ID_Товара из Заказов → поиск такого же ID в Меню и Товары → получение нужного значения<\\/p><p>Так таблицы могут работать как связанные части одной небольшой базы данных.<\\/p><p>&nbsp;<\\/p><p><strong>Функция XLOOKUP<\\/strong><\\/p><p>Для такого поиска используем XLOOKUP.<\\/p><p>XLOOKUP позволяет отдельно указать колонку, где выполняется поиск, и колонку, откуда нужно вернуть результат.<\\/p><p>Общий вид:<\\/p><p><code>=XLOOKUP(что_ищем; где_ищем; что_вернуть)<\\/code><\\/p><p>Три основные части:<\\/p><p>1. Что ищем<\\/p><p>Значение, которое должно найтись в справочнике.<\\/p><p>В нашем случае это ID_Товара из текущей строки листа «Заказы».<\\/p><p>2. Где ищем<\\/p><p>Колонка справочника, в которой находятся ID товаров.<\\/p><p>В листе «Меню и Товары» это колонка ID_Товара.<\\/p><p>3. Что вернуть<\\/p><p>Колонка, значение из которой нужно получить.<\\/p><p>Если хотим получить название блюда, выбираем колонку Наименование.<\\/p><p>Таким образом, функция отвечает на вопрос:<\\/p><p>«Найди этот ID товара в справочнике и верни название соответствующего товара».<\\/p><p>&nbsp;<\\/p><p>Пример: получение названия блюда<\\/p><p>Допустим, в листе «Заказы» в ячейке C2 находится ID товара.<\\/p><p>Выберите столбец справа от заполненных столбцов датасета (скорее всего у вас это столбец К), и в ячейке соответствующей строки заказа (скорее всего К2) введите формулу:<\\/p><p><code>=XLOOKUP(C2,\'Меню и Товары\'!A:A,\'Меню и Товары\'!B:B)<\\/code><\\/p><p>Здесь:<\\/p><p>C2 — ID товара, который ищем;<\\/p><p>\'Меню и Товары\'! A:A — колонка ID товаров;<\\/p><p>\'Меню и Товары\'! B:B — колонка названий товаров.<\\/p><p>Название листа заключено в одинарные кавычки, потому что в нём есть пробелы.<\\/p><p>После ввода формулы Google Таблицы находят соответствующий ID и возвращают название товара.<\\/p><p>Например, если найден PROD-009, результатом будет название этого товара — «Темпура ролл с креветкой».<\\/p><p>Естественно, можно сделать автозаполнение по столбцу, как и в Excel.<\\/p><p>Внимание:<\\/p><p>Здесь, и в дальнейших примерах, конкретные имена столбцов, адреса ячеек, ID заказов, клиентов, товаров, наименования - могут отличаться в вашем реальном датасете.&nbsp;<br>Поэтому ориентируйтесь самостоятельно по месту.<\\/p><p>Главное понять принцип.<\\/p><p>&nbsp;<\\/p><p><strong>Получение цены из того же справочника<\\/strong><\\/p><p>Точно таким же способом можно получить цену продажи.<\\/p><p>Меняется только третий аргумент XLOOKUP — колонка, из которой возвращается результат.<\\/p><p>В листе «Меню и Товары» цена продажи находится в колонке Цена_Продажи_Тг.&nbsp;<br>Например, для PROD-001 указана цена 3200 тг, а для PROD-002 — 2600 тг.<\\/p><p>Можно указать цену продажи данного товара в соседнем столбце (относительно предыдущего примера) (L).<\\/p><p>В ячейку L2 введите следующую формулу:<\\/p><p><code>=XLOOKUP(C2,\'Меню и Товары\'!A:A,\'Меню и Товары\'!E:E)<\\/code><\\/p><p>В столбце L отобразится цена товара с данным ID.<\\/p><p>(например: для PROD-009 - Темпура ролл с креветкой - 3100)<\\/p><p>&nbsp;<\\/p><p>Если в заказе указано количество 2, то после получения цены можно рассчитать стоимость без скидки:<\\/p><p>Количество × Цена.<\\/p><p>В ячейке&nbsp;M2 введите формулу:<\\/p><p>=L2*D2<\\/p><p>Например:<\\/p><p>2 × 3100 = 6200 тг<\\/p><p>Так мы не вводим цену блюда вручную в каждый заказ.&nbsp;<\\/p><p>Если цена берётся из единого справочника, вероятность случайно указать неправильную цену становится меньше.<\\/p><p>(В исходном датасете уже есть столбец с итоговой стоимостью, т.е. то же, что мы рассчитали сейчас формулой. Это сделано сознательно, чтобы можно было использовать эти данные на предыдущем уроке и, при этом, не усложнять. В реальности такие данные, конечно, рассчитываются формулой).<\\/p><p>&nbsp;<\\/p><p><strong>Почему важно правильно выбирать колонки<\\/strong><\\/p><p>При работе с XLOOKUP новичок часто ошибается не в самой функции, а в диапазонах.<\\/p><p>Нужно различать:<\\/p><p>где ищем<\\/p><p>и<\\/p><p>что возвращаем.<\\/p><p>Если искать ID в колонке названий, совпадения не найдутся.<\\/p><p>Если искать ID правильно, но вернуть колонку себестоимости вместо цены продажи, таблица покажет число, которое выглядит правдоподобно, но отвечает уже на другой вопрос.<\\/p><p>В нашем справочнике отдельно хранятся:<\\/p><p>ID товара;<\\/p><p>наименование;<\\/p><p>категория;<\\/p><p>себестоимость;<\\/p><p>цена продажи.<\\/p><p>Поэтому перед созданием формулы полезно сначала определить бизнес-вопрос:<\\/p><p>«Что я хочу узнать по ID товара?»<\\/p><p>Затем выбрать соответствующую колонку результата.<\\/p><p>&nbsp;<\\/p><p><strong>Расчет стоимости со скидкой<\\/strong><\\/p><p>После получения цены можно выполнять обычные арифметические расчёты, которые мы уже использовали в предыдущем уроке.<\\/p><p>Допустим:<\\/p><p>цена товара — 3100 тг;<\\/p><p>количество — 2;<\\/p><p>скидка — 10%.<\\/p><p>Сначала рассчитываем стоимость без скидки:<\\/p><p>3100 × 2 = 6200<\\/p><p>Размер скидки:<\\/p><p>6200 × 10% = 620<\\/p><p>Стоимость после скидки:<\\/p><p>6200 − 620 = 5580<\\/p><p>В таблице это можно объединить в одну формулу:<\\/p><p><code>=Цена*Количество*(1-Скидка)<\\/code><\\/p><p>Если скидка записана как 10%, формула автоматически учитывает её как десять процентов.<\\/p><p>Например:<\\/p><p><code>=L2*D2*(1-10%)<\\/code><\\/p><p>Здесь конкретные буквы столбцов зависят от того, как вы разместили новые расчётные поля. Важно не запомнить буквы, а понимать последовательность расчёта:<\\/p><p>цена × количество × (1 − скидка).<\\/p><p>Скидка в исходной структуре листа «Заказы» отдельным полем не указана. Поэтому при учебном расчёте её можно вынести в отдельный дополнительный столбец только для выполнения расчёта, предусмотренного программой урока.<\\/p><p>&nbsp;<\\/p><p><strong>Что делать с отменёнными заказами<\\/strong><\\/p><p>В датасете есть разные статусы заказа.&nbsp;<br>Для выполненных заказов указано «Доставлено», а для отменённых — «Отменено»;&nbsp;<br>у отменённых заказов вместо курьера используется символ <code>—<\\/code>.<\\/p><p>Это важно при построении отчёта.<\\/p><p>Если задача отчёта — показать продажи курьеров, отменённые заказы не следует автоматически считать продажами курьера.&nbsp;<br>Сначала нужно определить, какие строки относятся к фактически доставленным заказам.<\\/p><p>В лабораторной работе студенту потребуется самостоятельно выбрать подход к подготовке данных перед сводным отчётом, используя уже изученные возможности таблиц.<\\/p><p>&nbsp;<\\/p><p>В конце работы с XLOOKUP очистите все созданные вами ячейки с формулами и функциями.<\\/p><p>&nbsp;<\\/p><p><strong>Сводная таблица<\\/strong><\\/p><p>Сводная таблица, или Pivot Table, нужна для быстрого подведения итогов по большому количеству строк.<\\/p><p>В нашем датасете лист «Заказы» содержит отдельные записи заказов.&nbsp;<br>Для каждого заказа указаны, в частности, его ID, количество, сумма заказа, статус заказа и курьер.&nbsp;<\\/p><p>Например, если нужно узнать, какую общую сумму заказов обслужил каждый курьер, не нужно вручную искать и складывать строки.&nbsp;<br>Сводная таблица сама сгруппирует записи по курьеру и рассчитает итог.<\\/p><p>&nbsp;<\\/p><p>Логика простая:<\\/p><p>много строк заказов → группировка по курьеру → итоговая сумма по каждому курьеру<\\/p><p>Для нашего отчёта используются реальные данные листа «Заказы»:<\\/p><p>Группировка: столбец I — Курьер<\\/p><p>Показатель: столбец E — Сумма_Заказа_Тг<\\/p><p>Например, исходные строки могут содержать:<\\/p><p>ORD-001 → 6200 тг → Дмитрий (Курьер #2)<\\/p><p>ORD-002 → 3400 тг → Дмитрий (Курьер #2)<\\/p><p>ORD-003 → 3900 тг → Алихан (Курьер #1)<\\/p><p>Сводная таблица соберёт все строки каждого курьера и покажет их общий результат.&nbsp;<br>Эти значения не нужно рассчитывать вручную — их рассчитает Google Таблицы на основании исходных данных.<\\/p><p>Важно учитывать поле Статус_Заказа.&nbsp;<br>В датасете встречаются, например, статусы Доставлено и Отменено.&nbsp;<br>Поэтому перед построением отчёта о фактических продажах нужно исключить из расчёта отменённые заказы.<\\/p><p>&nbsp;<\\/p><p><strong>Создание сводной таблицы<\\/strong><\\/p><p>Для первого отчёта будем использовать непосредственно лист «Заказы».<\\/p><p>&nbsp;<\\/p><p>Шаг 1. Выделите исходные данные<\\/p><p>На листе «Заказы» выделите всю таблицу с заголовками:<\\/p><p>В меню Google Таблиц выберите:<\\/p><p>Insert (Вставка) → Pivot table (Сводная таблица).<\\/p><p>После этого Google Таблицы предложат выбрать Data&nbsp;range (диапазон) и место размещения сводной таблицы.<\\/p><p>Диапазон (\'Заказы\'!1:1000) - оставьте без изменений.<\\/p><p>Для учебной работы можно разместить сводную таблицу на New&nbsp;sheet&nbsp;(новом листе).&nbsp;<br>Так исходные данные листа «Заказы» останутся без изменений.<\\/p><p>Нажмите кнопку Create.<\\/p><p>Откроется редактор (мастер) сводной таблицы (pivot table).<\\/p><p>&nbsp;<\\/p><p>Шаг 2. Добавьте группировку по курьеру<\\/p><p>В редакторе сводной таблицы найдите область Rows (Строки).<\\/p><p>Нажмите Add (Добавить) и выберите:<\\/p><p>Курьер<\\/p><p>&nbsp;<\\/p><p>Теперь Google Таблицы будут создавать отдельную строку отчёта для каждого значения поля Курьер.<\\/p><p>&nbsp;<\\/p><p>Шаг 3. Добавьте сумму продаж<\\/p><p>В редакторе найдите область Values (Значения).<\\/p><p>Нажмите Add (Добавить) и выберите:<\\/p><p>Сумма_Заказа_Тг<\\/p><p>&nbsp;<\\/p><p>После добавления Google Таблицы могут автоматически выбрать способ расчёта.&nbsp;<\\/p><p>В настройке этого показателя выберите:<\\/p><p>Summarize&nbsp;by (Сводить по) → SUM<\\/p><p>То есть:<\\/p><p>Строки → Курьер<\\/p><p>Значения → Сумма_Заказа_Тг<\\/p><p>Сводить по → SUM<\\/p><p>В результате получится отчёт, в котором каждая строка соответствует курьеру, а рядом отображается общая сумма заказов этого курьера.<\\/p><p>Обратите внимание, также, на общую сумму.<\\/p><p>Сейчас в неё входят и суммы отменённых заказов то же.<\\/p><p>&nbsp;<\\/p><p>Шаг 4. Отфильтруйте отменённые заказы<\\/p><p>Для отчёта именно о выполненных продажах добавьте в область Filtres (Фильтры) поле:<\\/p><p>Статус_Заказа<\\/p><p>(столбец H листа «Заказы»).<\\/p><p>В настройках фильтра оставьте:<\\/p><p>Доставлено<\\/p><p>и исключите:<\\/p><p>Отменено<\\/p><p>Теперь сумма в сводной таблице будет рассчитываться только по доставленным заказам.<\\/p><p>&nbsp;<\\/p><p>Получается полный набор настроек:<\\/p><p>Фильтры → Статус_Заказа → Доставлено<\\/p><p>Строки → Курьер<\\/p><p>Значения → Сумма_Заказа_Тг → SUM<\\/p><p>Это уже полноценный сводный отчёт по фактическим продажам курьеров.<\\/p><p>&nbsp;<\\/p><p><strong>Как думать при работе со сводной таблицей<\\/strong><\\/p><p>Главное — сначала сформулировать бизнес-вопрос, а затем определить, какие реальные поля датасета нужны для ответа.<\\/p><p>&nbsp;<\\/p><p>Вопрос: «Какую сумму доставленных заказов обслужил каждый курьер?»<\\/p><p>Используем:<\\/p><p>Фильтры: Статус_Заказа → оставить Доставлено;<\\/p><p>Строки: Курьер;<\\/p><p>Значения: Сумма_Заказа_Тг;<\\/p><p>Операция: SUM .<\\/p><p>То есть сводная таблица группирует данные из столбца I Курьер, а значения берёт из столбца E Сумма_Заказа_Тг.<\\/p><p>&nbsp;<\\/p><p>Вопрос: «Сколько доставленных заказов обработал каждый курьер?»<\\/p><p>Теперь нас интересует не сумма денег, а количество заказов.<\\/p><p>Используем:<\\/p><p>Фильтры: Статус_Заказа → Доставлено;<\\/p><p>Строки: Курьер;<\\/p><p>Значения: ID_Заказа;<\\/p><p>Операция: COUNTA или другой доступный вариант подсчёта непустых значений.<\\/p><p>Здесь используется столбец A ID_Заказа, потому что каждый заказ имеет собственный идентификатор.<\\/p><p>Получается:<\\/p><p>Фильтры → Статус_Заказа → Доставлено<\\/p><p>Строки → Курьер<\\/p><p>Значения → ID_Заказа → COUNTA<\\/p><p>Теперь в отчёте можно увидеть, сколько доставленных заказов приходится на каждого курьера.<\\/p><p>&nbsp;<\\/p><p>Вопрос: «Сколько товаров было доставлено каждым курьером?»<\\/p><p>Это уже другой показатель.<\\/p><p>Используем:<\\/p><p>Фильтры: Статус_Заказа → Доставлено;<\\/p><p>Строки: Курьер;<\\/p><p>Значения: Количество;<\\/p><p>Операция: SUM.<\\/p><p>Здесь используется столбец D Количество. Он показывает количество единиц товара в конкретном заказе.<\\/p><p>Получается:<\\/p><p>Фильтры → Статус_Заказа → Доставлено<\\/p><p>Строки → Курьер<\\/p><p>Значения → Количество → SUM<\\/p><p>Это показывает уже не количество заказов и не сумму продаж, а общее количество единиц товара в доставленных заказах каждого курьера.<\\/p><p>&nbsp;<\\/p><p>Таким образом, одна и та же исходная таблица «Заказы» позволяет строить разные отчёты. Меняется не исходный датасет, а вопрос и соответствующая настройка сводной таблицы.<\\/p><p>Сводная таблица не создаёт новую базу данных. Она строит итоговый отчёт на основании выбранного диапазона исходных данных.<\\/p><p>В нашем случае основные поля для первого отчёта такие:<\\/p><p>I — Курьер → по этому полю группируем записи.<\\/p><p>E — Сумма_Заказа_Тг → этот показатель суммируем.<\\/p><p>H — Статус_Заказа → используем для отбора только доставленных заказов.<\\/p><p>A — ID_Заказа → используем, если нужно посчитать количество заказов.<\\/p><p>D — Количество → используем, если нужно посчитать количество проданных единиц товара.<\\/p><p>&nbsp;<\\/p><p><strong>Что нужно запомнить<\\/strong><\\/p><p>XLOOKUP используется, когда нужно найти значение по ключу в одном диапазоне и вернуть связанное значение из другого диапазона.<\\/p><p>В нашем датасете таким ключом является ID_Товара.<\\/p><p>Связь выглядит так:<\\/p><p>Заказы.ID_Товара → Меню и Товары.ID_Товара → нужное поле из Меню и Товары<\\/p><p>С помощью XLOOKUP можно получить название, цену и другие сведения из таблицы Меню и Товары, являющуюся, фактически, справочником товаров.<\\/p><p>&nbsp;<\\/p><p>Сводная таблица используется уже для другого действия: она группирует множество строк и быстро показывает итоговые показатели.<\\/p><p>Для отчёта по курьерам:<\\/p><p>Строки → Курьер<\\/p><p>Значения → показатель, который нужно суммировать или считать<\\/p><p>&nbsp;<\\/p><p>Эти два инструмента решают разные задачи: XLOOKUP помогает соединить сведения из разных листов, а Pivot Table помогает превратить большое количество строк в понятный итоговый отчёт.<\\/p>\",\"tests\":[{\"question\":\"Какую бизнес-задачу удобнее всего решать с помощью сводной таблицы?\",\"answers\":[\"Искать способы увеличения прибыли\",\"Группировать заказы и быстро получать итоги ✓\",\"Создавать новые заказы с автоматической скидкой\",\"Формировать для каждого заказа сводные данные\"],\"correct\":null},{\"question\":\"Куда следует добавить поле Курьер, если нужно получить отдельную строку отчёта для каждого курьера?\",\"answers\":[\"В область «Строки» ✓\",\"В область «Столбцы»\",\"В область «Фильтры»\",\"В область «Значения»\"],\"correct\":null},{\"question\":\"Какую операцию следует выбрать для Сумма_Заказа_Тг, если требуется узнать общую сумму заказов каждого курьера?\",\"answers\":[\"COUNT\",\"SUMMA\",\"SUM ✓\",\"TOTAL\"],\"correct\":null},{\"question\":\"В формуле стоимости со скидкой используется выражение Цена × Количество × (1 − Скидка). Что показывает его результат?\",\"answers\":[\"Стоимость товара до скидки\",\"Стоимость товара без скидки\",\"Стоимость заказа после применения скидки ✓\",\"Размер скидки в тенге\"],\"correct\":null},{\"question\":\"Почему при XLOOKUP важно правильно выбрать диапазон поиска?\",\"answers\":[\"Потому что XLOOKUP ищет нужный ключ именно в указанном диапазоне ✓\",\"Потому что диапазон автоматически сортирует заказы по дате\",\"Потому что XLOOKUP всегда использует только первый столбец листа\",\"Потому что диапазон определяет формат валюты\"],\"correct\":null}],\"lab\":\"<p>Связывание таблицы заказов с меню и составление отчёта по категориям и каналам поступления заказов.<\\/p><p>В этой работе нужно самостоятельно объединить сведения из двух листов и подготовить итоговый управленческий отчёт.<\\/p><p>При создании сводных таблиц - создавайте новые сводные таблицы, а не меняйте уже имеющиеся.<\\/p><p>&nbsp;<\\/p><p>Задача 1. Добавьте название и цену товара к заказам<\\/p><p>В листе «Заказы», между столбцами C&nbsp;и D&nbsp;вставьте 2 новых столбца для наименования и цены товара.<\\/p><p>Полностью самостоятельно, не подглядывая в лекцию, заполните столбцы названиями и ценами соответствующих товаров.<\\/p><p>Проверьте несколько результатов вручную по листу «Меню и Товары».<\\/p><p>&nbsp;<\\/p><p>Задача 2. Анализ продаж по категориям товаров<\\/p><p>Используя листы «Заказы» и «Меню и Товары», подготовьте отчёт о продажах по категориям товаров.<\\/p><p>Сначала с помощью XLOOKUP добавьте в таблицу «Заказы», новым столбцом, категорию каждого товара.<\\/p><p>Затем создайте сводную таблицу и определите, какая категория товаров принесла наибольшую сумму продаж.<\\/p><p>Самостоятельно определите, какие поля необходимо использовать в сводной таблице и какую операцию выбрать для расчёта итоговой суммы.<\\/p><p>Не забудьте исключить отменённые заказы.<\\/p><p>&nbsp;<\\/p><p>Задача 3. Сравнение каналов поступления заказов<\\/p><p>Создайте сводную таблицу, которая позволит сравнить количество заказов, поступивших через разные каналы.<\\/p><p>Определите, какой канал обеспечил наибольшее количество заказов.<\\/p><p>&nbsp;<\\/p><p>Задача 4. Сравнение среднего чека по каналам<\\/p><p>Создайте сводную таблицу для сравнения средней суммы заказа в зависимости от канала поступления.<\\/p><p>Определите, через какой канал поступает заказ с наибольшей средней суммой.<\\/p><p>Для выполнения задачи самостоятельно определите, нужны ли дополнительные фильтры и какие именно.<\\/p><p>Дополнительно:<\\/p><p>Сделайте так чтобы суммы отображались без дробной части (целое число - сумма в тенге)<\\/p><p>&nbsp;<\\/p><p>Задача 5. Сделайте управленческий вывод<\\/p><p>На основании сводной таблицы из теоретической части урока определите:<\\/p><p>какой курьер выполнил больше всего заказов;<\\/p><p>какой курьер обеспечил наибольшую сумму продаж.<\\/p><p>Если лидеры по количеству заказов и сумме продаж разные, укажите это отдельно.<\\/p><p>На основании сводных таблиц из лабораторной работы сделайте вывод:<\\/p><p>Какая категория в меню даёт наибольшую сумму продаж;<\\/p><p>Какая наименьшую;<\\/p><p>Какой канал поступления заказов даёт наибольшую сумму продаж;<\\/p><p>Какой наименьшую.<\\/p><p>&nbsp;<\\/p><p>&nbsp;<\\/p><p>После выполнения всех заданий лабораторной работы - удалите все изменения в датасете. Удалите добавленные столбцы и сводные таблицы. Т.е. верните датасет в исходное состояние.<\\/p><p>Можно поступить проще - заново получить и скопировать себе исходный датасет.<\\/p>\"}');
INSERT INTO `lessons` (`id`, `section_id`, `title_ru`, `slug`, `lesson_order`, `content`) VALUES
(5, 1, '1.4. Визуализация данных и наглядная отчетность', 'charts', 4, '{\"theory\":\"<p>До этого урока мы использовали Google Таблицы в основном для расчётов и создания сводных таблиц. Теперь научимся представлять результаты этих расчётов в графическом виде.<\\/p><p>&nbsp;<\\/p><p>Числа в таблице удобны для точного анализа, но руководителю не всегда нужно (есть время) просматривать десятки строк. Хорошо построенная диаграмма позволяет быстрее увидеть разницу между категориями, понять, какой день был наиболее результативным, и заметить изменение выручки во времени.<\\/p><p>&nbsp;<\\/p><p>В этом уроке будем работать с тремя видами диаграмм:<\\/p><p>круговой диаграммой — для показа долей;<\\/p><p>столбчатой диаграммой — для сравнения показателей между категориями;<\\/p><p>линейной диаграммой — для отображения изменения показателя во времени.<\\/p><p>&nbsp;<\\/p><p>Все практические примеры выполняются на учебном датасете службы доставки.<\\/p><p>&nbsp;<\\/p><p>Для визуализации продаж нам понадобятся прежде всего два листа: «Меню и Товары» и &nbsp;«Заказы».<\\/p><p>&nbsp;<\\/p><p>В предыдущем уроке мы уже использовали XLOOKUP для связывания листов и сводные таблицы для группировки заказов. Поэтому в этом уроке будем использовать эти уже знакомые возможности как основу подготовки данных для диаграмм.<\\/p><p>Для управленческого отчёта важно отдельно учитывать поле «Статус_Заказа».&nbsp;<\\/p><p>В датасете встречаются доставленные и отменённые заказы. Если мы хотим показать фактическую выручку, в отчёт следует включать только доставленные заказы.<\\/p><p>&nbsp;<\\/p><p>Почему диаграмма строится не непосредственно по исходной таблице ?<\\/p><p>Новичку часто хочется сразу выделить весь лист «Заказы» и нажать кнопку создания диаграммы. Это не всегда приводит к полезному результату.<\\/p><p>В исходной таблице каждая строка представляет отдельный заказ.&nbsp;<\\/p><p>Руководителю же чаще нужен итог:<\\/p><p>выручка по категориям;<\\/p><p>выручка по дням недели;<\\/p><p>выручка по датам;<\\/p><p>продажи по товарам.<\\/p><p>&nbsp;<\\/p><p>Поэтому сначала нужно подготовить небольшую итоговую таблицу.<\\/p><p>Например, вместо 100 строк заказов можно получить таблицу из нескольких строк:<\\/p><figure class=\\\"table\\\"><table><tbody><tr><td>Категория&nbsp;<\\/td><td>Выручка<\\/td><\\/tr><tr><td>Пицца&nbsp;<\\/td><td>91 900<\\/td><\\/tr><tr><td>Суши и Роллы<\\/td><td>72 700<\\/td><\\/tr><tr><td>Напитки&nbsp;<\\/td><td>20 250<\\/td><\\/tr><\\/tbody><\\/table><\\/figure><p>А уже эту небольшую таблицу превратить в диаграмму.<\\/p><p>&nbsp;<\\/p><p>Это важный принцип визуализации:<\\/p><p>сначала сформулировать бизнес-вопрос, затем подготовить итоговые данные и только после этого выбирать подходящий тип диаграммы.<\\/p><p>&nbsp;<\\/p><p><strong>Круговая диаграмма<\\/strong><\\/p><p>Круговая диаграмма показывает, какую долю от общей суммы занимает каждая категория.<\\/p><p>Она особенно удобна, когда категорий немного и нужно показать их соотношение.<\\/p><p>Например, в нашем датасете рассмотрим три категории:<\\/p><p>Пицца;<\\/p><p>Суши и Роллы;<\\/p><p>Напитки.<\\/p><p>Для фактически доставленных заказов сумма продаж этих категорий составляет:<\\/p><p>Пицца — 91 900 тг;<\\/p><p>Суши и Роллы — 72 700 тг;<\\/p><p>Напитки — 20 250 тг.<\\/p><p>Общая сумма этих трёх категорий — 184 850 тг.<\\/p><p>Если представить эти значения в виде круговой диаграммы, становится хорошо видно, что наибольшую долю занимает пицца.<\\/p><p>Доля пиццы составляет примерно 49,7%, суши и роллов — 39,3%, напитков — 11,0%.<\\/p><p>При этом важно понимать: круговая диаграмма показывает доли только выбранного набора данных.&nbsp;<\\/p><p>В данном примере мы сравниваем именно три категории, а не весь ассортимент службы доставки.<\\/p><p>&nbsp;<\\/p><p>Подготовка данных для круговой диаграммы<\\/p><p>Для построения круговой диаграммы нам нужно получить сумму доставленных заказов по категориям товаров.<\\/p><p>В исходном листе «Заказы» нет отдельного столбца «Категория». На этом листе есть ID_Товара, а название и категория товара находятся в листе «Меню и Товары».<\\/p><p>Поэтому в данном случае не нужно пытаться использовать SUMIF непосредственно на листе «Заказы». Вместо этого воспользуемся сводной таблицей, которую изучили в предыдущем уроке.<\\/p><p>Сводная таблица позволит одновременно:<\\/p><p>- связать данные о товаре с его категорией;<\\/p><p>- сгруппировать заказы по категориям;<\\/p><p>- исключить отменённые заказы;<\\/p><p>- посчитать общую сумму доставленных заказов по каждой категории.<\\/p><p>&nbsp;<\\/p><p>Подготовка данных для сводной таблицы<\\/p><p>Сначала нам нужно добавить категорию товара к каждой записи заказа.<\\/p><p>Перейдите на лист «Заказы».<\\/p><p>Справа от существующих данных используйте дополнительный столбец (например L).<\\/p><p>Назовите его:<\\/p><p>Категория<\\/p><p>В первой строке данных нового столбца используйте XLOOKUP.<\\/p><p>На листе «Заказы» ID_Товара находится в столбце C.<\\/p><p>На листе «Меню и Товары»:<\\/p><p>столбец A — ID_Товара;<\\/p><p>столбец C — Категория.<\\/p><p>Поэтому для первой строки заказа используйте:<\\/p><p><code>=XLOOKUP(C2,\'Меню и Товары\'!A:A,\'Меню и Товары\'!C:C)<\\/code><\\/p><p>Формула означает:<\\/p><p>C2 — ID товара текущего заказа;<\\/p><p>\'Меню и Товары\'!A:A — диапазон, в котором ищем ID товара;<\\/p><p>\'Меню и Товары\'!C:C — диапазон, из которого возвращаем категорию.<\\/p><p>После ввода формулы заполните её вниз для остальных заказов.<\\/p><p>Теперь у каждой строки листа «Заказы» есть категория соответствующего товара.<\\/p><p>&nbsp;<\\/p><p>Создание сводной таблицы по категориям.<\\/p><p>Перед созданием - выделите всю таблицу «Заказы».<\\/p><p>Теперь создайте новую сводную таблицу на основании листа «Заказы».<\\/p><p>Разместите новую сводную таблицу на новом листе.<\\/p><p>В редакторе сводной таблицы настройте поля следующим образом.<\\/p><p>В область «Фильтры» добавьте: Статус_Заказа;<\\/p><p>В настройках фильтра оставьте только: Доставлено;<\\/p><p>В область «Строки» добавьте: Категория;<\\/p><p>В область «Значения» добавьте: Сумма_Заказа_Тг;<\\/p><p>Для показателя «Сумма_Заказа_Тг» выберите операцию: SUM;<\\/p><p>&nbsp;<\\/p><p>Теперь Google Таблицы сгруппируют доставленные заказы по категориям и самостоятельно рассчитают общую сумму продаж каждой категории.<\\/p><p>&nbsp;<\\/p><p>Построение круговой диаграммы<\\/p><p>Теперь сводная таблица уже содержит именно те данные, которые нужны для визуализации.<\\/p><p>Выделите в сводной таблице названия категорий и итоговые суммы продаж.<\\/p><p>Создайте диаграмму (Insert&nbsp;→ Chart).<\\/p><p>В панели настройки диаграммы (Chart&nbsp;editor) выберите тип:<\\/p><p>Круговая диаграмма (Pie&nbsp;chart) (pie - пирог, торт).<\\/p><p>Google Таблицы будут использовать названия категорий как элементы диаграммы, а суммы продаж — для определения размера каждого сектора.<\\/p><p>&nbsp;<\\/p><p>Проверьте, что:<\\/p><p>категории используются как подписи;<\\/p><p>сумма продаж используется как числовой показатель;<\\/p><p>в расчётах учитываются только заказы со статусом «Доставлено».<\\/p><p>&nbsp;<\\/p><p>Настройка подписей и легенды<\\/p><p>Для круговой диаграммы подписи данных включены по умолчанию.<\\/p><p>В качестве подписей удобно использовать процентное соотношение категорий. Тогда руководитель сможет сразу увидеть, какую долю продаж занимает каждая категория.<\\/p><p>Например, если одна категория занимает почти половину всей суммы, это будет заметно не только по размеру сектора, но и по процентной подписи.<\\/p><p>Заголовок диаграммы должен объяснять, что именно показывает график.<\\/p><p>Например:<\\/p><p>«Выручка по категориям товаров»<\\/p><p>Такой заголовок лучше, чем просто «Продажи», потому что сразу сообщает читателю, какой показатель и в каком разрезе представлен.<\\/p><p>&nbsp;<\\/p><p>В результате мы выполнили следующую последовательность:<\\/p><p>Заказы → XLOOKUP → Категория → Сводная таблица → фильтр «Доставлено» → сумма продаж по категориям → круговая диаграмма.<\\/p><p>&nbsp;<\\/p><p>Это хороший пример рабочего процесса бизнес-аналитики: сначала подготовить данные, затем получить итоговый показатель и только после этого представить его графически.<\\/p><p>Не следует строить диаграмму непосредственно по 100 строкам исходных заказов, если бизнес-вопрос касается итоговой выручки по категориям. Сначала нужно получить агрегированные данные, которые непосредственно отвечают на этот вопрос.<\\/p><p>&nbsp;<\\/p><p>После построения и анализа диаграммы - удалите диаграмму, сводную таблицу и столбец с категориями.<\\/p><p>&nbsp;<\\/p><p>&nbsp;<\\/p><p><strong>Столбчатая диаграмма<\\/strong><\\/p><p>Столбчатая диаграмма хорошо подходит для сравнения нескольких значений.<\\/p><p>В нашем случае с её помощью можно сравнить объём продаж по дням недели.<\\/p><p>&nbsp;<\\/p><p>Как получить день недели ?<\\/p><p>В листе «Заказы» дата и время заказа находятся в столбце &nbsp;J &nbsp;«Дата_Заказа».<\\/p><p>Для построения отчёта по дням недели нужно получить название дня из даты.<\\/p><p>Для этого можно создать дополнительный учебный столбец «День_Недели». Это временный вспомогательный столбец, необходимый только для данного анализа.<\\/p><p>В ячейке этого столбца для первой строки заказа можно использовать функцию TEXT, например:<\\/p><p>=TEXT(J2,\\\"dddd\\\")<\\/p><p>Функция TEXT здесь используется только для того, чтобы преобразовать дату в название дня недели, для выполнения задачи текущего урока. Запоминать его как отдельный аналитический инструмент не требуется.<\\/p><p>&nbsp;<\\/p><p>Создайте сводную таблицу<\\/p><p>Выделите данные листа «Заказы», включая новый столбец&nbsp; K «День_Недели».<\\/p><p>Вставьте сводную таблицу на новом листе.<\\/p><p>В область «Фильтры» добавьте поле: Статус_Заказа;<\\/p><p>В фильтре оставьте только значение: Доставлено;<\\/p><p>В область «Строки» добавьте: День_Недели;<\\/p><p>В область «Значения» добавьте: Сумма_Заказа_Тг;<\\/p><p>Для поля «Сумма_Заказа_Тг» установите способ расчёта: SUM.<\\/p><p>Для учебного датасета результат должен соответствовать следующим значениям:<\\/p><p>&nbsp;<\\/p><figure class=\\\"table\\\"><table><tbody><tr><td><i>День_Недели<\\/i><\\/td><td>SUM of Сумма_Заказа_Тг<\\/td><\\/tr><tr><td>Friday<\\/td><td>53900<\\/td><\\/tr><tr><td>Monday<\\/td><td>47800<\\/td><\\/tr><tr><td>Saturday<\\/td><td>77150<\\/td><\\/tr><tr><td>Sunday<\\/td><td>39550<\\/td><\\/tr><tr><td>Thursday<\\/td><td>31300<\\/td><\\/tr><tr><td>Tuesday<\\/td><td>40950<\\/td><\\/tr><tr><td>Wednesday<\\/td><td>47300<\\/td><\\/tr><\\/tbody><\\/table><\\/figure><p>&nbsp;<\\/p><p>Если Google Таблицы расположили дни недели не в порядке от понедельника до воскресенья - для данного учебного примера оставьте так. Расположить дни недели в правильном порядке можно, но это излишне усложнит наш учебный пример.&nbsp;<\\/p><p>&nbsp;<\\/p><p>Создайте столбчатую диаграмму.<\\/p><p>Выделите в сводной таблице столбцы:<\\/p><p>День_Недели<\\/p><p>и<\\/p><p>SUM Сумма_Заказа_Тг.<\\/p><p>Выберите:<\\/p><p>Insert&nbsp;→ Chart<\\/p><p>Google Таблицы создадут, по умолчанию, столбчатую диаграмму.<\\/p><p>На горизонтальной оси должны находиться дни недели.<\\/p><p>На вертикальной оси должна находиться сумма продаж в тенге.<\\/p><p>&nbsp;<\\/p><p>Добавьте подписи данных.<\\/p><p>Дважды щёлкните по диаграмме.<\\/p><p>Справа появится&nbsp;Chart&nbsp;Editor (Редактор диаграммы).<\\/p><p>Перейдите на вкладку&nbsp;Customize (Настроить).<\\/p><p>Откройте вкладку&nbsp;Series (Ряды или Серии).<\\/p><p>Промотайте вниз.<\\/p><p>Отметьте&nbsp;checkbox&nbsp;Data&nbsp;Lables&nbsp;(Подписи данных).<\\/p><p>Теперь над каждым столбцом будет показана точная сумма продаж.<\\/p><p>Это удобно, когда нужно не только увидеть, какой столбец выше, но и узнать конкретное значение.<\\/p><p>Однако если столбцов много, подписи могут сделать диаграмму перегруженной. Поэтому всегда проверяйте читаемость готового отчёта.<\\/p><p>&nbsp;<\\/p><p>Настройте заголовок.<\\/p><p>Дважды щёлкните по заголовку диаграммы и введите более правильный заголовок&nbsp;<\\/p><p>\\\"Выручка по дням недели\\\"<\\/p><p>Сделайте двойной щелчок по заголовку вертикальной оси и введите:<\\/p><p>\\\"Выручка, тг\\\".<\\/p><p>Сделайте двойной щелчок по заголовку горизонтальной оси и введите:<\\/p><p>\\\"День недели\\\"<\\/p><p>&nbsp;<\\/p><p>Что показывает готовая диаграмма<\\/p><p>После настройки диаграммы сразу видно, что в учебном датасете максимальная выручка от доставленных заказов приходится на субботу — 77 150 тг.<\\/p><p>Минимальная выручка приходится на четверг — 31 300 тг.<\\/p><p>&nbsp;<\\/p><p>После завершения работы с диаграммой, на листе \\\"Заказы\\\" удалите временный столбец \\\"День Недели\\\".<\\/p><p>&nbsp;<\\/p><p><strong>Линейная диаграмма<\\/strong><\\/p><p>Линейная диаграмма используется, прежде всего, для показа изменения показателя во времени.<\\/p><p>Например, руководителю может быть интересно не только, сколько было продаж всего, но и как менялась выручка в течение периода.<\\/p><p>Для такого отчёта нам понадобятся:<\\/p><p>Дата_Заказа;<\\/p><p>Сумма_Заказа_Тг;<\\/p><p>Статус_Заказа.<\\/p><p>&nbsp;<\\/p><p>Сначала нужно получить итоговую сумму доставленных заказов для каждой даты.<\\/p><p>В нашем датасете даты заказов находятся в периоде с июня по август 2026 года. При этом заказы есть не на каждый календарный день. Это нормально.<\\/p><p>Подготовленная таблица должна иметь примерно такой принцип:<\\/p><figure class=\\\"table\\\"><table><tbody><tr><td>Дата<\\/td><td>Выручка<\\/td><\\/tr><tr><td>03.06.2026&nbsp;<\\/td><td>&nbsp;11 950<\\/td><\\/tr><tr><td>06.06.2026&nbsp;<\\/td><td>&nbsp;2 300<\\/td><\\/tr><tr><td>07.06.2026&nbsp;<\\/td><td>&nbsp;3 200<\\/td><\\/tr><\\/tbody><\\/table><\\/figure><p>и так далее по датам, для которых есть доставленные заказы.<\\/p><p>&nbsp;<\\/p><p>Здесь важно не перепутать отдельный заказ и итог за день. Если в один день было несколько заказов, их суммы должны быть объединены в одно значение за этот день.<\\/p><p>Для такой подготовки удобно использовать сводную таблицу.<\\/p><p>&nbsp;<\\/p><p>Создайте новую сводную таблицу на основании листа «Заказы».<\\/p><p>В область «Фильтры» добавьте: Статус_Заказа → Доставлено.<\\/p><p>В область «Строки» добавьте: Дата_Заказа.<\\/p><p>В область «Значения» добавьте: Сумма_Заказа_Тг → SUM.<\\/p><p>В результате Google Таблицы сгруппируют заказы по датам и посчитают общую сумму доставленных заказов для каждой даты.<\\/p><p>&nbsp;<\\/p><p>После этого выделите получившуюся таблицу и создайте линейную диаграмму.<\\/p><p>Insert&nbsp;→ Chart<\\/p><p>В Chart&nbsp;Editor, на вкладке Setup&nbsp;выберите Chart&nbsp;Type&nbsp;→ Line&nbsp;Chart (линейная диаграмма)<\\/p><p>На горизонтальной оси будет время.<\\/p><p>На вертикальной оси — выручка.<\\/p><p>Линия позволит увидеть периоды роста и снижения продаж.<\\/p><p>&nbsp;<\\/p><p><strong>Важное отличие трёх диаграмм<\\/strong><\\/p><p>Выбор диаграммы зависит от бизнес-вопроса.<\\/p><p>Если вопрос звучит:<\\/p><p>«Какую долю занимает каждая категория?»<\\/p><p>подходит круговая диаграмма.<\\/p><p>Если вопрос:<\\/p><p>«Как отличаются продажи между несколькими группами?»<\\/p><p>подходит столбчатая диаграмма.<\\/p><p>Если вопрос:<\\/p><p>«Как менялась выручка со временем?»<\\/p><p>подходит линейная диаграмма.<\\/p><p>&nbsp;<\\/p><p>Нельзя считать один тип диаграммы универсальным для всех задач.<\\/p><p>Например, линейная диаграмма плохо подходит для демонстрации долей категорий, а круговая диаграмма плохо показывает изменение выручки по датам.<\\/p><p>&nbsp;<\\/p><p><strong>Как проверить готовую диаграмму<\\/strong><\\/p><p>Перед тем как использовать диаграмму в отчёте, проверьте несколько вещей.<\\/p><p>- Правильно ли выбран диапазон данных?<\\/p><p>- Не попали ли в расчёт отменённые заказы?<\\/p><p>- Правильно ли определены категории и значения?<\\/p><p>- Соответствует ли тип диаграммы поставленному вопросу?<\\/p><p>- Понятны ли подписи?<\\/p><p>- Видна ли легенда, если она нужна?<\\/p><p>- Можно ли определить показатель без дополнительного объяснения?<\\/p><p>Если хотя бы на один вопрос ответ отрицательный, диаграмму нужно проверить и при необходимости изменить.<\\/p><p>&nbsp;<\\/p><p><strong>Что нужно запомнить<\\/strong><\\/p><p>Диаграмма — это графическое представление подготовленных данных.<\\/p><p>Перед построением диаграммы нужно определить бизнес-вопрос и подготовить итоговую таблицу.<\\/p><p>Круговая диаграмма показывает доли.<\\/p><p>Столбчатая диаграмма удобна для сравнения категорий или групп.<\\/p><p>Линейная диаграмма показывает изменение показателя во времени.<\\/p><p>Подписи данных помогают увидеть точные значения.<\\/p><p>Легенда помогает определить, какой элемент графика соответствует конкретной категории.<\\/p><p>Главная задача визуализации — не украсить таблицу, а сделать бизнес-информацию понятной с первого взгляда.<\\/p><p>&nbsp;<\\/p><p>После завершения работы с диаграммами - удалите все изменения и сводные таблицы.<\\/p><p>Верните датасет в исходное состояние или сделайте новую копию с исходного варианта.<\\/p>\",\"tests\":[{\"question\":\"Какой принцип следует использовать перед созданием диаграммы?\",\"answers\":[\"Сначала выбрать тип диаграммы, а затем искать подходящие данные\",\"Сначала сформулировать бизнес-вопрос и подготовить данные ✓\",\"Всегда строить график по всей исходной таблице\",\"Сначала изменить оформление таблицы, а потом определить показатель\"],\"correct\":null},{\"question\":\"Какой тип диаграммы наиболее удобен для сравнения нескольких категорий между собой?\",\"answers\":[\"Круговая диаграмма\",\"Линейная диаграмма\",\"Диаграмма без осей\",\"Столбчатая диаграмма ✓\"],\"correct\":null},{\"question\":\"Какой тип диаграммы лучше всего подходит для отображения доли каждой категории в общей сумме?\",\"answers\":[\"Круговая диаграмма ✓\",\"Линейная диаграмма\",\"Столбчатая диаграмма\",\"Точечная диаграмма\"],\"correct\":null},{\"question\":\"Какой тип диаграммы лучше всего показывает изменение показателя во времени?\",\"answers\":[\"Круговая диаграмма\",\"Столбчатая диаграмма\",\"Линейная диаграмма ✓\",\"Кольцевая диаграмма\"],\"correct\":null},{\"question\":\"Какой вариант лучше всего подходит для отображения выручки компании по месяцам в течение года?\",\"answers\":[\"Круговая диаграмма\",\"Линейная диаграмма ✓\",\"Диаграмма без осей\",\"Круговая диаграмма с одной категорией\"],\"correct\":null},{\"question\":\"Какой принцип является правильным при создании наглядного бизнес-отчёта?\",\"answers\":[\"Использовать как можно больше диаграмм и подписей\",\"В первую очередь выбирать диаграмму с наиболее привлекательным внешним видом.\",\"Сначала подготовить данные и определить задачу, а затем выбрать подходящий тип диаграммы ✓\",\"Сначала выбрать подходящий тип диаграммы, а затем добавить в неё подходящие бизнес-данные.\"],\"correct\":null}],\"lab\":\"<p>В этой лабораторной работе нужно самостоятельно подготовить графический отчёт о самых популярных позициях меню службы доставки.<\\/p><p>Задания используют материал текущего урока и ранее изученные возможности Google Таблиц: сводные таблицы, XLOOKUP и работу с данными листов «Заказы» и «Меню и Товары».<\\/p><p>Не изменяйте исходные данные. Для отчёта создавайте отдельные сводные таблицы и вспомогательные области.<\\/p><p>&nbsp;<\\/p><p>Задача 1. Подготовьте данные о позициях меню<\\/p><p>Используя листы «Заказы» и «Меню и Товары», подготовьте таблицу, в которой для каждой позиции меню будут видны:<\\/p><p>Наименование;<\\/p><p>Общее количество проданных единиц.<\\/p><p>Для анализа продаж учитывайте только заказы со статусом «Доставлено».<\\/p><p>&nbsp;<\\/p><p>Задача 2. Определите самые популярные позиции<\\/p><p>На основании подготовленной таблицы, создайте новую таблицу, где будет только пять позиций меню с наибольшим количеством проданных единиц.<\\/p><p>Расположите позиции от наиболее популярной к менее популярной.<\\/p><p>&nbsp;<\\/p><p>Задача 3. Постройте столбчатую диаграмму популярных позиций<\\/p><p>На основании пяти выбранных позиций создайте столбчатую диаграмму.<\\/p><p>На горизонтальной оси должны находиться названия товаров.<\\/p><p>На вертикальной оси — количество проданных единиц.<\\/p><p>Настройте заголовок диаграммы так, чтобы было понятно, что она показывает.<\\/p><p>Проверьте, что подписи товаров читаются полностью или максимально понятно.<\\/p><p>&nbsp;<\\/p><p>Главная цель лабораторной работы — научиться самостоятельно проходить весь путь от исходных данных до понятного управленческого графика:<\\/p><p>данные → группировка → итоговый показатель → выбор подходящей диаграммы → настройка → вывод.<\\/p>\"}'),
(6, 4, '2.1. Создание Telegram-бота через BotFather и подключение к Aimylogic', 'botfather-and-aimylogic', 1, '{\"theory\":\"<p>Telegram — это мессенджер, в котором пользователи обмениваются сообщениями. Кроме обычных аккаунтов пользователей,&nbsp;Telegram позволяет создавать специальных программных помощников — ботов.<\\/p><p>Telegram-бот — это аккаунт, которым управляет программа.&nbsp;<br>Пользователь пишет боту сообщение или нажимает кнопку,&nbsp;Telegram передаёт действие бота в подключённый сервис, а сервис определяет, какой ответ нужно показать пользователю.<\\/p><p>&nbsp;<\\/p><p>В этом уроке мы создадим самого простого рабочего бота службы доставки.&nbsp;<br>В конце урока бот должен не просто существовать и быть подключённым к&nbsp;Aimylogic, а реально провести короткий диалог:<\\/p><p>Пользователь открывает бота → бот показывает приветствие и кнопку → пользователь нажимает кнопку → бот показывает второе сообщение.<\\/p><p>Это будет первый законченный сценарий нашего будущего бота.<\\/p><p>BotFather и создание&nbsp;Telegram-бота<\\/p><p>&nbsp;<\\/p><p>Для создания&nbsp;Telegram-ботов используется официальный служебный бот&nbsp;Telegram —&nbsp;BotFather.<\\/p><p>BotFather создаёт новых ботов и позволяет изменять их основные настройки.&nbsp;<br>При создании бота он выдаёт&nbsp;API-токен — секретный ключ, который используется внешними сервисами для подключения к&nbsp;Telegram Bot API.<\\/p><p>&nbsp;<\\/p><p>Нужно различать три понятия.<\\/p><p>&nbsp;<\\/p><p>Отображаемое имя — название, которое видит пользователь.&nbsp;<br>Например:<\\/p><p><code>Доставка Петропавл<\\/code>&nbsp;<\\/p><p>&nbsp;<\\/p><p>Username — уникальное техническое имя бота.&nbsp;<br>Например:<\\/p><p><code>Ваша-Фамилия_delivery_bot<\\/code><\\/p><p>(Вместо Ваша-Фамилия вы подставите вашу фамилию маленькими английскими буквами)<\\/p><p>Username должен заканчиваться на&nbsp;bot.&nbsp;<br>Если выбранное имя уже занято,&nbsp;BotFather попросит указать другое.<\\/p><p>&nbsp;<\\/p><p>API-токен — секретный ключ доступа к&nbsp;Telegram-боту через&nbsp;Bot API.<\\/p><p>API-токен нельзя публиковать или отправлять посторонним.&nbsp;<br>Он используется для управления конкретным ботом.<\\/p><p>&nbsp;<\\/p><p><strong>Вход в&nbsp;Telegram<\\/strong><\\/p><p>Если вы знаете как открыть&nbsp;Telegram на учебном компьютере - авторизуйтесь, и переходите к созданию бота.<\\/p><p>&nbsp;<\\/p><p>Если нет, то:<\\/p><p>Откройте браузер.<\\/p><p>В адресной строке введите&nbsp;<code>web.telegram.org <\\/code>.<\\/p><p>Откройте&nbsp;Telegram Web.<\\/p><p>Появится&nbsp;QR-код.<\\/p><p>Возьмите смартфон, на котором открыт ваш&nbsp;Telegram.<\\/p><p>В&nbsp;Telegram откройте «Настройки».<\\/p><p>Откройте «Устройства».<\\/p><p>Нажмите «Подключить устройство».<\\/p><p>Отсканируйте&nbsp;QR-код на экране компьютера.<\\/p><p>Дождитесь загрузки списка чатов.<\\/p><p>Проверьте: в левой части окна отображается список ваших чатов.<br>Результат:&nbsp;Telegram открыт в браузере.<\\/p><p>&nbsp;<\\/p><p><strong>Создание бота через&nbsp;BotFather<\\/strong><\\/p><p>В&nbsp;Telegram откройте поле поиска.<\\/p><p>Введите <code>@BotFather<\\/code> .<\\/p><p>В результатах найдите официальный аккаунт&nbsp;BotFather.<\\/p><p>(обязательно с синей галочкой)<\\/p><p>Откройте чат.<\\/p><p>Нажмите&nbsp;START.<\\/p><p>В поле сообщения введите:<\\/p><p><code>\\/newbot<\\/code><\\/p><p>Отправьте команду.<\\/p><p>BotFather попросит указать имя нового бота.<\\/p><p>Введите:<\\/p><p>Доставка Петропавл<\\/p><p>Отправьте сообщение.<\\/p><p>Теперь&nbsp;BotFather попросит&nbsp;username.<\\/p><p>Введите, с вашей фамилией:<\\/p><p><code>&lt;Ваша-фамилия&gt;_delivery_bot&nbsp;<\\/code><\\/p><p>например:<\\/p><p><code>trump_delivery_bot<\\/code><\\/p><p>Отправьте сообщение.<\\/p><p>Если&nbsp;username занят, измените его.&nbsp;<br>Например:<\\/p><p><code>trump_2026_delivery_bot<\\/code><\\/p><p>&nbsp;<\\/p><p>После успешного создания&nbsp;BotFather покажет информацию о новом боте и&nbsp;API-токен.<\\/p><p>(желательно перевести и прочитать информацию о новом боте)<\\/p><p>Скопируйте&nbsp;API-токен.<\\/p><p>(API-токен имеет вид типа: 604771091:AAbWzM3ByOpMRkxJow-MDT4o7KwfnO0)<\\/p><p>Сохраните его временно в безопасном месте, чтобы использовать на следующем этапе.<br>(лучше всего себе на телефон или на свой&nbsp;Google-диск)<\\/p><p>Не оставляйте токен на учебном компьютере и не отправляйте его в общий чат.<\\/p><p>&nbsp;<\\/p><p>В окне сообщения вновь созданного бота найдите адрес (URL) бота и нажмите на него.<\\/p><p>(типа: t.me\\/trump_delivery_bot)<\\/p><p>В окне вашего бота нажмите кнопку&nbsp;START.<\\/p><p>Сообщение уйдёт, но дальше ничего происходить не будет.&nbsp;<br>Никакой логики взаимодействия мы ещё не создали.<\\/p><p>&nbsp;<\\/p><p>Результат:&nbsp;Telegram-бот создан.<\\/p><p>&nbsp;<\\/p><p><strong>Регистрация и вход в&nbsp;Aimylogic<\\/strong><\\/p><p>Aimylogic — визуальный конструктор чат-ботов.&nbsp;<br>В нём сценарий создаётся из отдельных блоков, соединённых между собой.&nbsp;<br>Каждый блок выполняет определённое действие в диалоге.<\\/p><p>&nbsp;<\\/p><p>Откройте браузер.<\\/p><p>Перейдите на сайт&nbsp;Aimylogic (aimylogic.com).<\\/p><p>В верхнем меню нажмите Стоимость.<\\/p><p>На странице тарифов нажмите кнопку Начать бесплатно.<\\/p><p>Заполните данные входа.<\\/p><p>Откроется начальная страница.<\\/p><p>Нажмите + Создать чат-бота<\\/p><p>(Интерфейс может, со временем, поменяться. В любом случае найдите функционал создания чат-бота. Это же относится ко всем остальным действия в интерфейсе&nbsp;Aimylogic. Проявляйте смекалку)<\\/p><p>Откроется окно Способ создания чат-бота.<\\/p><p>Выберете В конструкторе.<\\/p><p>Откроется окно Основные настройки.<\\/p><p>Выберете язык Русский и пустой шаблон.<\\/p><p>Введите название проекта:<\\/p><p><code>Доставка Петропавл -&nbsp;Telegram<\\/code><\\/p><p>Нажмите кнопку: В конструктор.<\\/p><p>После создания проекта откроется редактор сценария (конструктор).<\\/p><p>Проверьте: в интерфейсе отображается название проекта, а в редакторе доступна рабочая область сценария.<\\/p><p>Если будут появляться рекламные сообщения - закрывайте.<\\/p><p>Результат: создан проект&nbsp;Aimylogic.<\\/p><p>&nbsp;<\\/p><p>Aimylogic описывает блоки как основные элементы, из которых строится логика сценария.&nbsp;<br>Блоки размещаются на экранах и соединяются переходами.<\\/p><p>&nbsp;<\\/p><p><strong>Подключение&nbsp;Telegram-бота<\\/strong><\\/p><p>Теперь передадим&nbsp;Aimylogic API-токен, который вы получили от&nbsp;BotFather.<\\/p><p>В проекте&nbsp;Aimylogic, в вертикальном меню слева, найдите раздел «Подключения каналов» и откройте.<\\/p><p>В списке каналов найдите «Telegram» и нажмите.<\\/p><p>В поле для токена вставьте&nbsp;API-токен, полученный от&nbsp;BotFather.<\\/p><p>Нажмите «Подключить».<\\/p><p>Если&nbsp;TG-бот существует и доступен - появится сообщение: Канал подключен.<\\/p><p>Если подключение не выполняется, проверьте:<\\/p><p>API-токен скопирован полностью;<br>в начале или конце токена нет лишнего пробела;<br>используется токен именно созданного вами бота.<\\/p><p>Результат:&nbsp;Telegram подключён к проекту&nbsp;Aimylogic.<\\/p><p>&nbsp;<\\/p><p><strong>Рабочая область конструктора<\\/strong><\\/p><p>Теперь, в меню слева, перейдите обратно в конструктор.<\\/p><p>В центре находится рабочая область сценария.&nbsp;<br>Здесь будут размещаться экраны и блоки.<\\/p><p>&nbsp;<\\/p><p>Основная идея конструктора проста:<\\/p><p>экран → блок → действие бота → переход на следующий экран.<\\/p><p>Например, один экран может содержать текстовое сообщение и кнопку.&nbsp;<br>При нажатии кнопки бот переходит на другой экран.<\\/p><p>&nbsp;<\\/p><p>В&nbsp;Aimylogic блок «Текст» используется для вывода текстового сообщения клиенту.<\\/p><p>Сейчас создадим именно такой простой сценарий.<\\/p><p>&nbsp;<\\/p><p><strong>Первый сценарий<\\/strong><\\/p><p>Наш сценарий будет состоять из двух экранов.<\\/p><p>Первый экран (он же стартовый):<\\/p><p>Текст: \\\"Здравствуйте! Это бот службы доставки.\\\"<\\/p><p>Кнопка: \\\"Узнать больше\\\"<\\/p><p>Второй экран:<\\/p><p>Текст: \\\"Мы готовы помочь с оформлением доставки.\\\"<\\/p><p>&nbsp;<\\/p><p><strong>Создание первого экрана<\\/strong><\\/p><p>Ты должен находиться в визуальном редакторе, где уже есть пустая рабочая область и панель «Блоки».<\\/p><p>В блоках выбери блок «Текст»<\\/p><p>Введи следующий текст:&nbsp;<\\/p><p><code>Здравствуйте! Это бот службы доставки<\\/code><\\/p><p>Нажми кнопку Сохранить.<\\/p><p>Таким образом мы создали первый экран, который будет выполняться при запуске сценария, т.е. когда в&nbsp;Telegram, в боте пользователь введёт команду <code>\\/start<\\/code>.&nbsp;<\\/p><p>Примечание: Не добавляй \\/start в текст блока. И не надо делать отдельный экран: \\/start<\\/p><p>&nbsp;<\\/p><p>В&nbsp;Telegram последовательность выглядит так:<\\/p><p>Пользователь открывает бота<\\/p><p>&nbsp; &nbsp; &nbsp; &nbsp;↓<\\/p><p>Вводит команду \\/start<\\/p><p>&nbsp; &nbsp; &nbsp; &nbsp;↓<\\/p><p>Telegram отправляет \\/start в&nbsp;Aimylogic<\\/p><p>&nbsp; &nbsp; &nbsp; &nbsp;↓<\\/p><p>Aimylogic запускает сценарий<\\/p><p>&nbsp; &nbsp; &nbsp; &nbsp;↓<\\/p><p>Aimylogic отправляет в&nbsp;Telegram первый экран<\\/p><p>&nbsp; &nbsp; &nbsp; &nbsp;↓<\\/p><p>В&nbsp;Telegram отображается: «Здравствуйте! Это бот службы доставки»<\\/p><p>&nbsp;<\\/p><p>По другому говоря - клиент является тем, кто начинает диалог с чат-ботом.&nbsp;<\\/p><p>&nbsp;<\\/p><p><strong>Публикация и проверка сценария в&nbsp;Telegram<\\/strong><\\/p><p>Это важный этап.&nbsp;<br>То, что вы сделали сценарий в конструкторе, ещё не является полной проверкой.&nbsp;<br>Нужно открыть самого&nbsp;Telegram-бота и пройти созданный сценарий как обычный пользователь.<\\/p><p>Проверим сценарий на реальное взаимодействие с Telegram.<\\/p><p>&nbsp;<\\/p><p>В главном меню, вверху справа нажмите кнопку Сохранить.<\\/p><p>Потом нажмите кнопку Опубликовать.<\\/p><p>Дождитесь окончания публикации (должно быть не более 10 секунд).<\\/p><p>Зайдите в&nbsp;Telegram в своего бота.<\\/p><p>Введите команду <code>\\/start<\\/code>.<\\/p><p>Если в боте появился текст стартового блока - всё работает.<\\/p><p>&nbsp;<\\/p><p><strong>Если бот не отвечает<\\/strong><\\/p><p>Если после команды <code>\\/start<\\/code> бот не показывает приветствие, проверьте по порядку.<\\/p><p>Проверка 1.&nbsp;Telegram подключён<\\/p><p>Вернитесь в&nbsp;Aimylogic → откройте «Каналы» → найдите&nbsp;Telegram → проверьте статус подключения.<\\/p><p>Проверка 2. Сценарий опубликован<\\/p><p>Проверьте, что после создания или изменения сценария была выполнена публикация.<\\/p><p>Проверка 3. Используется правильный бот<\\/p><p>Сравните&nbsp;username бота в&nbsp;Telegram с&nbsp;username бота, который создавался через&nbsp;BotFather и подключался к&nbsp;Aimylogic.<\\/p><p>Не изменяйте сразу несколько настроек одновременно.&nbsp;<br>Сначала найдите, на каком именно этапе возникла проблема.<\\/p><p>&nbsp;<\\/p><p><strong>Добавление кнопки<\\/strong><\\/p><p>Теперь добавим кнопку к этому сообщению.<\\/p><p>В текстовом блоке нажмите кнопку + КНОПКА.<\\/p><p>Введите текст:&nbsp;<\\/p><p><code>Узнать больше<\\/code><\\/p><p>Нажмите&nbsp;Enter.<\\/p><p>&nbsp;<\\/p><p>В&nbsp;Aimylogic кнопку можно связать с другим экраном:&nbsp;<br>для этого используется связь от кнопки к нужному экрану.&nbsp;<\\/p><p>&nbsp;<\\/p><p><strong>Создание второго экрана<\\/strong><\\/p><p>Теперь создадим экран, который будет открываться после нажатия кнопки.<\\/p><p>Проведите мышью в пустой области конструктора справа.<\\/p><p>Появится кнопка +Добавить экран.<\\/p><p>Нажмите на кнопку и выберите блок Текст.<\\/p><p>&nbsp;<\\/p><p>Введите текст:&nbsp;<\\/p><p><code>Мы готовы помочь с оформлением доставки<\\/code><\\/p><p>Сохраните блок.<\\/p><p>&nbsp;<\\/p><p>На первом экране, на кнопке <code>Узнать больше<\\/code> наведите мышь на круглишок на кнопке справа.<\\/p><p>Удерживая левую кнопку мыши протяните связь на второй экран и отпустите кнопку мыши.<\\/p><p>Появится стрелка связи ведущая от первого экрана ко второму.<\\/p><p>&nbsp;<\\/p><p>Что происходит при нажатии кнопки в боте ?<\\/p><p>В&nbsp;Aimylogic обычная кнопка может быть связана с другим экраном.&nbsp;<br>Когда пользователь нажимает её, бот переходит на связанный экран.<\\/p><p>В нашем сценарии происходит следующее:<\\/p><p>Пользователь запускает бота командой \\/start.<\\/p><p>Aimylogic начинает сценарий с первого экрана.<\\/p><p>Бот отображает текст: \\\"Здравствуйте! Это бот службы доставки.\\\" и кнопку.<\\/p><p>Пользователь нажимает кнопку Узнать больше.<\\/p><p>Бот переходит на второй экран, с текстом: \\\"Мы готовы помочь с оформлением доставки.\\\"<\\/p><p>Это уже полноценный, хотя и очень простой, диалог.<\\/p><p>&nbsp;<\\/p><p>Сохраните и опубликуйте изменения<\\/p><p>Проверьте:&nbsp;Telegram-канал остаётся подключённым, а публикация завершилась без сообщения об ошибке.<\\/p><p>&nbsp;<\\/p><p><strong>Проверьте диалог в&nbsp;Telegram.<\\/strong><\\/p><p>В боте&nbsp;Telegram введите команду \\/start<\\/p><p>Ожидаемый результат:<\\/p><p>Здравствуйте! Это бот службы доставки.<\\/p><p>Под сообщением должна отображаться кнопка: Узнать больше<\\/p><p>Нажмите кнопку.<\\/p><p>Подождите ответа бота.<\\/p><p>Ожидаемый результат: бот отправляет второе сообщение:&nbsp;<br>\\\"Мы готовы помочь с оформлением доставки.\\\"<\\/p><p>Результат: диалог полностью прошёл от первого экрана до второго.<\\/p><p>Созданный в&nbsp;Aimylogic сценарий реально работает в&nbsp;Telegram.<\\/p><p>&nbsp;<\\/p><p><strong>Что должно получиться в конце урока<\\/strong><\\/p><p>К концу урока у вас должны быть:<\\/p><p>создан&nbsp;Telegram-бот через&nbsp;BotFather;<\\/p><p>получен&nbsp;API-токен;<\\/p><p>создан проект в&nbsp;Aimylogic;<\\/p><p>Telegram подключён к проекту;<\\/p><p>создан первый (стартовый) экран;<\\/p><p>добавлен текст приветствия;<\\/p><p>добавлена кнопка Узнать больше;<\\/p><p>создан второй экран;<\\/p><p>добавлено второе текстовое сообщение;<\\/p><p>кнопка связана со вторым экраном;<\\/p><p>сценарий опубликован;<\\/p><p>диалог проверен непосредственно в&nbsp;Telegram.<\\/p><p>&nbsp;<\\/p><p>На этом первом уроке этого достаточно.&nbsp;<br>В следующих уроках мы будем постепенно усложнять эту схему и добавлять в неё реальные элементы автоматизации бизнес-процесса.<\\/p>\",\"tests\":[{\"question\":\"Для чего используется BotFather?\",\"answers\":[\"Для просмотра истории переписки в Telegram\",\"Для создания и настройки Telegram-ботов ✓\",\"Для создания Google-аккаунтов через Telegram\",\"Для публикации сайтов в Telegram\"],\"correct\":null},{\"question\":\"Что представляет собой API-токен Telegram-бота?\",\"answers\":[\"Название проекта Aimylogic с подключенным Telegram-ботом\",\"Секретный ключ проекта Aimylogic для подключения к Telegram-боту\",\"Секретный ключ для подключения и управления ботом через Bot API ✓\",\"Ссылка на веб-версию Telegram\"],\"correct\":null},{\"question\":\"Что необходимо сделать с API-токеном после его получения от BotFather?\",\"answers\":[\"Опубликовать его в описании бота\",\"Передать его знакомым или друзьям, чтобы они могли заходить в бота\",\"Использовать его для подключения бота к Aimylogic ✓\",\"Удалить его сразу после создания бота\"],\"correct\":null},{\"question\":\"Для чего в Aimylogic используется раздел «Каналы»?\",\"answers\":[\"Для подключения бота к внешним каналам общения ✓\",\"Для изменения языка общения с ботом\",\"Для доступа к файлам компьютера\",\"Для подключения Google-таблиц\"],\"correct\":null},{\"question\":\"Что нужно сделать, чтобы кнопка в сценарии перевела пользователя на другой экран?\",\"answers\":[\"Переместить кнопку на другой экран\",\"Изменить API-токен этого экрана\",\"Создать новый аккаунт Google для этого экрана\",\"Связать кнопку с нужным экраном ✓\"],\"correct\":null},{\"question\":\"Почему после создания сценария важно проверить его непосредственно в Telegram?\",\"answers\":[\"Потому что схема в конструкторе сама по себе не показывает работу бота в реальном канале ✓\",\"Потому что Telegram нужен для изменения названия проекта\",\"Потому что Aimylogic не сохраняет схемы\",\"Потому что BotFather автоматически удаляет тестовые сценарии\"],\"correct\":null}],\"lab\":\"<p>Цель лабораторной работы — самостоятельно изменить настройки уже созданного&nbsp;Telegram-бота и проверить результат непосредственно в&nbsp;Telegram.<\\/p><p>В этой работе не нужно заново создавать проект Aimylogic или Telegram-бота.<\\/p><p>&nbsp;<\\/p><p>Задача. Изменение отображаемого имени бота<\\/p><p>Откройте&nbsp;Telegram.<\\/p><p>В поиске найдите @BotFather.<\\/p><p>Откройте официальный чат&nbsp;BotFather.<\\/p><p>Отправьте команду:<\\/p><p>\\/setname<\\/p><p>Выберите созданного в уроке бота.<\\/p><p>Введите новое отображаемое имя, отличающееся от первоначального.<\\/p><p>Например:<\\/p><p>Сервис доставки — Помощник<\\/p><p>Отправьте новое имя.<\\/p><p>Дождитесь подтверждения&nbsp;BotFather.<\\/p><p>Откройте своего бота в&nbsp;Telegram.<\\/p><p>Проверьте новое отображаемое имя.<\\/p><p>Верните изначальное имя бота.<\\/p><p>&nbsp;<\\/p><p>Задача. Изменение описания бота<\\/p><p>Вернитесь в чат с&nbsp;BotFather.<\\/p><p>Отправьте:<\\/p><p>\\/setdescription<\\/p><p>Выберите созданного бота.<\\/p><p>Введите новое описание.<\\/p><p>Например:<\\/p><p>Служба доставки продуктов в г. Петропавловск. Здесь вы можете получить информацию о доставке.<\\/p><p>Отправьте описание.<\\/p><p>Дождитесь подтверждения&nbsp;BotFather.<\\/p><p>Проверьте:&nbsp;BotFather подтвердил изменение описания.<\\/p><p>&nbsp;<\\/p><p>Задача. Проверка описания в&nbsp;Telegram<\\/p><p>Теперь проверьте результат глазами пользователя.<\\/p><p>Откройте ссылку на созданного бота.<\\/p><p>Если есть возможность, откройте эту ссылку с&nbsp;Telegram-аккаунта, который ещё не начинал диалог с ботом, например, вашего одногруппника.<\\/p><p>Откройте профиль бота.<\\/p><p>Найдите описание.<\\/p><p>Проверьте, что отображается новое описание.<\\/p>\"}');
INSERT INTO `lessons` (`id`, `section_id`, `title_ru`, `slug`, `lesson_order`, `content`) VALUES
(7, 4, '2.2. Проектирование сценария диалога и создание кнопочного меню в Aimylogic', 'first-aimylogic-workflow', 2, '{\"theory\":\"<p>В прошлом уроке мы создали Telegram-бота, получили API-токен и подключили бота к Aimylogic.&nbsp;<br>Теперь бот уже существует и доступен в Telegram, но сам по себе он ещё не умеет вести полноценный диалог.<\\/p><p>&nbsp;<\\/p><p>В этом уроке создадим первый рабочий сценарий службы доставки.&nbsp;<br>Пользователь откроет бота, увидит приветствие и главное меню, а затем сможет выбрать одно из четырёх действий:<\\/p><p>«Посмотреть меню»<\\/p><p>«Адрес доставки»<\\/p><p>«Режим работы»<\\/p><p>«Связаться с оператором»<\\/p><p>Каждая кнопка будет вести в отдельную ветку сценария.&nbsp;<br>После просмотра информации пользователь сможет одной кнопкой вернуться в главное меню.<\\/p><p>&nbsp;<\\/p><p>Aimylogic является визуальным конструктором:&nbsp;<br>сценарий собирается из отдельных элементов, соединённых переходами.&nbsp;<br>Такой подход позволяет видеть логику диалога как схему и изменять её без программирования.&nbsp;<br><br>&nbsp;<\\/p><p><strong>Как устроен сценарий бота<\\/strong><\\/p><p>Сценарий можно представить как маршрут пользователя:<\\/p><p>приветствие (стартовый экран) → главное меню → выбранная ветка → возврат в главное меню.<\\/p><p>Главное меню является центральной точкой сценария.<\\/p><p>Например:<\\/p><p>Главное меню → «Посмотреть меню» → сообщение со сведениями о меню → «В главное меню» → главное меню<\\/p><p>Или:<\\/p><p>Главное меню → «Адрес доставки» → сообщение с адресом → «В главное меню» → главное меню<\\/p><p>Это важно: кнопка должна не просто отображаться пользователю, а иметь переход в следующий элемент сценария.<\\/p><p>&nbsp;<\\/p><p><strong>Блок сообщения<\\/strong><\\/p><p>Основной элемент простого сценария — блок, который отправляет пользователю сообщение.<\\/p><p>В сообщении можно разместить текст, а при необходимости добавить интерактивные элементы.&nbsp;<br>Для нашего урока главным интерактивным элементом будут кнопки.<\\/p><p>&nbsp;<\\/p><p>Важно различать:<\\/p><p>сообщение — то, что бот сообщает пользователю;<\\/p><p>кнопка — действие, которое пользователь может выбрать;<\\/p><p>переход — связь, определяющая, какой элемент сценария будет выполнен после выбора действия.<\\/p><p>Например:<\\/p><p>Сообщение: «Выберите нужное действие»<\\/p><p>Кнопка: «Адрес доставки»<\\/p><p>Переход: к сообщению с адресом доставки.<\\/p><p>&nbsp;<\\/p><p><strong>Подготовка сценария<\\/strong><\\/p><p>Откройте браузер → перейдите на сайт Aimylogic → войдите в тот же аккаунт, который использовали при подключении Telegram-бота → откройте проект с вашим ботом.<\\/p><p>В вертикальном меню слева откройте конструктор (редактор сценария).<\\/p><p>Удалите все элементы, которые были созданы на прошлом уроке.<br>(через меню открываемое тремя вертикальными точками).<\\/p><p>(рабочая область сценария должна быть пустая).<\\/p><p>&nbsp;<\\/p><p><strong>Приветственное сообщение<\\/strong><\\/p><p>Сначала создадим короткое приветствие.<\\/p><p>Откройте в конструкторе первый блок сообщения, который должен выполняться после запуска сценария.<\\/p><p>&nbsp;<\\/p><p>В меню блоков добавьте блок Текст.<\\/p><p>Введите: «Здравствуйте! Это бот службы доставки еды. Здесь вы можете посмотреть меню, узнать адрес и режим работы или связаться с оператором. Выберите нужное действие.»<\\/p><p>Нажмите сохранить.<\\/p><p>В стартовом экране нажмите кнопку \\\"+ кнопка\\\" и введите текст:<br>\\\"На главное меню\\\".<\\/p><p>Нажмите&nbsp;Enter.<\\/p><p>Таким образом мы заново создали первый (стартовый) экран.<\\/p><p>&nbsp;<\\/p><p>Приветственное сообщение не должно содержать всю информацию о службе доставки.&nbsp;<br>Его задача — объяснить пользователю, что умеет бот, и направить его к главному меню.<\\/p><p>Сценарий начинается с взаимодействия пользователя с ботом в Telegram, после чего бот последовательно выполняет заданные элементы сценария.<\\/p><p>&nbsp;<\\/p><p><strong>Создание главного меню<\\/strong><\\/p><p>Теперь создадим отдельный блок для главного меню.<\\/p><p>Проведите мышью справа от первого сообщения, появится кнопка + Добавить экран.<\\/p><p>Нажмите на кнопку и в меню блоков выберите Текст.<\\/p><p>В поле текста введите:<\\/p><p>\\\"Главное меню. Выберите нужное действие:\\\".<\\/p><p>Нажмите Сохранить.<\\/p><p>Кнопкой \\\"+ кнопка\\\" - добавьте три кнопки:<\\/p><p>\\\"Посмотреть меню\\\"<\\/p><p>\\\"Режим работы\\\"<\\/p><p>\\\"Связаться с оператором\\\"<\\/p><p>&nbsp;<\\/p><p>Результат: на рабочем поле появился блок главного меню с тремя кнопками.<\\/p><p>&nbsp;<\\/p><p><strong>Соединение приветствия с главным меню<\\/strong><\\/p><p>На стартовом экране, на кнопке \\\"На главное меню\\\", справа найдите круглишок.<\\/p><p>Наведите на него курсор мыши.<\\/p><p>Нажав и удерживая левую кнопку мыши - протяните связь на второй экран (экран главного меню)<\\/p><p>&nbsp;<\\/p><p><strong>Создание ветки «Посмотреть меню»<\\/strong><\\/p><p>Теперь создадим первую ветку.<\\/p><p>В рабочей области, справа от второго экрана, добавьте новый экран.<\\/p><p>Создайте блок текст.<\\/p><p>Введите текст:<\\/p><p>\\\"Наше меню: пицца, суши и роллы, бургеры, напитки\\\".<\\/p><p>Нажмите Сохранить.<\\/p><p>Добавьте кнопку:<\\/p><p>\\\"В главное меню\\\"<\\/p><p>Соедините кнопку «Посмотреть меню» в экране главного меню с новым экраном Наше меню.<\\/p><p>На экране Наше меню, от кнопки \\\"В главное меню\\\", протяните связь обратно к экрану главного меню.<\\/p><p>Это нужно, чтобы в ветке не было тупика.&nbsp;<br>После просмотра информации пользователь может вернуться к основному выбору.<\\/p><p>&nbsp;<\\/p><p>Результат:<\\/p><p>Приветствие → \\\"На главное меню\\\" → Главное меню → \\\"Посмотреть меню\\\" → информация о меню → \\\"В главное меню\\\" → Главное меню.<\\/p><p>&nbsp;<\\/p><p>В главном меню проекта aimylogic, справа вверху, нажмите кнопку \\\"Опубликовать\\\".<\\/p><p>&nbsp;<\\/p><p><strong>Проверка текущего состояния сценария в&nbsp;Telegram<\\/strong><\\/p><p>Откройте&nbsp;Telegram.<\\/p><p>Если&nbsp;Telegram ещё не открыт на учебном компьютере, перейдите в браузере на:<\\/p><p>web.telegram.org<\\/p><p>Авторизуйтесь в&nbsp;Telegram:<\\/p><p>Настройки → Устройства → Подключить устройство<\\/p><p>и завершите вход с помощью&nbsp;QR-кода.<\\/p><p>&nbsp;<\\/p><p>Найдите своего бота.<\\/p><p>(Если вы его не видите в списке чатов, найдите через поиск по имени бота)<\\/p><p>Введите команду \\/start .<\\/p><p>Должно выйти приветственное сообщение с кнопкой: \\\"На главное меню\\\".<\\/p><p>Нажмите на кнопку.<\\/p><p>Должно выйти сообщение главного меню с 3 кнопками.<\\/p><p>Нажмите на кнопку \\\"Посмотреть меню\\\".<\\/p><p>Должно открыться сообщение с меню и кнопкой \\\"В главное меню\\\".<\\/p><p>Нажмите на кнопку.<\\/p><p>Должен произойти возврат в главное меню.<\\/p><p>Если так всё и происходит, значит бот работает правильно.<\\/p><p>&nbsp;<\\/p><p><strong>Создание ветки «Режим работы»<\\/strong><\\/p><p>Теперь создайте вторую ветку.<\\/p><p>Справа экрана Наше меню добавьте новый экран через&nbsp;«+ Добавить экран».<\\/p><p>В меню блоков выберите&nbsp;«Текст».<\\/p><p>Введите:<\\/p><p>\\\"Принимаем заказы ежедневно с 10:00 до 22:00. Доставка выполняется в течение рабочего времени службы доставки с 11:00 до 23:00\\\".<\\/p><p>Нажмите&nbsp;«Сохранить».<\\/p><p>Добавьте кнопку:&nbsp;\\\"В главное меню\\\".<\\/p><p>Нажмите&nbsp;Enter.<\\/p><p>Соедините добавленную кнопку с экраном Главное меню.<\\/p><p>На экране&nbsp;«Главное меню» соедините кнопку&nbsp;«Режим работы» с экраном с информацией о режиме работы.<\\/p><p>&nbsp;<\\/p><p>Результат: создана ветка «Режим работы».<\\/p><p>Проверьте маршрут:<\\/p><p>Главное меню → «Режим работы» → информация о режиме работы → «В главное меню» → Главное меню.<\\/p><p>В главном меню проекта, нажмите кнопку Сохранить.<\\/p><p>&nbsp;<\\/p><p><strong>Создание ветки «Связаться с оператором»<\\/strong><\\/p><p>Последняя ветка главного меню должна позволять пользователю понять, как связаться с оператором.<\\/p><p>&nbsp;<\\/p><p><strong>Создайте эту ветку полностью самостоятельно<\\/strong>, по аналогии с предыдущими ветками.<\\/p><p>Текст введите на своё усмотрение.<\\/p><p>Проверьте, что ветка имеет обратную связь с главным меню.<\\/p><p>&nbsp;<\\/p><p>Посмотрите всю визуальную структуру сценария.<\\/p><p>(если нужно уменьшите масштаб рабочей области).<\\/p><p>Нажмите кнопку Опубликовать.<\\/p><p>&nbsp;<\\/p><p><strong>Проверка структуры всего сценария<\\/strong><\\/p><p>В&nbsp;Telegram откройте чат с ботом.<\\/p><p>В меню бота&nbsp;Telegram (справа вверху три вертикальных кнопки) очистите историю бота.<\\/p><p>Командой&nbsp;\\/start запустите бота.<\\/p><p>Перейдите в главное меню<\\/p><p>Последовательно проверьте все три ветки.<\\/p><p>Если все маршруты выполняется без ошибок, сценарий первого рабочего меню создан правильно.<\\/p><p>Важно: если после изменения сценария в&nbsp;Telegram отображается старая версия (старая логика работы), снова вернитесь в&nbsp;Aimylogic и нажмите&nbsp;«Опубликовать».<br>Если что то не работает, и вы не может найти проблему - обратитесь к ИИ, скинув необходимые скриншоты.<\\/p>\",\"tests\":[{\"question\":\"Какую основную задачу выполняет блок сообщения в визуальном сценарии чат-бота?\",\"answers\":[\"Создаёт резервную копию проекта\",\"Отправляет пользователю заданный текст ✓\",\"Удаляет предыдущий экран\",\"Подключает Telegram-аккаунт\"],\"correct\":null},{\"question\":\"Для чего нужны кнопки в главном меню бота?\",\"answers\":[\"Чтобы изменить название Telegram-бота\",\"Чтобы закрыть Telegram-бот\",\"Чтобы автоматически удалить сообщение после отправки\",\"Чтобы пользователь мог выбрать действие ✓\"],\"correct\":null},{\"question\":\"Что произойдёт, если кнопка не имеет необходимого перехода?\",\"answers\":[\"Aimylogic автоматически создаст новую ветку\",\"Telegram изменит текст кнопки\",\"Проект будет автоматически удалён\",\"Пользователь не получит ожидаемое продолжение диалога ✓\"],\"correct\":null},{\"question\":\"Зачем информационной ветке нужна кнопка возврата?\",\"answers\":[\"Чтобы удалить предыдущий блок\",\"Чтобы изменить API-токен\",\"Чтобы создать новый проект\",\"Чтобы пользователь мог продолжить работу с другими пунктами меню ✓\"],\"correct\":null},{\"question\":\"Что нужно проверить после создания главного меню?\",\"answers\":[\"Что количество блоков соответствует количеству кнопок\",\"Что все кнопки имеют понятные названия и необходимые переходы ✓\",\"Что все блоки находятся в одной строке\",\"Что пользователь отключён от Telegram\"],\"correct\":null},{\"question\":\"Какой результат показывает, что ветка сценария настроена корректно?\",\"answers\":[\"В рабочей области находится необходимое количество блоков\",\"Telegram перестаёт показывать кнопки\",\"Aimylogic удаляет начальный элемент сценария\",\"Пользователь попадает в ветку и может вернуться в главное меню ✓\"],\"correct\":null}],\"lab\":\"<p>Цель лабораторной работы — самостоятельно изменить уже созданный сценарий, не повторяя пошагово построение четырёх основных веток из теоретической части.<\\/p><p>&nbsp;<\\/p><p>Вам необходимо добавить в существующее главное меню пятую кнопку «Акции и скидки» и самостоятельно построить для неё отдельную ветку.<\\/p><p>&nbsp;<\\/p><p>Задача. Добавление ветки «Акции и скидки»<\\/p><p>Откройте в Aimylogic проект с ботом, созданным в предыдущем уроке и дополненным в теоретической части этого урока.<\\/p><p>Найдите на рабочем поле блок «Главное меню».<\\/p><p>Добавьте к нему пятую кнопку:<\\/p><p>«Акции и скидки»<\\/p><p>Создайте отдельный блок сообщения для новой ветки.<\\/p><p>Самостоятельно придумайте одну акцию службы доставки.<\\/p><p>&nbsp;<\\/p><p>Например, это может быть скидка на определённую категорию товаров, специальное предложение при заказе от определённой суммы или бесплатная доставка при выполнении определённого условия.<\\/p><p>Текст акции должен содержать:<\\/p><p>название акции;<\\/p><p>условие получения предложения;<\\/p><p>размер скидки или другое преимущество;<\\/p><p>срок действия акции либо фразу о том, что акция действует в течение ограниченного периода.<\\/p><p>&nbsp;<\\/p><p>Пример структуры сообщения:<\\/p><p>«Акция недели: при заказе от 10 000 тг доставка бесплатно. Предложение действует до конца недели.»<\\/p><p>Этот пример не нужно копировать. В лабораторной работе придумайте собственную акцию.<\\/p><p>&nbsp;<\\/p><p>В созданном сообщении добавьте кнопку:<\\/p><p>«В главное меню»<\\/p><p>Затем самостоятельно соедините:<\\/p><p>кнопку «Акции и скидки» → новое сообщение с акцией;<\\/p><p>кнопку «В главное меню» → существующий блок главного меню.<\\/p><p>Сохраните сценарий.<\\/p><p>&nbsp;<\\/p><p>После сохранения откройте Telegram и запустите бота.<\\/p><p>&nbsp;<\\/p><p>Проверьте полный маршрут:<\\/p><p>главное меню → «Акции и скидки» → сообщение с вашей акцией → «В главное меню» → главное меню.<\\/p><p>&nbsp;<\\/p><p>Контрольный результат:<\\/p><p>в главном меню отображаются пять кнопок;<\\/p><p>пятая кнопка называется «Акции и скидки»;<\\/p><p>она ведёт в отдельную ветку;<\\/p><p>в ветке отображается придуманная вами акция;<\\/p><p>в ветке есть кнопка «В главное меню»;<\\/p><p>кнопка возврата приводит непосредственно к главному меню;<\\/p><p>остальные четыре ветки продолжают работать без изменений.<\\/p><p>&nbsp;<\\/p><p>После выполнения лабораторной студент должен самостоятельно уметь взять существующее главное меню, добавить новый пункт, создать отдельную ветку, соединить её с меню и обеспечить возврат пользователя обратно в главное меню.<\\/p>\"}'),
(8, 4, '2.3. Отображение реального меню службы доставки из реального датасета в Telegram-боте', 'real-menu', 3, '{\"theory\":\"<p>В прошлом уроке мы собрали кнопочное меню.&nbsp;<br>Сообщение «Наше меню: пицца, суши и роллы, бургеры, напитки» мы вводили вручную, и это просто текст-заглушка.&nbsp;<\\/p><p>&nbsp;<\\/p><p>В этом уроке бот будет брать названия блюд и цены из&nbsp;Google Таблицы, из вашей копии датасета службы доставки.&nbsp;<br>Продукт или цену поменяли в таблице, и бот сразу показывает новую.<\\/p><p>В конце урока в&nbsp;Telegram должен работать такой маршрут:<\\/p><p>Главное меню → «Посмотреть меню» → выбор категории → «Пицца» → сообщение со списком пицц и ценами из таблицы → возврат в меню.<\\/p><p>&nbsp;<\\/p><p><strong>Откуда бот будет брать данные<\\/strong><\\/p><p>Таблица для бота играет роль склада данных.&nbsp;<br>Бот не хранит названия и цены у себя.&nbsp;<br>Когда пользователь нажимает кнопку,&nbsp;Aimylogic выполняет такую последовательность:<\\/p><p>Пользователь нажимает кнопку в&nbsp;Telegram →&nbsp;Aimylogic заходит в вашу&nbsp;Google Таблицу →&nbsp;Aimylogic читает нужные ячейки и запоминает значения в переменных →&nbsp;Aimylogic подставляет значения в текст сообщения → В Telegram приходит готовое сообщение<\\/p><p>Значения читаются в момент нажатия кнопки, а не в момент публикации бота.&nbsp;<br>Поэтому актуальные цены берутся из таблицы автоматически.<\\/p><p>&nbsp;<\\/p><p>Переменная — это «коробочка с названием», в которую бот временно кладёт значение, например название блюда.&nbsp;<br>Потом это название можно вставить в текст сообщения по имени коробочки.&nbsp;<br>В&nbsp;Aimylogic имя переменной в тексте начинается со знака доллара.<\\/p><p>&nbsp;<\\/p><p><strong>Лист «Меню и Товары»: что в нём лежит?<\\/strong><\\/p><p>Откройте в браузере свою копию датасета (вы сделали её в Модуле 1) и перейдите на лист «Меню и Товары».&nbsp;<br>Внизу окна таблицы есть вкладки листов, нажмите на нужную.&nbsp;<br>Обратите внимание на написание: «Товары» пишется с большой буквы.<\\/p><p>&nbsp;<\\/p><p>Первая строка листа содержит названия столбцов:<\\/p><p>столбец&nbsp;A —&nbsp;ID_Товара;<\\/p><p>столбец&nbsp;B — Наименование;<\\/p><p>столбец&nbsp;C — Категория;<\\/p><p>столбец&nbsp;D — Себестоимость_Тг;<\\/p><p>столбец&nbsp;E — Цена_Продажи_Тг.<\\/p><p>Для бота нам нужны только два столбца:&nbsp;B (Наименование) и&nbsp;E (Цена_Продажи_Тг).&nbsp;<br>Столбец&nbsp;D (Себестоимость_Тг) показывать клиентам нельзя.&nbsp;<br>Это внутренние данные, по которым вы считаете прибыль.&nbsp;<br>Клиенту нужна только цена продажи.<\\/p><p>В столбце&nbsp;C (Категория) блюда разбиты на группы:&nbsp;<br>Пицца, Суши и Роллы, Бургеры, Фастфуд, Закуски, Горячие блюда, Супы, Десерты, Напитки.&nbsp;<br>Блюда одной категории идут в таблице подряд.<\\/p><p>&nbsp;<\\/p><p>Адрес ячейки: как сказать боту, откуда читать<\\/p><p>Каждая ячейка таблицы имеет адрес: буква столбца и номер строки.&nbsp;<br>Например,&nbsp;B2 — это ячейка на пересечении столбца&nbsp;B и строки 2.&nbsp;<br>Бот находит данные только по адресу, поэтому нужно точно знать, в какой строке лежит нужное блюдо.<\\/p><p>Категория «Пицца» занимает строки со 2 по 6.&nbsp;<br>Проверьте это в своей таблице:&nbsp;<br>в столбце&nbsp;C в этих пяти строках написано «Пицца».<\\/p><p>&nbsp;<\\/p><p>Вот данные, которые мы будем выводить в боте:<\\/p><p>B2 — Пицца Пепперони (30 см),&nbsp;E2 — 3200<\\/p><p>B3 — Пицца Маргарита (30 см),&nbsp;E3 — 2600<\\/p><p>B4 — Пицца 4 Сыра (30 см),&nbsp;E4 — 3600<\\/p><p>B5 — Пицца Сборная мясная (30 см),&nbsp;E5 — 3900<\\/p><p>B6 — Пицца Цыпленок Барбекю (30 см),&nbsp;E6 — 3400<\\/p><p>&nbsp;<\\/p><p><strong>Подготовка: что нужно перед началом<\\/strong><\\/p><p>Aimylogic сможет читать таблицу, только если вы подключите к нему тот же&nbsp;Google-аккаунт, в котором лежит ваша копия датасета.&nbsp;<br>Чужая таблица, например общая ссылка на оригинал, не подойдёт:&nbsp;<br>бот должен работать с вашей копией.<\\/p><p>&nbsp;<\\/p><p>Убедитесь, что:<\\/p><p>вы вошли в&nbsp;Google под тем аккаунтом, где сохранена копия датасета;<\\/p><p>проект с ботом из прошлых уроков открывается в Aimylogic;<\\/p><p>стартовый экран и главное меню из урока 2.2 на месте и бот отвечает в&nbsp;Telegram.<\\/p><p>Если&nbsp;Telegram не открыт на компьютере -&nbsp;<br>откройте&nbsp;web.telegram.org → «Настройки (Settings)» → «Устройства (Devices)» → «Подключить устройство (Link Desktop Device)» → отсканируйте&nbsp;QR-код телефоном.<\\/p><p>&nbsp;<\\/p><p><strong>Подключение&nbsp;Google Таблиц к&nbsp;Aimylogic<\\/strong><\\/p><p>Подключение выполняется один раз.&nbsp;<br>Дальше все блоки проекта используют его.<\\/p><p>Откройте сайт&nbsp;Aimylogic и войдите в свой аккаунт.<\\/p><p>Откройте проект с вашим ботом («Доставка Петропавл -&nbsp;Telegram»).<\\/p><p>В вертикальном меню слева нажмите «Конструктор», чтобы открыть рабочую область сценария.<\\/p><p>Справа от имеющихся экранов, добавьте новый экран и в списке блоков, ниже, в разделе Действия, найдите блок \\\"Интеграция с&nbsp;Google-таблицами\\\".<\\/p><p>В открывшемся окне нажмите \\\"Перейти в настройки\\\".<\\/p><p>Если спросит: \\\"Сохранить изменения перед выходом?\\\", нажмите \\\"Сохранить и выйти\\\".<\\/p><p>В окне \\\"Настройки бота\\\", на вкладке \\\"Интеграции\\\", нажмите:<br>\\\"Войти через&nbsp;Google\\\".<\\/p><p>Пройдите процедуру авторизации.<\\/p><p>&nbsp;<\\/p><p>Результат:&nbsp;Google-аккаунт подключён к&nbsp;Aimylogic.<\\/p><p>&nbsp;<\\/p><p>Вернитесь в конструктор.<\\/p><p>На экране интеграции с&nbsp;Google-таблицами, в заголовке блока нажмите шестерёнку.<\\/p><p>В открывшемся окне «Интеграция с&nbsp;Google Таблицами» в поле «Аккаунт» виден ваш&nbsp;Google-аккаунт.<\\/p><p>&nbsp;<\\/p><p>В своём&nbsp;Google-диске откройте копию датасета службы доставки (google-таблицу).<\\/p><p>Посмотрите на адресную строку - она будет иметь примерно такой вид:<br>https:\\/\\/docs.google.com\\/spreadsheets\\/d\\/1gmVOaRnNM9amgxByQvSKFmGYiKgfkLuNRAO4hEPjiF5\\/edit?gid=188130150#gid=189120150<\\/p><p>Выделите и скопируйте часть этой строки между \\/d\\/ и \\/edit<\\/p><p>в примере строки выше это: 1gmVOaRnNM9amgxByQvSKFmGYiKgfkLuNRAO4hEPjiF5<\\/p><p>&nbsp;<\\/p><p>Вернитесь в&nbsp;Aimylogic, в конструктор, в окно интеграции.<\\/p><p>В поле&nbsp;ID таблицы вставьте скопированный&nbsp;ID.<\\/p><p>Если вы вставили правильный&nbsp;ID, в поле ниже \\\"Лист таблицы\\\", появятся листы вашего датасета.<\\/p><p>Если они не появились проверьте или повторите все предыдущие шаги.<\\/p><p>Если не получается - обратитесь к ИИ.<\\/p><p>&nbsp;<\\/p><p>В окне интеграции нажмите Сохранить.<\\/p><p>&nbsp;<\\/p><p>Теперь, этот экран интеграции с&nbsp;Google-таблицами, который вы добавили на экран для проверки, удалите:&nbsp;<br>нажмите на три вертикальные точки у блока → «Удалить».&nbsp;<br>Мы построим всё в правильном порядке далее.<\\/p><p>&nbsp;<\\/p><p><strong>Подготовка экрана выбора категорий<\\/strong><\\/p><p>В уроке 2.2 экран «Наше меню» содержал текст со списком и кнопку «В главное меню».&nbsp;<br>Теперь на этом экране будет выбор категории.<\\/p><p>Откройте в конструкторе экран, который открывается по кнопке «Посмотреть меню» (текст «Наше меню: пицца, суши и роллы, бургеры, напитки»).<\\/p><p>Нажмите на текстовый блок этого экрана, чтобы открыть редактирование.<\\/p><p>Замените текст на:&nbsp;<br>«Список категорий продуктов. Выберите категорию:».<\\/p><p>Нажмите «Сохранить».<\\/p><p>Нажмите «+ КНОПКА» и введите «Пицца».&nbsp;<br>Нажмите&nbsp;Enter.<\\/p><p>Кнопка «В главное меню» с прошлого урока остаётся на месте и по-прежнему ведёт в главное меню.<\\/p><p>&nbsp;<\\/p><p><strong>Создание блока чтения таблицы<\\/strong><\\/p><p>Теперь создадим отдельный экран, на котором будет только блок чтения данных.<\\/p><p>Проведите мышью в свободной области справа от экрана выбора категорий.&nbsp;<br>Нажмите «+ Добавить экран».<\\/p><p>Выберите блок «Интеграция с&nbsp;Google Таблицами».<\\/p><p>В поле «Аккаунт» проверьте, что выбран ваш аккаунт&nbsp;Google.<\\/p><p>В поле «ID таблицы» вставьте идентификатор вашей копии датасета.&nbsp;<br>Он указан в адресной строке браузера между частями ссылки&nbsp;\\/d\\/ и&nbsp;\\/edit.&nbsp;<br>В поле «Лист таблицы» выберите «Меню и Товары».<\\/p><p>В поле «Действие» выберите «Получить значение».<\\/p><p>Ниже находится «Список параметров для записи»:&nbsp;<br>пары полей, где левое поле — это имя переменной, а правое — адрес ячейки.<\\/p><p>В левое поле введите имя переменной:&nbsp;pizza1_name<\\/p><p>В правое поле введите адрес ячейки:&nbsp;B2<\\/p><p>Нажмите «+ Добавить значение». Появится новая пара полей.<\\/p><p>В новой паре в левое поле введите:&nbsp;pizza1_price<\\/p><p>В правое поле введите:&nbsp;E2<\\/p><p>Повторите добавление пар для остальных четырёх пицц.&nbsp;<br>Всего в блоке должно получиться десять пар:<\\/p><p>pizza1_name → B2 и pizza1_price → E2<\\/p><p>pizza2_name → B3 и pizza2_price → E3<\\/p><p>pizza3_name → B4 и pizza3_price → E4<\\/p><p>pizza4_name → B5 и pizza4_price → E5<\\/p><p>pizza5_name → B6 и pizza5_price → E6<\\/p><p>(Значок&nbsp;$ слева от поля стоит в интерфейсе для обозначения типа поля и не является частью того, что вы вводите).<\\/p><p>Используйте только английские буквы, цифры и знак подчёркивания в именах переменных, без пробелов.<\\/p><p>Проверьте: в блоке видны все десять пар, адреса написаны латинскими буквами и цифрами (B2,&nbsp;E2 и так далее), а не русскими буквами «В» и «Е».&nbsp;<br>Это частая ошибка новичков - русская «В» и английская&nbsp;B выглядят одинаково, но для&nbsp;Aimylogic это разные символы.<\\/p><p>Нажмите «Сохранить» в окне блока.<\\/p><p>Результат: блок чтения настроен, десять ячеек привязаны к десяти переменным.<\\/p><p>&nbsp;<\\/p><p><strong>Вывод данных в сообщение бота<\\/strong><\\/p><p>У блока чтения два выхода снизу:&nbsp;<br>«Данные сохранены» и «Ошибка сохранения».&nbsp;<br>Это разные пути сценария:&nbsp;<br>один для удачного чтения, другой для сбоя, например если&nbsp;Google Таблицы временно недоступны.&nbsp;<br>Текст со списком пицц, нужно подключить к выходу «Данные сохранены», на отдельном экране.<\\/p><p>Справа от экрана с блоком чтения добавьте новый экран: «+ Добавить экран».<\\/p><p>Выберите блок «Текст».<\\/p><p>Введите сообщение, нажимая&nbsp;Enter для перехода на новую строку:<\\/p><p>Пицца:<\\/p><p>$pizza1_name — $pizza1_price тг<\\/p><p>$pizza2_name — $pizza2_price тг<\\/p><p>$pizza3_name — $pizza3_price тг<\\/p><p>$pizza4_name — $pizza4_price тг<\\/p><p>$pizza5_name — $pizza5_price тг<\\/p><p>Нажмите «Сохранить».<\\/p><p>&nbsp;<\\/p><p>В знаке доллара перед именем переменной в тексте сообщения есть смысл:&nbsp;<br>это способ сказать&nbsp;Aimylogic «вставь сюда значение переменной»,&nbsp;<br>а не «обратись к ячейке&nbsp;B2» заново.&nbsp;<br>Переменная уже прочитана блоком выше, текст только берёт готовое значение.<\\/p><p>&nbsp;<\\/p><p>На этом же экране, нажмите «+ КНОПКА» и введите «К категориям».&nbsp;<br>Нажмите&nbsp;Enter.<\\/p><p>Ещё раз нажмите «+ КНОПКА» и введите «В главное меню».&nbsp;<br>Нажмите&nbsp;Enter.<\\/p><p>&nbsp;<\\/p><p>Ниже экрана для пицц, создайте ещё один экран, на этот раз для случая ошибки:&nbsp;<br>«+ Добавить экран», блок «Текст»,&nbsp;<br>сообщение «Не удалось загрузить список продуктов. Попробуйте позже» .<br>Добавьте кнопку «В главное меню».<\\/p><p>&nbsp;<\\/p><p>Теперь соедините экраны стрелками:<\\/p><p>- на экране выбора категорий продуктов протяните стрелку от кнопки «Пицца» к экрану с блоком интеграции&nbsp;Google-таблицы;<\\/p><p>- на экране с блоком интеграции&nbsp;Google-таблицы, наведите курсор на круглый маркер справа от строки «Данные сохранены», зажмите левую кнопку мыши и протяните стрелку на экран со списком пицц;<\\/p><p>- от строки «Ошибка сохранения» протяните стрелку на экран с сообщением об ошибке;<\\/p><p>на экране со списком пицц протяните стрелку от кнопки «К категориям» на экран списка категорий продуктов;<\\/p><p>- на экране со списком пицц протяните стрелку от кнопки «В главное меню» на экран главного меню;<\\/p><p>- на экране с сообщением об ошибке протяните стрелку от кнопки «В главное меню» на экран главного меню.<\\/p><p>&nbsp;<\\/p><p>Для отслеживания связей-стрелок - вы можете навести указатель мыши на соответствующую связь или на круглишки входа и выхода данной связи - связь-стрелка подсветится жёлтым.<\\/p><p>Проверьте: от каждой кнопки и от каждого выхода каждого экрана - тянется стрелка и нет обрывов.<\\/p><p>&nbsp;<\\/p><p>Результат: четыре экрана ветки «Пицца» связаны между собой, включая путь на случай сбоя.<\\/p><p>&nbsp;<\\/p><p><strong>Публикация и проверка в&nbsp;Telegram<\\/strong><\\/p><p>В правом верхнем углу конструктора нажмите «Сохранить», затем «Опубликовать».&nbsp;<br>Дождитесь завершения публикации.<\\/p><p>Откройте&nbsp;Telegram, откройте чат с вашим ботом.<\\/p><p>Для чистой проверки очистите историю:&nbsp;<br>нажмите три вертикальные точки в правом верхнем углу чата → «Очистить историю».<\\/p><p>Отправьте команду \\/start.<\\/p><p>Нажмите «На главное меню» → «Посмотреть меню» → «Пицца».<\\/p><p>Ожидаемый результат: бот присылает сообщение:<\\/p><p>Пицца:<\\/p><p>Пицца Пепперони (30 см) — 3200 тг<\\/p><p>Пицца Маргарита (30 см) — 2600 тг<\\/p><p>Пицца 4 Сыра (30 см) — 3600 тг<\\/p><p>Пицца Сборная мясная (30 см) — 3900 тг<\\/p><p>Пицца Цыпленок Барбекю (30 см) — 3400 тг<\\/p><p>&nbsp;<\\/p><p>Проверьте: каждая строка совпадает с таблицей.&nbsp;<br>Нажмите «К категориям» и убедитесь, что бот возвращает вас на выбор категории,&nbsp;<br>а кнопка «В главное меню» ведёт в главное меню.<\\/p><p>&nbsp;<\\/p><p><strong>Если что-то пошло не так<\\/strong><\\/p><p>Разберём типичные проблемы по порядку.&nbsp;<br>Не меняйте несколько настроек одновременно.<\\/p><p>&nbsp;<\\/p><p>Бот отвечает «Сожалеем, произошла техническая ошибка» вместо меню.&nbsp;<br>Значит, выход «Ошибка сохранения» не был подключён к отдельному экрану, либо сам блок чтения сломан изнутри.&nbsp;<br>Если проверка полей не помогает, самый надёжный способ — удалить блок интеграции Google-таблицы полностью и создать его заново с нуля, заново вписав аккаунт, таблицу, лист и все пары переменных (или, лучше начать с одной пары переменных).&nbsp;<br>Иногда блок сохраняет внутри себя неверную ссылку на переменную ещё с момента первой настройки, и обычное исправление полей её не убирает, помогает только пересоздание блока.<\\/p><p>&nbsp;<\\/p><p>Вместо названия в сообщении виден текст вроде $pizza1_name.&nbsp;<br>Переменная не заполнилась.&nbsp;<br>Проверьте, что имя в блоке чтения совпадает с именем в тексте без единой опечатки, и что блок чтения стоит на экране раньше текстового блока по ходу сценария.<\\/p><p>&nbsp;<\\/p><p>Вместо цены пусто.&nbsp;<br>Проверьте адрес ячейки:&nbsp;<br>возможно, вы указали ячейку не из столбца&nbsp;E, или в ней нет данных.<\\/p><p>&nbsp;<\\/p><p>Вместо нужного продукта показана другая позиция.&nbsp;<br>Адрес указывает на другую строку.&nbsp;<br>Сверьте номера строк с таблицей.<\\/p><p>&nbsp;<\\/p><p>В поле «Таблица» нет вашей копии.&nbsp;<br>Aimylogic подключён к другому аккаунту&nbsp;Google, не к тому, где лежит копия.&nbsp;<br>Вернитесь в настройки интеграций и подключите нужный аккаунт.<\\/p><p>&nbsp;<\\/p><p>Бот показывает старый вариант меню.&nbsp;<br>Нажмите «Опубликовать» ещё раз и заново пройдите маршрут от \\/start.<\\/p><p>&nbsp;<\\/p><p>Блок вообще не отвечает.&nbsp;<br>Google ограничивает количество запросов к таблице в минуту.&nbsp;<br>Подождите минуту и повторите.<\\/p><p>&nbsp;<\\/p><p>Если не получается - обратитесь к ИИ.<\\/p><p>&nbsp;<\\/p><p><strong>Синхронизация: как изменения в таблице попадают в бота<\\/strong><\\/p><p>Теперь самое важное:&nbsp;<br>проверим, что бот действительно читает таблицу, а не хранит свою копию данных.<\\/p><p>Откройте свою копию датасета, лист «Меню и Товары».&nbsp;<br>Нажмите на ячейку&nbsp;E2 (цена Пиццы Пепперони).&nbsp;<br>Замените 3200 на 3300 и нажмите&nbsp;Enter.<\\/p><p>Не закрывайте таблицу.&nbsp;<br>Откройте&nbsp;Telegram, нажмите в боте «К категориям» → «Пицца».<\\/p><p>Ожидаемый результат: в первой строке цена изменилась на 3300 тг.&nbsp;<br>Публиковать бота заново не нужно - сценарий мы не меняли, изменились только данные в таблице.<\\/p><p>&nbsp;<\\/p><p>Важная деталь: уже отправленные сообщения в чате не меняются.&nbsp;<br>Старое сообщение со старой ценой останется выше в переписке.&nbsp;<br>Обновлённые данные приходят только в новом сообщении, после повторного нажатия на кнопку.<\\/p><p>Теперь верните исходную цену: в ячейке&nbsp;E2 введите 3200 и нажмите&nbsp;Enter.<\\/p><p>Проверьте: после повторного нажатия «Пицца» бот снова показывает 3200 тг.<\\/p><p>&nbsp;<\\/p><p>Из этого вытекает правило.&nbsp;<br>Пока содержимое меню правится в таблице, публиковать бота заново не требуется. Публикация нужна, когда вы меняете сам сценарий:&nbsp;<br>кнопки, тексты в блоках, стрелки, переменные.<\\/p><p>&nbsp;<\\/p><p>Чего нельзя делать с таблицей, когда к ней подключён бот.<\\/p><p>Бот читает ячейки по адресам, а не по названиям блюд.&nbsp;<br>Если адрес «B2» привязан к Пицце Пепперони, бот будет читать&nbsp;B2 всегда, даже если там окажется другое блюдо.&nbsp;<br>Поэтому:<br>- не вставляйте новые строки в середину категории Пицца и не удаляйте существующие, иначе содержимое адресов&nbsp;B2–B6 сместится;<\\/p><p>- не сортируйте лист «Меню и Товары», иначе строки поменяются местами и бот покажет другие блюда;<\\/p><p>- не переименовывайте лист «Меню и Товары»: бот привязан к листу по названию;<\\/p><p>- не удаляйте и не перемещайте столбцы&nbsp;B и&nbsp;E.<\\/p><p>Если вам нужно добавить блюдо, пишите его в конец таблицы или меняйте значения в существующих строках.&nbsp;<br>Если вы всё же изменили структуру листа, вернитесь в блок чтения и перепроверьте адреса ячеек.<\\/p><p>&nbsp;<\\/p><p>Если не получается - обратитесь к ИИ.<\\/p><p>&nbsp;<\\/p><p><strong>Что должно получиться в конце урока<\\/strong><\\/p><p>К концу урока у вас должны быть:<\\/p><p>- подключён&nbsp;Google-аккаунт в интеграциях&nbsp;Aimylogic;<\\/p><p>- экран выбора категорий с кнопками «Пицца» и «В главное меню»;<\\/p><p>- отдельный экран с блоком интеграции (чтения) Google-таблицы, у которого оба выхода подключены к своим экранам;<\\/p><p>- экран «Продукты из категории Пицца» с текстовым сообщением на основе переменных;<\\/p><p>- экран с сообщением об ошибке на случай сбоя чтения;<\\/p><p>- десять переменных для названий и цен пяти пицц;<\\/p><p>- готовая публикация бота;<\\/p><p>- проверка в&nbsp;Telegram: меню совпадает с таблицей;<\\/p><p>- проверка синхронизации: изменение цены в таблице отразилось в боте.<\\/p>\",\"tests\":[{\"question\":\"Для чего в Aimylogic используется блок «Интеграция с Google таблицами»?\",\"answers\":[\"Для создания новых аккаунтов Google для Google-таблиц\",\"Для изменения имени Telegram-бота через Google-таблицы\",\"Для публикации Google-таблицы в интернете\",\"Для чтения данных из таблицы и записи данных в неё ✓\"],\"correct\":null},{\"question\":\"Как записывается адрес ячейки при чтении значения из таблицы?\",\"answers\":[\"Номер строки и название листа\",\"Название столбца и слово «ячейка»\",\"Название блюда или товара\",\"Буква столбца и номер строки ✓\"],\"correct\":null},{\"question\":\"Что произойдёт, если изменить цену в таблице после публикации бота?\",\"answers\":[\"Бот обновится только после сохранения и публикации проекта в Aimylogic\",\"Новая цена появится в новых сообщениях бота при повторном обращении к данным ✓\",\"Бот перестанет работать до повторной публикации\",\"В старых сообщениях чата цена изменится автоматически\"],\"correct\":null},{\"question\":\"Чем опасна вставка новой строки в середину столбца таблицы, который читает бот?\",\"answers\":[\"Aimylogic автоматически отключит Telegram от Google-таблицы\",\"Таблица перестанет открываться в браузере\",\"Адреса ячеек сместятся, и бот может показать другие позиции ✓\",\"Все переменные получат одинаковое значение\"],\"correct\":null},{\"question\":\"Что означает ситуация, когда в сообщении бота вместо значения виден текст\\/имя самой переменной?\",\"answers\":[\"Telegram заблокировал бота или разорвалась связь с Google-таблицей\",\"Переменная не заполнилась, и нужно проверить блок интеграции и совпадение имён ✓\",\"Таблица удалена с Google Диска или не доступна или нет интернета\",\"Сообщение слишком длинное для Telegram\"],\"correct\":null},{\"question\":\"Для чего нужна переменная в блоке интеграции (чтения) таблицы?\",\"answers\":[\"Чтобы изменить оформление таблицы\",\"Чтобы запретить редактирование таблицы\",\"Чтобы удалить прочитанную ячейку\",\"Чтобы временно хранить прочитанное значение и использовать его в других блоках ✓\"],\"correct\":null},{\"question\":\"Что нужно сделать после изменения кнопок и текстов в сценарии, чтобы они заработали в Telegram?\",\"answers\":[\"Опубликовать сценарий и пройти маршрут в Telegram заново ✓\",\"Закрыть вкладку с конструктором, чтобы изменения сохранились и опубликовались в Telegram\",\"Создать нового бота в BotFather и свзять его со сценарием\",\"Заново получить API-токен бота в Telegram\"],\"correct\":null}],\"lab\":\"<p>Цель лабораторной работы — самостоятельно расширить меню бота ещё одной категорией и проверить, что вы умеете находить данные в таблице и исправлять ошибки подключения.<\\/p><p>Задание выполняйте без пошаговой инструкции из теории:&nbsp;<br>вы должны сами определить, какие строки таблицы нужны и какие блоки использовать.<\\/p><p>&nbsp;<\\/p><p><strong>Задача 1. Найти данные категории «Напитки»<\\/strong><\\/p><p>Откройте лист «Меню и Товары» вашей копии датасета.<\\/p><p>В столбце&nbsp;C (Категория) найдите все строки со значением «Напитки».<\\/p><p>Определите номера первой и последней строки категории.<\\/p><p>Выпишите на листок или в блокнот пары адресов:&nbsp;<br>для каждого напитка ячейку из столбца&nbsp;B (Наименование) и ячейку из столбца&nbsp;E (Цена_Продажи_Тг).<\\/p><p>Проверьте: напитков должно быть пять, а пар адресов столько же.&nbsp;<br>Все пары принадлежат одной категории, и ни одна пара не относится к соседней категории.<\\/p><p>&nbsp;<\\/p><p><strong>Задача 2. Добавить категорию в меню бота<\\/strong><\\/p><p>Откройте в конструкторе экран выбора категорий.<\\/p><p>Добавьте кнопку «Напитки».<\\/p><p>Создайте новый экран для блока интеграции с&nbsp;Google-таблицей и чтения этой категории и ещё два экрана: один для вывода списка напитков, другой для сообщения об ошибке.<\\/p><p>На экране чтения настройте блок:&nbsp;<br>выберите свою копию датасета, лист «Меню и Товары», действие «Получить значение», введите адреса из задачи 1 и придумайте понятные имена переменных (без знака доллара), например&nbsp;drink1_name и&nbsp;drink1_price.<\\/p><p>На экране вывода добавьте текстовый блок с названием категории и списком напитков (название и цена каждого напитка через переменные), а также кнопки «К категориям» и «В главное меню».<\\/p><p>На экране ошибки добавьте сообщение о сбое и кнопку «В главное меню».<\\/p><p>Свяжите стрелками:&nbsp;<br>кнопку «Напитки» с экраном чтения;&nbsp;<br>выход «Данные сохранены» с экраном вывода списка;&nbsp;<br>выход «Ошибка сохранения» с экраном ошибки;&nbsp;<br>кнопки возврата с соответствующими экранами.<\\/p><p>Опубликуйте сценарий.<\\/p><p>&nbsp;<\\/p><p>Проверьте: в конструкторе нет кнопок и выходов без связи, а имена переменных в блоке чтения и в тексте совпадают.<\\/p><p>&nbsp;<\\/p><p><strong>Задача 3. Сверить результат бота с таблицей<\\/strong><\\/p><p>Откройте&nbsp;Telegram, перезапустите бота командой \\/start и пройдите маршрут до списка напитков.<\\/p><p>Сравните каждую строку списка в боте с таблицей:&nbsp;<br>название и цена каждого напитка должны совпадать полностью.<\\/p><p>Если есть расхождения, найдите причину по списку проблем из теории, исправьте и опубликуйте заново.<\\/p><p>Проверьте: все пять напитков видны, цены совпадают с таблицей, кнопки «К категориям» и «В главное меню» работают.<\\/p><p>&nbsp;<\\/p><p><strong>Задача 4. Диагностика ошибки в адресе<\\/strong><\\/p><p>Эта задача нужна, чтобы вы научились узнавать неисправность по признаку.<\\/p><p>Откройте блок чтения экрана «Напитки».<\\/p><p>В одной из пар замените адрес ячейки цены на адрес пустой ячейки:&nbsp;<br>например, в столбце&nbsp;E на несколько строк ниже конца данных.&nbsp;<br>Эту ячейку выберите самостоятельно, проверив в таблице, что она пустая.<\\/p><p>Опубликуйте сценарий и откройте список напитков в&nbsp;Telegram.<\\/p><p>Запишите, что именно бот показал вместо цены этого напитка.<\\/p><p>Верните правильный адрес, опубликуйте заново и убедитесь, что ошибка исчезла.<\\/p><p>Проверьте: цена напитка снова отображается, а в ваших записях есть описание того, как выглядела ошибка.<\\/p><p>&nbsp;<\\/p><p><strong>Задача 5. Полностью самостоятельно, без подсказок, добавьте в сценарий обработку ещё одной категории, например Суши и Роллы.<\\/strong><\\/p><p>Протестируйте в&nbsp;Telegram что все возможные пути новой ветки работают.<\\/p><p>&nbsp;<\\/p><p>Если не получается - обратитесь к ИИ.<\\/p><p>&nbsp;<\\/p><p><strong>Задача 6. Итоговая проверка всех веток<\\/strong><\\/p><p>В&nbsp;Telegram очистите историю чата и запустите бота командой \\/start.<\\/p><p>Пройдите по очереди все ветки: «Посмотреть меню» → «Пицца», «Посмотреть меню» → «Напитки», «Посмотреть меню» → «Суши и Роллы», «Режим работы», «Связаться с оператором».<\\/p><p>Из каждой ветки вернитесь в главное меню.<\\/p><p>&nbsp;<\\/p><p>После выполнения лабораторной вы должны самостоятельно уметь найти нужную категорию на листе «Меню и Товары», определить адреса ячеек, прочитать их через блок «Интеграция с&nbsp;Google Таблицами» без ошибок синтаксиса, вывести результат клиенту в&nbsp;Telegram и найти причину, если данные не отображаются.<\\/p>\"}');
INSERT INTO `lessons` (`id`, `section_id`, `title_ru`, `slug`, `lesson_order`, `content`) VALUES
(9, 4, '2.4. Приём данных клиента и запись заказа в Google Таблицу через Aimylogic', 'recording-order-in-table', 4, '{\"theory\":\"<p>В прошлом уроке бот научился читать меню из вашей&nbsp;Google Таблицы и показывать его клиенту в&nbsp;Telegram.&nbsp;<br>Это было одностороннее движение данных: таблица → бот → клиент.&nbsp;<br>Теперь сделаем обратное движение: клиент → бот → таблица.<\\/p><p>В конце урока в&nbsp;Telegram должен работать такой маршрут:<\\/p><p>Главное меню → «Оформить заказ» → бот спрашивает имя → клиент отвечает → бот спрашивает адрес → клиент отвечает → бот спрашивает телефон → клиент отвечает → бот показывает сообщение с введёнными данными для проверки → данные записываются новой строкой в&nbsp;Google Таблицу.<\\/p><p>&nbsp;<\\/p><p><strong>Зачем нужен сбор данных через диалог<\\/strong><\\/p><p>До сих пор клиент только нажимал кнопки и получал готовые сообщения.&nbsp;<br>Для реального заказа этого недостаточно:&nbsp;<br>бот должен узнать, кому доставлять заказ, куда и по какому номеру телефона связаться.<\\/p><p>Для этого в&nbsp;Aimylogic есть специальный блок, который одновременно отправляет вопрос клиенту и сохраняет его ответ в переменную.<\\/p><p>&nbsp;<\\/p><p><strong>Блок «text&nbsp;to $var»: что это и как он работает<\\/strong><\\/p><p>В панели блоков, в разделе «Еще блоки», находится блок «text to $var».&nbsp;<br>Его название можно перевести как «текст в переменную»:&nbsp;<br>это ровно то, что он делает.<\\/p><p>&nbsp;<\\/p><p>У блока две части:<\\/p><p>Поле «Сообщение» — текст вопроса, который бот отправит клиенту.<\\/p><p>Поле «Имя переменной» — «коробочка», в которую бот положит то, что клиент напишет в ответ.&nbsp;<br>Слева от поля уже стоит знак $, вводить его самому не нужно.<\\/p><p>В отличие от блока «Текст», после отправки сообщения сценарий не идёт дальше автоматически:&nbsp;<br>блок «text to $var» ждёт, пока клиент что-то напишет, и только после этого сохраняет ответ и передаёт сценарий дальше.&nbsp;<\\/p><p>Это важное отличие, которое и делает возможным сбор данных.<\\/p><p>&nbsp;<\\/p><p>Вы уже работали с переменными в прошлом уроке, когда читали значения из таблицы. Разница в том, что тогда переменную заполняла Google Таблица, а теперь переменную заполнит сам клиент, напечатав ответ в чате.<\\/p><p>&nbsp;<\\/p><p><strong>Создание первого вопроса — имя клиента<\\/strong><\\/p><p>Откройте сайт&nbsp;Aimylogic → войдите в свой аккаунт → откройте проект с вашим ботом («Доставка Петропавл -&nbsp;Telegram») → в вертикальном меню слева нажмите «Конструктор».<\\/p><p>Найдите на рабочем поле блок «Главное меню» (тот, где уже есть кнопки «Посмотреть меню», «Режим работы», «Связаться с оператором»).<\\/p><p>Нажмите на блок «Главное меню», чтобы открыть его редактирование.<\\/p><p>Нажмите «+ КНОПКА» и введите текст: <code>Оформить заказ<\\/code> .<\\/p><p>Нажмите&nbsp;Enter.<\\/p><p>Результат: в главном меню появилась четвёртая кнопка «Оформить заказ».<\\/p><p>&nbsp;<\\/p><p>Проведите мышью в свободной области снизу от экрана главного меню.&nbsp;<br>Появится кнопка «+ Добавить экран».<\\/p><p>Нажмите на неё.&nbsp;<br>В панели блоков откройте раздел «Еще блоки» и найдите блок «text to $var».<\\/p><p>Добавьте блок на рабочее поле.<\\/p><p>В открывшемся окне блока в поле «Сообщение» введите:&nbsp;<br><code>Для оформления заказа назовите, пожалуйста, ваше имя<\\/code><\\/p><p>В поле «Имя переменной» (после знака $) введите:<\\/p><p><code>client_name<\\/code><\\/p><p>Используйте только английские буквы, цифры и знак подчёркивания в имени переменной, без пробелов и без русских букв — то же правило, что уже применялось для переменных чтения из таблицы в прошлом уроке.<\\/p><p>Нажмите «Сохранить».<\\/p><p>Проверьте: на рабочем поле появился новый экран с вопросом об имени, а в блоке указана переменная&nbsp;client_name.<\\/p><p>&nbsp;<\\/p><p>Соедините кнопку «Оформить заказ» на экране главного меню с новым экраном для ввода имени.<\\/p><p>&nbsp;<\\/p><p><strong>Создание второго вопроса — адрес доставки<\\/strong><\\/p><p>Проведите мышью в свободной области ниже от экрана с вопросом об имени.&nbsp;<br>Нажмите «+ Добавить экран».<\\/p><p>В разделе «Еще блоки» снова выберите «text to $var».<\\/p><p>В поле «Сообщение» введите:&nbsp;<\\/p><p><code>Укажите, пожалуйста, улицу и номер дома для доставки<\\/code> .<\\/p><p>В поле «Имя переменной» введите:<\\/p><p><code>client_address<\\/code><\\/p><p>Нажмите «Сохранить».<\\/p><p>&nbsp;<\\/p><p>Соедините экран с вопросом об имени с новым экраном с вопросом об адресе.<\\/p><p>Проверьте: после ответа на вопрос об имени сценарий должен переходить именно к вопросу об адресе, а не возвращаться в меню.<\\/p><p>&nbsp;<\\/p><p><strong>Создание третьего вопроса — номер телефона<\\/strong><\\/p><p>Проведите мышью снизу от экрана с вопросом об адресе.&nbsp;<br>Нажмите «+ Добавить экран».<\\/p><p>Снова выберите блок «text to $var».<\\/p><p>В поле «Сообщение» введите:&nbsp;<br><code>Напишите, пожалуйста, номер телефона для связи с курьером<\\/code> .<\\/p><p>В поле «Имя переменной» введите:<\\/p><p><code>client_phone<\\/code><\\/p><p>Нажмите «Сохранить».<\\/p><p>Соедините экран с вопросом об адресе с новым экраном вопроса о телефоне.<\\/p><p>&nbsp;<\\/p><p>Результат: три вопроса идут строго друг за другом: имя → адрес → телефон, и каждый ответ сохраняется в свою отдельную переменную сразу в момент ответа.<\\/p><p>&nbsp;<\\/p><p><strong>Подстановка переменных в итоговое сообщение<\\/strong><\\/p><p>Теперь нужно показать клиенту, что бот правильно понял и сохранил все три ответа.&nbsp;<br>Для этого используем тот же приём со знаком доллара, который уже применялся в прошлом уроке для подстановки названий и цен блюд.<\\/p><p>&nbsp;<\\/p><p>Проведите мышью справа от экрана с вопросом о телефоне.&nbsp;<br>Нажмите «+ Добавить экран».<\\/p><p>На этот раз выберите обычный блок «Текст»&nbsp;<br>(не «text to $var», так как дальше бот должен просто показать итог, а не ждать ещё один ответ).<\\/p><p>В поле текста введите, нажимая&nbsp;Enter для перехода на новую строку:<code>Проверьте, пожалуйста, данные заказа:<\\/code><\\/p><code><p>Имя: $client_name<\\/p><p>Адрес доставки: $client_address<\\/p><\\/code><p><code>Телефон: $client_phone<\\/code><\\/p><p>Нажмите «Сохранить».<\\/p><p>Соедините выход экрана с вопросом о телефоне с новым текстовым экраном.<\\/p><p>&nbsp;<\\/p><p>Добавьте на этом же экране кнопку «В главное меню» и протяните от неё стрелку назад к экрану главного меню.<\\/p><p>&nbsp;<\\/p><p><strong>Проверка сбора данных до записи в таблицу<\\/strong><\\/p><p>Прежде чем подключать запись в&nbsp;Google Таблицу, нужно убедиться, что сам диалог работает правильно.<\\/p><p>В правом верхнем углу конструктора нажмите «Сохранить», затем «Опубликовать».&nbsp;<br>Дождитесь окончания публикации.<\\/p><p>&nbsp;<\\/p><p>Откройте&nbsp;Telegram, откройте чат с вашим ботом.<\\/p><p>Очистите историю чата (три вертикальные точки в правом верхнем углу чата → «Очистить историю»).<\\/p><p>Отправьте команду <code>\\/start<\\/code> .<\\/p><p>Нажмите «На главное меню» → «Оформить заказ».<\\/p><p>Бот должен спросить имя.&nbsp;<br>Напишите в чат любое тестовое имя, например: <code>Данияр<\\/code> .<\\/p><p>Бот должен сразу спросить адрес.&nbsp;<br>Напишите, например: <code>ул. Абая, д. 10<\\/code> .<\\/p><p>Бот должен спросить телефон.&nbsp;<br>Напишите, например: <code>777-777-77-77<\\/code> .<\\/p><p>Ожидаемый результат — итоговое сообщение:<\\/p><p>Проверьте, пожалуйста, данные заказа:<\\/p><p>Имя: Данияр<\\/p><p>Адрес доставки: ул. Абая, д. 10<\\/p><p>Телефон: 777-777-77-77<\\/p><p>Проверьте: каждое введённое вами значение появилось на своей строке, а не перепуталось местами.&nbsp;<br>&nbsp;<\\/p><p>Если вместо значения видно $client_name или похожий текст — значит, имя переменной в блоке «textto $var» и в тексте итогового сообщения написано по-разному;&nbsp;<br>сверьте оба места буква в букву.<\\/p><p>Если бот не дожидается ответа и сразу задаёт следующий вопрос.&nbsp;<br>Такое бывает, если вместо блока «text to $var» случайно был добавлен блок «Текст».&nbsp;<br>Удалите такой экран и создайте заново именно блок «text to $var».<\\/p><p>&nbsp;<\\/p><p><strong>Подготовка листа для записи заказов<\\/strong><\\/p><p>Прежде чем настраивать запись, в таблице должен быть лист, куда бот будет вносить новые строки.<\\/p><p>Откройте свою копию датасета в&nbsp;Google Таблицах.<\\/p><p>Внизу окна, рядом с вкладками листов, нажмите кнопку «+» (добавить лист).<\\/p><p>Переименуйте новый лист: дважды щёлкните по названию вкладки и введите:<\\/p><p>\\\"Заказы из бота\\\" .<\\/p><p>В первой строке нового листа введите заголовки столбцов, каждый в своей ячейке:<\\/p><p>A1: <code>Имя_Клиента<\\/code><\\/p><p>B1: <code>Адрес_Доставки<\\/code><\\/p><p>C1: <code>Телефон<\\/code><\\/p><p>Проверьте: новый лист называется точно «Заказы из бота», без лишних пробелов, а в строке 1 заполнены все три заголовка.<\\/p><p>Это важно:&nbsp;Aimylogic привязывается к листу по его точному названию.&nbsp;<br>Если название будет отличаться хотя бы на один пробел или регистр буквы, бот не найдёт лист.<\\/p><p>&nbsp;<\\/p><p><strong>Настройка блока записи в&nbsp;Google Таблицу<\\/strong><\\/p><p>Теперь добавим блок, который берёт три сохранённые переменные и записывает их новой строкой на лист «Заказы из бота».<\\/p><p>Вернитесь в Aimylogic, в конструктор.<\\/p><p>Откройте текстовый экран с итоговым сообщением&nbsp;<br>(«Проверьте, пожалуйста, данные заказа...»).<\\/p><p>Проведите мышью в свободной области справа от этого экрана.&nbsp;<br>Нажмите «+ Добавить экран».<br>(«+ Добавить экран» может быть не точно справа, а где ни будь выше, под другими блоками справа, короче найдите эту всплывающую кнопку).<\\/p><p>&nbsp;<\\/p><p>В панели блоков, в разделе «Действия», найдите блок «Интеграция с Google-таблицами» — тот же блок, который вы уже использовали в прошлом уроке для чтения меню.<\\/p><p>Добавьте блок на рабочее поле.<\\/p><p>В поле «Аккаунт» проверьте, что указан тот же Google-аккаунт, где лежит ваша копия датасета.<\\/p><p>В поле «ID таблицы» вставьте тот же идентификатор таблицы, который вы уже использовали в прошлом уроке (часть ссылки между \\/d\\/ и \\/edit).<\\/p><p>В поле \\\"Лист таблицы\\\" выберите:<\\/p><p><code>Заказы из бота<\\/code><\\/p><p>В поле «Действие» на этот раз выберите не «Получить значение», а «Сохранить в строку».<\\/p><p>Ниже появится раздел «Список параметров для записи» с одним полем «Значение или переменная».<\\/p><p>&nbsp;<\\/p><p>Важное правило этого блока:&nbsp;<br>поля заполняются строго по порядку, и каждое следующее поле попадает в следующий по порядку столбец листа слева направо.&nbsp;<br>То есть первое заполненное поле автоматически окажется в столбце&nbsp;A, второе — в столбце&nbsp;B, третье — в столбце&nbsp;C, и так далее.&nbsp;<br>Отдельно указать номер или название столбца тут нельзя — только сам порядок добавления полей определяет, куда попадёт значение.&nbsp;<br>Поэтому заполнять поля нужно строго в том порядке, в котором расположены столбцы на листе «Заказы из бота»:&nbsp;<br>A — Имя_Клиента,&nbsp;B — Адрес_Доставки,&nbsp;C — Телефон.<\\/p><p>В первое поле «Значение или переменная» введите переменную:<\\/p><p><code>$client_name<\\/code><\\/p><p>Нажмите «+ Добавить значение».&nbsp;<br>Появится второе поле.<\\/p><p>Во второе поле введите переменную:<\\/p><p><code>$client_address<\\/code><\\/p><p>Нажмите «+ Добавить значение».&nbsp;<br>Появится третье поле.<\\/p><p>В третье поле введите переменную:<\\/p><p><code>$client_phone<\\/code><\\/p><p>Нажмите «Сохранить» в окне блока.<\\/p><p>Двойным кликом снова откройте блок на редактирование.<\\/p><p>Проверьте: в блоке видно три поля по порядку — $client_name, $client_address, $client_phone, а название листа указано точно «Заказы из бота».<\\/p><p>&nbsp;<\\/p><p><strong>Экраны результата записи: успех и ошибка.<\\/strong><\\/p><p>У блока записи, как и у блока чтения из прошлого урока, два выхода:&nbsp;<br>для успешного результата и для ошибки.<\\/p><p>Проведите мышью снизу от блока записи.&nbsp;<br>Нажмите «+ Добавить экран», выберите блок «Текст».<\\/p><p>Введите сообщение:&nbsp;<br><code>Спасибо! Ваш заказ принят, мы свяжемся с вами для подтверждения<\\/code> .<\\/p><p>Нажмите «Сохранить».<\\/p><p>Добавьте на этом экране кнопку «В главное меню».<\\/p><p>Наведите курсор на маркер выхода «Данные сохранены» (или похожей подписи) у блока записи, зажмите левую кнопку мыши и протяните стрелку к новому экрану подтверждения принятия заказа.<\\/p><p>Создайте ещё один экран для случая ошибки:&nbsp;<br>«+ Добавить экран» → блок «Текст» → сообщение <code>Не удалось сохранить заказ. Попробуйте ещё раз или свяжитесь с оператором<\\/code> .<\\/p><p>Добавьте кнопку «В главное меню».<\\/p><p>Протяните стрелку от выхода «Ошибка сохранения» блока записи к новому экрану с сообщением об ошибке.<\\/p><p>Протяните стрелку от кнопки «В главное меню» на экране подтверждения, а также от кнопки «В главное меню» на экране ошибки — обратно к экрану главного меню.<\\/p><p>&nbsp;<\\/p><p><strong>Добавление кнопки подтверждения к экрану с подтверждением данных заказа.<\\/strong><\\/p><p>Перейдите на уже существующий экран с текстом:<\\/p><p><code>Проверьте, пожалуйста, данные заказа:<\\/code><\\/p><code><p>Имя: $client_name<\\/p><p>Адрес доставки: $client_address<\\/p><\\/code><p><code>Телефон: $client_phone<\\/code><\\/p><p>Нажмите «+ КНОПКА» и введите текст:&nbsp;<br><code>Подтвердить заказ<\\/code> &nbsp;<br>Нажмите&nbsp;Enter.<\\/p><p>Нажмите «Сохранить».<\\/p><p>На кнопке в Главное меню, нажмите иконку редактирования (карандаш) и замените текст \\\"В главное меню\\\" на текст \\\"Отменить заказ\\\".<\\/p><p>Поменяйте кнопки местами, чтобы кнопка \\\"Подтвердить заказ\\\" была первой.<\\/p><p>Протяните связь от кнопки \\\"Подтвердить заказ\\\" на экран интеграции с&nbsp;Google-таблицами, который записывает данные в таблицу.<\\/p><p>&nbsp;<\\/p><p>Результат: на экране подтверждения появилась кнопка, которая поведёт дальше, к записи заказа в таблицу.<\\/p><p>&nbsp;<\\/p><p>Сохраните текущее состояние сценария.<\\/p><p>&nbsp;<\\/p><p>Проверьте: весь маршрут выглядит так — вопрос об имени → вопрос об адресе → вопрос о телефоне → показ введённых данных → кнопки Подтвердить заказ или Отменить заказ → запись в таблицу → сообщение об успехе или об ошибке → возврат в главное меню.<\\/p><p>&nbsp;<\\/p><p><strong>Публикация и сквозная проверка<\\/strong><\\/p><p>В правом верхнем углу конструктора нажмите «Сохранить», затем «Опубликовать».&nbsp;<br>Дождитесь завершения.<\\/p><p>Откройте&nbsp;Telegram, откройте чат с ботом.<\\/p><p>Очистите историю чата.<\\/p><p>Отправьте \\/start → «На главное меню» → «Оформить заказ».<\\/p><p>Введите тестовое имя: <code>Айгерим<\\/code> .<\\/p><p>Введите тестовый адрес: <code>ул. Сатпаева, д. 5, кв. 12<\\/code> .<\\/p><p>Введите тестовый телефон: <code>777-777-77-77<\\/code> .<\\/p><p>Нажмите Подтвердить заказ.<\\/p><p>Ожидаемый результат:&nbsp;<br>бот показывает итоговое сообщение с этими тремя значениями, а затем — сообщение «Спасибо! Ваш заказ принят...».<\\/p><p>Не закрывая&nbsp;Telegram, откройте вашу копию датасета и перейдите на лист «Заказы из бота».<\\/p><p>Ожидаемый результат:&nbsp;<br>в строке 2 (или следующей) появились записанные данные:<\\/p><p>A2: Айгерим<\\/p><p>B2: ул. Сатпаева, д. 5, кв. 12<\\/p><p>C2: 777-777-77-77<\\/p><p>Проверьте: значения в таблице в точности совпадают с тем, что вы вводили в&nbsp;Telegram, и расположены в правильных столбцах.<\\/p><p>&nbsp;<\\/p><p><strong>Если запись не появилась в таблице<\\/strong><\\/p><p>Разберём типичные причины по порядку.&nbsp;<br>Не меняйте сразу несколько настроек, меняйте по одной и сразу проверяйте.<\\/p><p>&nbsp;<\\/p><p>- Бот показал сообщение об ошибке вместо благодарности.&nbsp;<br>Откройте блок записи и проверьте:&nbsp;<br>совпадает ли название листа в поле «Лист таблицы» с реальным названием вкладки «Заказы из бота» буква в букву, включая пробелы.<\\/p><p>&nbsp;<\\/p><p>- В таблице появилась пустая строка.&nbsp;<br>Значит, переменные не были подставлены в поля блока записи.&nbsp;<br>Откройте блок записи и проверьте, что в каждом поле действительно выбрана переменная ($client_name и так далее), а не оставлен пустой текст.<\\/p><p>&nbsp;<\\/p><p>- Данные записались не в те столбцы.&nbsp;<br>Сверьте порядок полей в блоке записи с реальным порядком столбцов на листе «Заказы из бота»:&nbsp;<br>A — Имя_Клиента,&nbsp;B — Адрес_Доставки,&nbsp;C — Телефон.<\\/p><p>&nbsp;<\\/p><p>Google ограничивает частоту запросов к таблице.&nbsp;<br>Если запись не прошла после нескольких подряд тестов, подождите минуту и повторите попытку.<\\/p><p>&nbsp;<\\/p><p>При любой ошибке, если не получается — обратитесь к ИИ.<br>Опишите проблему текстом, скопируйте сообщения об ошибке, вставьте скриншоты.<\\/p><p>&nbsp;<\\/p><p>Повторная проверка: несколько заказов подряд<\\/p><p>Важно убедиться, что бот умеет принимать не один, а несколько заказов подряд, без путаницы между клиентами.<\\/p><p>В&nbsp;Telegram снова пройдите маршрут «Оформить заказ» с другими тестовыми данными, например именем Болат, адресом ул. Желтоксан, д. 3 и телефоном 705-705-75-75.<\\/p><p>Откройте лист «Заказы из бота».<\\/p><p>Ожидаемый результат: появилась новая строка с данными Болата, а строка 2 с данными Айгерим осталась без изменений.<\\/p><p>Проверьте: каждый новый диалог создаёт именно новую строку, а не изменяет предыдущую.<\\/p><p>&nbsp;<\\/p><p><strong>Добавление даты и времени заказа<\\/strong><\\/p><p>Сейчас в каждой строке таблицы есть имя, адрес и телефон.&nbsp;<br>Для реальной работы нужно знать ещё и когда оформлен заказ.&nbsp;<br>Спрашивать это у клиента не нужно:&nbsp;<br>бот получит дату и время сам, от встроенного сервиса&nbsp;Aimylogic, с помощью блока «HTTP-запрос».<\\/p><p>Откройте свою копию датасета и перейдите на лист «Заказы из бота».&nbsp;<br>В ячейку&nbsp;D1 введите заголовок:<\\/p><p><code>Дата_Время_Заказа<\\/code><\\/p><p>Проверьте: в первой строке заполнены четыре заголовка,&nbsp;A1, B1,&nbsp;C1 и&nbsp;D1.<\\/p><p><br>Вернитесь в&nbsp;Aimylogic, в конструктор.&nbsp;<br>Найдите экран проверки данных («Проверьте, пожалуйста, данные заказа...»).&nbsp;<br>Проведите мышью в свободной области рядом с ним и нажмите «+ Добавить экран».<\\/p><p>В панели блоков, в разделе «Действия», найдите блок «HTTP-запрос» и добавьте его на рабочее поле.<\\/p><p>Метод&nbsp;GET оставьте без изменений.<\\/p><p>В поле&nbsp;URL скопируйте одной строкой, без пробелов:<\\/p><p><code>https:\\/\\/tools.aimylogic.com\\/api\\/now?tz=Asia\\/Aqtobe&amp;format=dd.MM.yyyy%20HH:mm<\\/code><\\/p><p>Здесь&nbsp;tz — часовой пояс (Asia\\/Aqtobe соответствует времени Казахстана),&nbsp;<br>format — вид результата (день.месяц.год часы:минуты),&nbsp;<\\/p><p>%20 — пробел между датой и временем.<\\/p><p>Откройте вкладку&nbsp;RESPONSE.&nbsp;<br>Нажмите «Имя и значение переменной».<\\/p><p>В поле «Имя переменной» введите:<\\/p><p><code>order_datetime<\\/code><\\/p><p>В поле «Значение» введите:<\\/p><p><code>$httpResponse.formatted<\\/code><\\/p><p>Вкладки&nbsp;BODY и&nbsp;HEADERS не заполняйте.&nbsp;<br>Нажмите «Сохранить».<\\/p><p>Результат: на рабочем поле появился блок «HTTP-запрос» с двумя выходами:&nbsp;<br>«Завершен успешно» и «Завершен с ошибкой».<\\/p><p>&nbsp;<\\/p><p>Теперь добавим полученное время в запись.&nbsp;<br>Двойным кликом откройте блок «Интеграция с&nbsp;Google-таблицами», который записывает заказ.&nbsp;<br>Снизу найдите четвёртое поле.&nbsp;<\\/p><p>(если его нет нажмите «+ Добавить значение»).<br>Введите в него:<\\/p><p><code>$order_datetime<\\/code><\\/p><p>Нажмите «Сохранить».&nbsp;<br>Двойным кликом снова откройте блок.<\\/p><p>Проверьте: в блоке четыре поля по порядку — $client_name, $client_address, $client_phone, $order_datetime.&nbsp;<br>Четвёртое поле попадёт в столбец&nbsp;D, который вы только что назвали.<\\/p><p><br>Теперь перестроим связи.&nbsp;<br>Сейчас кнопка «Подтвердить заказ» ведёт сразу к экрану записи в таблицу.&nbsp;<br>Время нужно получить раньше, поэтому цепочка должна выглядеть так: кнопка → «HTTP-запрос» → запись.<\\/p><p>На экране проверки данных, от кнопки Подтвердить заказ - протяните стрелку к блоку «HTTP-запрос».<\\/p><p>(Если видны две стрелки, наведите курсор на старую (она подсветится жёлтым) и удалите её) .<\\/p><p>В созданном экране с блоком «HTTP-запрос», от выхода «Завершен успешно» - протяните стрелку к блоку записи в&nbsp;Google Таблицу.<\\/p><p>Протяните стрелку от выхода «Завершен с ошибкой» блока «HTTP-запрос» к экрану с сообщением об ошибке («Не удалось сохранить заказ...»).<\\/p><p>&nbsp;<\\/p><p>Результат: цепочка собрана.<\\/p><p>Проверьте: маршрут выглядит так — «Подтвердить заказ» → получение даты и времени → запись в таблицу → сообщение об успехе или об ошибке → возврат в главное меню, а кнопка «Отменить заказ» по-прежнему ведёт в главное меню.&nbsp;<br>Оборванных стрелок нет.<\\/p><p>&nbsp;<\\/p><p>Нажмите «Сохранить», затем «Опубликовать».&nbsp;<br>Дождитесь завершения.<\\/p><p>&nbsp;<\\/p><p><strong>Проверка сценария добавления даты\\/времени<\\/strong><\\/p><p>В&nbsp;Telegram очистите историю чата и отправьте \\/start.&nbsp;<br>Пройдите «На главное меню» → «Оформить заказ».&nbsp;<br>Введите имя <code>Данияр<\\/code>, адрес <code>ул. Абая, д. 10<\\/code>, телефон <code>777-777-77-77<\\/code> .&nbsp;<br>На экране проверки данных нажмите «Подтвердить заказ».<\\/p><p>Ожидаемый результат:&nbsp;<br>бот присылает сообщение «Спасибо! Ваш заказ принят...».<\\/p><p>Откройте лист «Заказы из бота» в вашей&nbsp;Google-таблице.&nbsp;<br>В новой строке в столбце&nbsp;D должны быть дата и время в формате дд.мм.гггг чч:мм.<\\/p><p>Проверьте: значения в столбцах&nbsp;A,&nbsp;B и&nbsp;C на месте, а время в столбце&nbsp;D совпадает с часами вашего компьютера.<\\/p><p>Теперь проверьте отмену:&nbsp;<br>пройдите маршрут ещё раз с любыми данными, но на экране проверки данных нажмите «Отменить заказ».&nbsp;<br>Ожидаемый результат: бот показывает главное меню, а новая строка в таблице не появляется.<\\/p><p>&nbsp;<\\/p><p>Если что-то пошло не так, проверьте по порядку.<\\/p><p>- В столбце&nbsp;D пусто или длинный набор символов.&nbsp;<br>Откройте блок «HTTP-запрос», вкладку&nbsp;RESPONSE.&nbsp;<br>Значение должно быть именно $httpResponse.formatted, а имя переменной&nbsp;order_datetime должно совпадать с четвёртым полем блока записи.<\\/p><p>- Время в столбце&nbsp;D сдвинуто.&nbsp;<br>Проверьте в&nbsp;URL параметр&nbsp;tz=Asia\\/Aqtobe.<\\/p><p>- Вместо благодарности бот показал сообщение об ошибке.&nbsp;<br>Проверьте адрес в поле&nbsp;URL:&nbsp;<br>он должен быть записан одной строкой, без лишних пробелов, с %20 между датой и временем.<\\/p><p>&nbsp;<\\/p><p><strong>Что нужно запомнить<\\/strong><\\/p><p>Блок «text to $var» задаёт вопрос, ждёт ответ клиента и сохраняет его в переменную.&nbsp;<br>Блок «Текст» сразу передаёт выполнение дальше.<\\/p><p>Знак $ перед именем переменной в тексте сообщения означает подстановку сохранённого значения.<\\/p><p>Действие «Сохранить в строку» добавляет новую строку, а столбец определяется только порядком полей в блоке.<\\/p><p>Лист для записи должен существовать заранее, а его название в блоке должно совпадать буква в букву.<\\/p><p>Блок «HTTP-запрос» обращается к внешнему сервису и сохраняет ответ в переменную.&nbsp;<br>У него два выхода: успешное завершение и ошибка.<\\/p><p>Дату и время заказа бот получает автоматически, поэтому клиента о них спрашивать не нужно.<\\/p><p>Каждая кнопка и каждый выход блока должны быть соединены стрелкой с нужным экраном.<\\/p><p>После любого изменения сценария нужно нажать «Сохранить» и «Опубликовать».<\\/p>\",\"tests\":[{\"question\":\"Чем блок «text to $var» отличается от блока «Текст»?\",\"answers\":[\"Он не отправляет сообщений клиенту, а только меняет оформление экрана\",\"Он отправляет вопрос, ждёт ответ клиента и сохраняет его в переменную ✓\",\"Он автоматически записывает ответ клиента в Google Таблицу без дополнительной настройки интеграции\",\"Он принимает только числа и отклоняет текстовые ответы клиента\"],\"correct\":null},{\"question\":\"Какое имя переменной можно использовать в Aimylogic?\",\"answers\":[\"Имя клиента\",\"Имя_клиента\",\"client-name\",\"client_name ✓\"],\"correct\":null},{\"question\":\"Как действие «Сохранить в строку» определяет, в какой столбец попадёт значение?\",\"answers\":[\"По названию столбца, указанному перед значением в поле блока\",\"Автоматически, по типу данных: числа в одни столбцы, текст в другие\",\"По порядку полей слева направо ✓\",\"Все значения записываются в первый столбец через запятую\"],\"correct\":null},{\"question\":\"Для чего нужен блок «HTTP-запрос»?\",\"answers\":[\"Чтобы обратиться к внешнему сервису и сохранить его ответ в переменную ✓\",\"Чтобы вставить на экран бота фотографию из интернета\",\"Чтобы изменить название листа в Google Таблице\",\"Чтобы создать нового Telegram-бота через BotFather без перехода в мессенджер\"],\"correct\":null},{\"question\":\"Почему у блока «HTTP-запрос» два выхода?\",\"answers\":[\"Первый ведёт к главному меню, второй к настройкам бота\",\"Один продолжает сценарий при успешном запросе, другой при ошибке ✓\",\"Один для клиентов с Telegram, другой для остальных\",\"Оба нужны для повторной отправки запроса\"],\"correct\":null},{\"question\":\"Что произойдёт, если кнопка на экране не связана стрелкой ни с одним экраном?\",\"answers\":[\"Aimylogic сам выберет подходящий экран для перехода\",\"Кнопка исчезнет из Telegram после публикации сценария\",\"Бот автоматически перейдёт на экран ошибки\",\"Клиент нажмёт кнопку, но сценарий дальше не продолжится ✓\"],\"correct\":null},{\"question\":\"Почему лист для записи нужно создать и назвать заранее?\",\"answers\":[\"Потому что блок записи ищет лист по точному названию ✓\",\"Потому что Google Таблицы запрещают добавлять листы после подключения бота\",\"Потому что название листа копируется из названия проекта Aimylogic\",\"Потому что иначе бот перестанет отвечать клиентам в Telegram\"],\"correct\":null},{\"question\":\"Что нужно сделать после изменения сценария, чтобы изменения заработали у клиентов в Telegram?\",\"answers\":[\"Заново получить API-токен у BotFather\",\"Удалить историю переписки в Google Таблице\",\"Сохранить и опубликовать сценарий, затем пройти маршрут заново ✓\",\"Создать новый проект и заново подключить бота\"],\"correct\":null},{\"question\":\"Почему время заказа лучше получать автоматически, а не спрашивать у клиента?\",\"answers\":[\"Потому что клиенты не умеют писать цифры\",\"Это исключает ошибки ввода и экономит клиенту один вопрос ✓\",\"Потому что Telegram запрещает вопросы про время\",\"Потому что Google Таблицы принимают время только от сервисов\"],\"correct\":null},{\"question\":\"Что происходит со строками в таблице, когда два клиента подряд оформляют заказ?\",\"answers\":[\"Второй заказ заменяет первый в той же строке\",\"Данные обоих заказов объединяются в одну строку\",\"Второй заказ отклоняется, пока первый не обработан оператором\",\"Каждый заказ добавляется отдельной новой строкой ✓\"],\"correct\":null}],\"lab\":\"<p>Цель — самостоятельно расширить созданный сценарий оформления заказа. Определяйте нужные блоки и связи сами.<\\/p><p>&nbsp;<\\/p><p><strong>Задача 1. Комментарий к заказу<\\/strong><\\/p><p>Добавьте в сценарий вопрос о комментарии к заказу, например о коде домофона. Придумайте текст вопроса и имя переменной.&nbsp;<br>Определите, между какими экранами его разместить, чтобы клиент увидел комментарий на экране проверки данных, и добавьте в текст этого экрана новую строку.<\\/p><p>Добавьте на лист «Заказы из бота» новый столбец с заголовком «Комментарий». Самостоятельно определите, каким по счёту полем в блоке записи он должен идти, и настройте блок.<\\/p><p>Проверьте: после тестового заказа комментарий лежит в новом столбце, а остальные четыре значения остались на своих местах.<\\/p><p>&nbsp;<\\/p><p><strong>Задача 2. Персональное сообщение после заказа<\\/strong><\\/p><p>Измените экран «Заказ принят»:&nbsp;<br>бот должен обращаться к клиенту по имени и повторять адрес доставки.&nbsp;<br>Новых вопросов не добавляйте, используйте уже сохранённые переменные.<\\/p><p>Проверьте: после тестового заказа в&nbsp;Telegram видны имя и адрес, которые вы вводили.<\\/p><p>&nbsp;<\\/p><p><strong>Задача 3. Повтор при ошибке<\\/strong><\\/p><p>Добавьте на экран ошибки кнопку «Попробовать снова».&nbsp;<br>Определите, на какой экран её нужно вести, чтобы клиенту не пришлось заново отвечать на все вопросы.<\\/p><p>Проверьте: кнопка ведёт на экран проверки данных, где снова доступна кнопка «Подтвердить заказ».<\\/p><p>&nbsp;<\\/p><p><strong>Задача 4. Диагностика порядка полей<\\/strong><\\/p><p>Временно поменяйте местами значения в первом и втором полях блока записи.&nbsp;<br>Опубликуйте сценарий и оформите один тестовый заказ.&nbsp;<br>Запишите, в какие столбцы попали имя и адрес.<\\/p><p>Верните прежний порядок полей и опубликуйте сценарий.&nbsp;<br>Удалите неверную тестовую строку на листе:&nbsp;<br>правый клик по номеру строки → «Удалить строку».<\\/p><p>Проверьте: новый заказ записывается правильно, а неверной строки на листе нет.<\\/p><p>&nbsp;<\\/p><p><strong>Задача 5. Итоговая проверка<\\/strong><\\/p><p>Очистите историю чата и запустите бота командой \\/start.&nbsp;<br>Оформите два заказа с разными данными, а третий начните и отмените на экране проверки данных.<\\/p><p>Проверьте: на листе ровно две новые строки, значения лежат в правильных столбцах, а время в каждой строке соответствует моменту оформления заказа.<\\/p>\"}');
INSERT INTO `lessons` (`id`, `section_id`, `title_ru`, `slug`, `lesson_order`, `content`) VALUES
(10, 5, '3.1. Установка n8n и подключение Google Таблиц', 'n-eight-n-setup', 1, '{\"theory\":\"<p>В первых двух модулях вы работали с готовыми облачными сервисами:&nbsp;<br>вошли в аккаунт и сразу начали собирать результат.&nbsp;<br>Модуль 3 устроен иначе.&nbsp;<br>n8n мы установим на ваш компьютер и запустим сами.&nbsp;<br>Это нужно, чтобы вы понимали, как устроена программа, которая в следующих уроках будет автоматически следить за заказами и отправлять уведомления.<\\/p><p>&nbsp;<\\/p><p>В этом уроке мы подготовим фундамент:&nbsp;<br>установим&nbsp;n8n, запустим его, создадим учётную запись владельца и подключим&nbsp;Google Таблицы, чтобы&nbsp;n8n мог читать вашу учебную копию датасета.&nbsp;<br>Самая тонкая часть урока — настройка доступа в&nbsp;Google Cloud Console.&nbsp;<br>Выполняйте её строго по шагам и сверяйте результат после каждого этапа.<\\/p><p>&nbsp;<\\/p><p><strong>Что такое&nbsp;n8n<\\/strong><\\/p><p>n8n (читается «эн-эйт-эн») — визуальный конструктор автоматизаций.<\\/p><p>Вы рисуете схему из блоков, например:&nbsp;<br>«когда в таблице появилась новая строка, отправь сообщение в&nbsp;Telegram».&nbsp;<\\/p><p>Каждый блок называется узлом (Node), а вся схема — сценарием (Workflow).<\\/p><p>&nbsp;<\\/p><p>У&nbsp;n8n есть два варианта работы.&nbsp;<\\/p><p>Облачная версия работает на серверах компании&nbsp;n8n:&nbsp;<br>вы входите через браузер, а после пробного периода она платная.&nbsp;<br>Локальная версия устанавливается на ваш компьютер и работает прямо на нём.&nbsp;<br>Для учебных целей она бесплатна, поэтому в курсе используем её.<\\/p><p>Главное отличие локальной версии:&nbsp;<\\/p><p>она работает только пока запущена.&nbsp;<br>Она «живёт» в окне командной строки.&nbsp;<br>Если закрыть это окно или выключить компьютер,&nbsp;n8n остановится, и сценарии перестанут выполняться.&nbsp;<\\/p><p>Сами сценарии и настройки при этом сохраняются на диске и снова появятся при следующем запуске.<\\/p><p>&nbsp;<\\/p><p><strong>Что понадобится перед началом<\\/strong><\\/p><p>Нужен компьютер с&nbsp;Windows 10 или 11 и разрешение устанавливать программы.&nbsp;<br>Если на учебном компьютере установка запрещена, сообщите преподавателю.&nbsp;<\\/p><p>Также нужны браузер&nbsp;Google Chrome, интернет и&nbsp;Google-аккаунт, в котором лежит ваша копия датасета «Сервис доставки - Фамилия Имя» из урока 1.1.&nbsp;<br>Все действия в&nbsp;Google Cloud Console выполняйте именно в этом аккаунте.<\\/p><p>&nbsp;<\\/p><p><strong>Установка&nbsp;Node.js<\\/strong><\\/p><p>n8n написан на языке&nbsp;JavaScript и запускается внутри программы-платформы&nbsp;Node.js.&nbsp;<br>Вместе с&nbsp;Node.js автоматически ставится&nbsp;npm — менеджер пакетов.&nbsp;<br>Это что-то вроде магазина программ для командной строки:&nbsp;<br>через него мы установим сам&nbsp;n8n.&nbsp;<br><br>&nbsp;<\\/p><p>Откройте&nbsp;Chrome → в адресной строке введите&nbsp;nodejs.org → нажмите&nbsp;Enter.<\\/p><p>На главной странице сайта&nbsp;nodejs.org нажмите кнопку&nbsp;Get Node.js .<\\/p><p>На странице загрузок, чуть ниже, найдите строку:<br>Or get a prebuilt Node.js® for<br>выберите&nbsp;Windows x64<br>и нажмите кнопку:<br>Windows Installer (.msi)<\\/p><p>Дождитесь загрузки файла вида&nbsp;node-vNN.N.N-x64.msi.<\\/p><p>Откройте скачанный файл:&nbsp;<br>(значок загрузок в правом верхнем углу&nbsp;Chrome → щёлкните по файлу) .<\\/p><p>&nbsp;<\\/p><p>(если вышло предупреждение безопасности - действительно ли вы хотите запустить файл - нажмите Запустить\\/Открыть (run) .<\\/p><p>&nbsp;<\\/p><p>В окне&nbsp;Node.js Setup нажмите&nbsp;Next → отметьте галочку «I acceptthe terms in the LicenseAgreement» →&nbsp;Next → папку установки не меняйте, нажмите&nbsp;Next → в окне&nbsp;Custom Setup ничего не меняйте, нажмите&nbsp;Next.<\\/p><p>Если появится окно «Tools for Native Modules», галочку не ставьте.&nbsp;<br>Нажмите&nbsp;Next →&nbsp;Install.<\\/p><p>(Если&nbsp;Windows спросит разрешение на внесение изменений - нажмите «Да» (Yes) ) . Когда установка завершится, нажмите&nbsp;Finish.<\\/p><p>&nbsp;<\\/p><p>Проверка&nbsp;Node.js<\\/p><p>Нажмите на клавиатуре&nbsp;Win+R → в окне «Выполнить» введите&nbsp;cmd → нажмите&nbsp;Enter.&nbsp;<br>Откроется чёрное окно «Командная строка».&nbsp;<br>Мы используем именно её, а не&nbsp;PowerShell.<br>PowerShell на некоторых компьютерах блокирует запуск&nbsp;npm.<\\/p><p>Введите команду:<\\/p><p><code>node -v<\\/code><\\/p><p>нажмите&nbsp;Enter<\\/p><p>Ожидаемый результат: строка вида&nbsp;v25.x.x (номер версии у вас может отличаться).<\\/p><p>Затем введите:<\\/p><p><code>npm -v<\\/code><\\/p><p>Ожидаемый результат: номер версии&nbsp;npm, например 12.x.x.<\\/p><p>Обе команды показали номера версий.&nbsp;<br>Если вместо этого появилось сообщение «”node” не является внутренней или внешней командой» - перезагрузите компьютер.<br>Если не помогло - обратитесь к ИИ.<\\/p><p>&nbsp;<\\/p><p><strong>Установка&nbsp;n8n<\\/strong><\\/p><p>В том же окне введите команду и нажмите&nbsp;Enter:<\\/p><p><code>npm install -g n8n<\\/code><\\/p><p>и&nbsp;нажмите&nbsp;Enter.<\\/p><p>&nbsp;<\\/p><p>Установка может быть довольно длительной и без визуального отражения прогресса.<\\/p><p>&nbsp;<\\/p><p>Разберём команду.&nbsp;<br>npm — программа-установщик,&nbsp;install — «установить», -g — «глобально», то есть для всего компьютера (так&nbsp;n8n можно запускать из любой папки),&nbsp;n8n — что именно устанавливаем.<\\/p><p>&nbsp;<\\/p><p>Установка занимает от 2 до 10 минут.&nbsp;<br>В процессе будут появляться строки&nbsp;npmwarn deprecated.&nbsp;<br>Это обычные предупреждения, а не ошибки, на них не обращайте внимания.&nbsp;<br>Ничего не закрывайте и не нажимайте.<\\/p><p>&nbsp;<\\/p><p>Установка закончена, когда появилась строка вида «added 1000+&nbsp;packages in 5m» и снова появилось приглашение&nbsp;C:\\\\Users\\\\ВашеИмя&gt; (или подобное).<\\/p><p>&nbsp;<\\/p><p>Если вместо этого появилось сообщение о том, что&nbsp;n8n требует другую версию&nbsp;Node.js, установите именно ту версию, которую указывает сообщение, и повторите команду.<\\/p><p>&nbsp;<\\/p><p>Проверьте:&nbsp;<br>введите&nbsp;<code>n8n --version<\\/code> и нажмите&nbsp;Enter.&nbsp;<br>Должен появиться номер версии&nbsp;n8n.<\\/p><p>&nbsp;<\\/p><p>Результат:&nbsp;n8n установлен на компьютер.<\\/p><p>&nbsp;<\\/p><p><strong>Первый запуск&nbsp;n8n<\\/strong><\\/p><p>В окне командной строки введите:<\\/p><p><code>n8n<\\/code><\\/p><p>Нажмите&nbsp;Enter.&nbsp;<\\/p><p>&nbsp;<\\/p><p>Если появится окно предупреждения безопасности Windows нажмите Разрешить (Allow).<\\/p><p>&nbsp;<\\/p><p>Первый запуск может занять до минуты.&nbsp;<\\/p><p>Ждите, пока в окне не появится строка:&nbsp;<br>«Editor is now accessible via:&nbsp;http:\\/\\/localhost:5678».<\\/p><p>&nbsp;<\\/p><p>Удерживая&nbsp;Ctrl нажмите на этот адрес локального сервера&nbsp;n8n.<\\/p><p>или<br>Откройте&nbsp;Chrome → новая вкладка → введите&nbsp;http:\\/\\/localhost:5678 →&nbsp;Enter.&nbsp;<\\/p><p>&nbsp;<\\/p><p>Если появится окно «Брандмауэр Защитника&nbsp;Windows», нажмите «Отмена» (Cancel).&nbsp;<br>Для работы на одном компьютере доступ из сети не нужен.<\\/p><p><br>Адрес состоит из двух частей:&nbsp;<br>localhost означает «этот компьютер»,&nbsp;<br>а 5678 — номер порта, то есть номер «двери», через которую&nbsp;n8n принимает подключения.<\\/p><p>&nbsp;<\\/p><p>Важно: окно командной строки с&nbsp;n8n закрывать нельзя.&nbsp;<br>Пока оно открыто,&nbsp;n8n работает.<\\/p><p>&nbsp;<\\/p><p>Проверьте: в браузере открылась страница создания учётной записи владельца (Setup owner account).<\\/p><p>&nbsp;<\\/p><p>Если в окне командной строки появилось сообщение «Port 5678&nbsp;is already in use», значит&nbsp;n8n уже запущен в другом окне.&nbsp;<br>Найдите и используйте его или закройте лишнее окно.&nbsp;<br>Если страница не открывается, проверьте, что окно с&nbsp;n8n не закрыто и в нём есть строка «Editor is now accessible».<\\/p><p>&nbsp;<\\/p><p><strong>Создание&nbsp;owner-пользователя<\\/strong><\\/p><p>Owner (владелец) — главная учётная запись вашего локального&nbsp;n8n.&nbsp;<br>Это не аккаунт&nbsp;Google и не облачный аккаунт&nbsp;n8n.&nbsp;<br>Она существует только на вашем компьютере и нужна, чтобы входить в вашу копию&nbsp;n8n.<\\/p><p>&nbsp;<\\/p><p>Заполните форму:<\\/p><p>Email — ваш адрес электронной почты, например ваш&nbsp;Gmail.<\\/p><p>First Name и&nbsp;Last Name — имя и фамилия латинскими буквами.<\\/p><p>Password — пароль не короче 8 символов, минимум с одной цифрой и одной заглавной буквой, например&nbsp;Delivery2026.&nbsp;<br>Придумайте свой пароль и запомните его:&nbsp;<\\/p><p>восстановить доступ к локальному&nbsp;n8n сложнее, чем к обычному сайту.<\\/p><p>Нажмите&nbsp;Next («Далее»).<\\/p><p>Если появятся стартовые вопросы о вас - пропустите.<br>Нажмите&nbsp;Get started (начать).<\\/p><p>&nbsp;<\\/p><p>Если после этого появится предложение получить лицензионный ключ, пропустите их кнопкой&nbsp;Skip («Пропустить») или закройте окно крестиком.&nbsp;<br>Всё это для нашей работы не нужно.<\\/p><p>Если после этого появится предложение подключить искусственный интеллект:<\\/p><p>Ускорьте разработку и отладку с помощью&nbsp;n8n Assistant (Build and debugfaster with the n8n Assistant) - нажмите кнопку Настройте позже в разделе «Настройки» (Set up later in Settings).<\\/p><p>&nbsp;<\\/p><p>На вопросе: Давайте создадим вашу первую автоматизацию&nbsp;(Let\'s build your first automation) -выберите: Build a workflow.<\\/p><p>Появится рабочее поле с кнопкой +&nbsp;Add firststep…<\\/p><p>&nbsp;<\\/p><p>Результат: учётная запись владельца создана.<\\/p><p>&nbsp;<\\/p><p><strong>Русификация интерфейса через переводчик&nbsp;Chrome<\\/strong><\\/p><p>У локальной версии&nbsp;n8n нет полноценного русского интерфейса, поэтому воспользуемся встроенным переводчиком&nbsp;Chrome.<\\/p><p>Щёлкните правой кнопкой мыши по пустому месту страницы&nbsp;n8n → выберите «Перевести на русский» (Translate to Russian).&nbsp;<br>Также можно нажать значок перевода справа в адресной строке и выбрать «Русский».<\\/p><p>Проверьте: надписи в меню и на кнопках стали русскими.<\\/p><p>Перевод машинный, поэтому у него есть особенности.&nbsp;<br>Иногда название кнопки переведено неточно.&nbsp;<br>При открытии новых окон часть текста может остаться английской:&nbsp;<br>тогда снова щёлкните правой кнопкой и выберите перевод.&nbsp;<br>Названия узлов в строке поиска вводите по-английски, например&nbsp;Google Sheets.&nbsp;<br>В этом курсе названия кнопок даются по схеме: Русское название (English name), чтобы вы могли найти нужный элемент в любом виде интерфейса.<\\/p><p>Но мой совет как преподавателя - оставьте интерфейс на английском языке.<\\/p><p>&nbsp;<\\/p><p><strong>Остановка и повторный запуск&nbsp;n8n<\\/strong><\\/p><p>Чтобы остановить&nbsp;n8n, перейдите в окно командной строки, где он запущен, и нажмите&nbsp;Ctrl+C.&nbsp;<br>Если&nbsp;Windows&nbsp;спросит «Terminate batch job (Y\\/N)?»,&nbsp;введите&nbsp;Y&nbsp;и&nbsp;нажмите&nbsp;Enter.&nbsp;<br>Закрытие этого окна также останавливает&nbsp;n8n.<\\/p><p>Проверьте: после остановки страница&nbsp;http:\\/\\/localhost:5678 в браузере не открывается.&nbsp;<br>Это нормально: сервер выключен.<\\/p><p>&nbsp;<\\/p><p>Чтобы запустить&nbsp;n8n снова, выполните:&nbsp;Win+R →&nbsp;cmd →&nbsp;Enter → введите:&nbsp;n8n →&nbsp;Enter → дождитесь строки «Editor is now accessible» → в&nbsp;Chrome откройте&nbsp;http:\\/\\/localhost:5678 → введите&nbsp;email и пароль владельца → нажмите «Войти» (Sign in).<\\/p><p>&nbsp;<\\/p><p>Если&nbsp;при&nbsp;повторном&nbsp;запуске&nbsp;n8n&nbsp;снова&nbsp;предложит&nbsp;Build and debug faster with the n8n Assistant - нажмите Turn off for this instance .<\\/p><p>Снова&nbsp;выберите: Build a workflow .<\\/p><p>Откроется холст — рабочее поле сценария.<\\/p><p>&nbsp;<\\/p><p>Ваши сценарии и подключения хранятся в папке&nbsp;C:\\\\Users\\\\ВашеИмя.n8n и никуда не пропадают между запусками.&nbsp;<br>Но если на учебном компьютере профиль пользователя очищается после занятия, всё придётся настраивать заново.&nbsp;<br>Поэтому лабораторная работа этого урока учит повторять настройку самостоятельно.<\\/p><p>&nbsp;<\\/p><p><strong>Знакомство с рабочей областью&nbsp;n8n<\\/strong><\\/p><p>Сейчас у вас открыт холст — рабочее поле сценария (Workflow).&nbsp;<br>Сценарий — это схема из узлов (Nodes), соединённых линиями.&nbsp;<br>Слева вертикально находится боковое меню.&nbsp;<br>Если значок непонятен, наведите курсор - появится подсказка.<\\/p><p>Вверху&nbsp;холста&nbsp;написано&nbsp;Personal \\/ My workflow.&nbsp;<br>Personal — ваше личное пространство, где хранятся сценарии и учётные данные.&nbsp;<br>My workflow — название сценария по умолчанию.&nbsp;<br>Если хотите - можете переименовать.&nbsp;<br>По центру сверху находятся вкладки&nbsp;Editor («Редактор»),&nbsp;Executions («Запуски», журнал прошлых запусков) и&nbsp;Evaluations (в курсе не используется).&nbsp;<br>Справа сверху — кнопка&nbsp;Publish («Опубликовать»).<\\/p><p>&nbsp;<\\/p><p>В&nbsp;n8n есть две особенности.&nbsp;<br>Во-первых, кнопки&nbsp;Save нет:&nbsp;n8n сам сохраняет изменения как черновик через 1–5 секунд.&nbsp;<\\/p><p>Во-вторых,&nbsp;Publish нужна, чтобы сценарий работал автоматически;&nbsp;<br>пока он не опубликован, его можно запускать только вручную.&nbsp;<\\/p><p>Publish пригодится с урока 3.2, сейчас её не нажимайте.<\\/p><p>&nbsp;<\\/p><p>В центре холста — рамка&nbsp;Add firststep... («Добавить первый шаг») - с неё начинается добавление узлов.&nbsp;<br>Справа вертикальная панель: плюс открывает список узлов, значок листа добавляет Sticky note (заметку).&nbsp;<br>Слева внизу — кнопки масштаба:&nbsp;fitview (уместить всё), zoom in,&nbsp;zoom out и&nbsp;tidyup (выровнять узлы).&nbsp;<br>Внизу панель&nbsp;Logs («Журнал»): после запуска в ней видно, как отработал каждый узел.<\\/p><p>&nbsp;<\\/p><p><strong>Как&nbsp;Google Таблицы подключаются к&nbsp;n8n<\\/strong><\\/p><p>Передавать&nbsp;n8n пароль от&nbsp;Google-аккаунта нельзя.&nbsp;<br>Используется механизм&nbsp;OAuth2:&nbsp;<br>вы сами входите на странице&nbsp;Google и нажимаете «Разрешить», а&nbsp;Google выдаёт&nbsp;n8n ключ доступа, не раскрывая пароль.<\\/p><p>В облачной версии&nbsp;n8n есть готовый вход «Sign in with Google».&nbsp;<br>В локальной версии его нет, поэтому мы создаём собственное «приложение» в&nbsp;Google Cloud Console:&nbsp;<br>проект, два&nbsp;API, экран согласия и&nbsp;OAuth-клиент.&nbsp;<br>Клиент даёт две строки:&nbsp;ClientID (как логин приложения) и&nbsp;Client Secret (как пароль приложения).<\\/p><p>Цепочка:&nbsp;Google Cloud Console →&nbsp;Client ID и&nbsp;ClientSecret →&nbsp;credential в&nbsp;n8n → вход через&nbsp;Google →&nbsp;n8n читает таблицу.&nbsp;<br>Работайте в том&nbsp;Google-аккаунте, где лежит ваша копия датасета.&nbsp;<br>Если&nbsp;Google предложит платный пробный период или банковскую карту, закройте предложение.<\\/p><p>&nbsp;<\\/p><p><strong>Создание проекта в&nbsp;Google&nbsp;Cloud&nbsp;Console<\\/strong><\\/p><p>Откройте&nbsp;Chrome →&nbsp;console.cloud.google.com →&nbsp;Enter.&nbsp;<br>Выберите нужный аккаунт. Введите пароль.<br>При первом входе отметьте согласие с условиями и нажмите&nbsp;Agree and continue.<\\/p><p>В верхней панели нажмите кнопку выбора проекта (My First Project или&nbsp;Select a project) →&nbsp;New project («Новый проект») → в поле&nbsp;Project name введите&nbsp;n8n-delivery →&nbsp;Create («Создать»). Через 10–30 секунд нажмите колокольчик справа вверху →&nbsp;Select project.<\\/p><p>Проверьте: в верхней панели написано&nbsp;n8n-delivery.&nbsp;<br>Если нет, выберите проект через ту же кнопку.<\\/p><p>&nbsp;<\\/p><p><strong>Включение двух&nbsp;API<\\/strong><\\/p><p>API — «дверь», через которую программа обращается к сервису&nbsp;Google.&nbsp;<br>Нужны две:&nbsp;Google Sheets API (чтение таблиц) и&nbsp;Google Drive API (поиск ваших таблиц в списке).<\\/p><p>Меню (три полоски слева вверху) →&nbsp;APIs &amp;&nbsp;Services («API и сервисы») →&nbsp;Library («Библиотека») → поиск&nbsp;Google Sheets API → карточка →&nbsp;Enable («Включить»).&nbsp;<br>Затем снова&nbsp;Library → поиск&nbsp;Google Drive API →&nbsp;Enable.<\\/p><p>Проверьте:&nbsp;APIs &amp;&nbsp;Services →&nbsp;Enabled APIs &amp;&nbsp;services — в списке оба&nbsp;API.&nbsp;<br>Если позже&nbsp;n8n сообщит, что&nbsp;API не включён, подождите 2–5 минут.<\\/p><p>&nbsp;<\\/p><p><strong>Настройка экрана согласия<\\/strong><\\/p><p>Это окно, где&nbsp;Google спросит:&nbsp;<br>«Разрешить приложению доступ к таблицам?»&nbsp;<br>Оно настраивается один раз.<\\/p><p>APIs &amp;&nbsp;Services →&nbsp;OAuth consent screen («Экран согласия&nbsp;OAuth») откроет&nbsp;Google Auth Platform.&nbsp;<br>Get started и пройдите шаги.&nbsp;<br>App Information: App name — n8n delivery, User support email — ваш адрес → Next.&nbsp;<br>Audience: External («Внешний») → Next.&nbsp;<br>Contact Information:&nbsp;<br>ваш email → Next.&nbsp;<br>Finish: согласие с User Data Policy → Continue → Create.<\\/p><p>&nbsp;<\\/p><p>Теперь добавьте себя в тестовые пользователи: слева Audience → блок Test users → Add users → ваш Gmail → Save.<\\/p><p>Проверьте: ваш адрес виден в списке, статус —&nbsp;Testing («Тестирование»).&nbsp;<br>В режиме&nbsp;Testing Google отзывает доступ примерно через 7 дней:&nbsp;<br>тогда в&nbsp;credential снова нажмите&nbsp;Sign in withGoogle.<\\/p><p>&nbsp;<\\/p><p><strong>Создание&nbsp;OAuth-клиента<\\/strong><\\/p><p>APIs &amp; Services → Credentials («Учётные&nbsp;данные») → + Create credentials → OAuth client ID (в&nbsp;новом&nbsp;интерфейсе&nbsp;возможен&nbsp;путь: Clients → Create client).&nbsp;<br>Application type — Web application, Name — n8n local .<\\/p><p>В&nbsp;блоке&nbsp;Authorized redirect URIs&nbsp;нажмите&nbsp;Add URI&nbsp;и&nbsp;введите&nbsp;ровно&nbsp;такой&nbsp;адрес,&nbsp;без&nbsp;пробелов&nbsp;и&nbsp;без&nbsp;слэша&nbsp;в&nbsp;конце:<\\/p><p>http:\\/\\/localhost:5678\\/rest\\/oauth2-credential\\/callback<\\/p><p>На него&nbsp;Google вернёт вас в&nbsp;n8n после входа.&nbsp;<br>Нажмите&nbsp;Create.<\\/p><p>В окне&nbsp;OAuth client created скопируйте&nbsp;Client ID (оканчивается на .apps.googleusercontent.com) и&nbsp;Client Secret (обычно начинается с&nbsp;GOCSPX-) в надёжное место: заметку на телефоне или личный&nbsp;Google Диск.&nbsp;<br>Секрет может не показываться повторно.&nbsp;<br>Не отправляйте его в общие чаты и не оставляйте на учебном компьютере.<\\/p><p>Нажмите&nbsp;OK .<\\/p><p>&nbsp;<\\/p><p>Проверьте: клиент&nbsp;n8n local виден в списке.<\\/p><p>&nbsp;<\\/p><p><strong>Узел Google Sheets и credential в n8n<\\/strong><\\/p><p>Вернитесь в&nbsp;n8n (http:\\/\\/localhost:5678).&nbsp;<br>Если нужен новый сценарий, нажмите&nbsp;Create →&nbsp;Workflow.<\\/p><p>Нажмите&nbsp;Add first step... →&nbsp;поиск&nbsp;Manual → Manual Trigger.&nbsp;<br>Если открылось окно узла, закройте его.&nbsp;<br>Нажмите плюс на правой стороне узла → поиск&nbsp;Google Sheets →&nbsp;Google Sheets → действие&nbsp;Get row(s)&nbsp;in sheet.&nbsp;<br>Откроется окно узла: слева&nbsp;Input, в центре настройки, справа&nbsp;Output.<\\/p><p>В поле Credential&nbsp;откройте&nbsp;Connect to Google Sheets.&nbsp;<br>В окне Google Sheets account сравните OAuth Redirect URL с адресом из Google Cloud - они должны совпасть.&nbsp;<br>Вставьте Client ID и Client Secret без пробелов по краям и нажмите Sign in with Google.&nbsp;<br>Если браузер заблокировал окно&nbsp;Google, нажмите значок блокировки справа в адресной строке и разрешите всплывающие окна.&nbsp;<br>Выберите свой аккаунт.<\\/p><p>Предупреждение&nbsp;Google hasn’t verified this app — это нормально:&nbsp;<br>приложение ваше и в режиме тестирования.&nbsp;<br>Нажмите Continue (в старом окне: Advanced → Go to n8n delivery (unsafe)).&nbsp;<br>В запросе доступа отметьте все галочки (Select all) →&nbsp;Continue, иначе позже возникнет ошибка прав.<\\/p><p>Окно&nbsp;Google закроется, в&nbsp;n8n появится&nbsp;Google Sheets account.&nbsp;<br><br>&nbsp;<\\/p><p>Если&nbsp;Google показал&nbsp;redirect_uri_mismatch, адрес в клиенте не совпал с адресом&nbsp;n8n - исправьте.&nbsp;<br>Ошибка&nbsp;access_denied (403) — ваш адрес не добавлен в&nbsp;Test users.&nbsp;<br>Ошибка&nbsp;invalid_client —&nbsp;Client ID или&nbsp;Secret скопированы неточно - скопируйте заново.<\\/p><p>&nbsp;<\\/p><p><strong>Проверка доступа к учебной копии датасета<\\/strong><\\/p><p>Оставьте Resource: Sheet Within Document и Operation: Get Row(s).&nbsp;<br>В поле&nbsp;Document выберите&nbsp;From list → вашу копию «Сервис доставки - Фамилия Имя».&nbsp;<br>Если список пуст, проверьте&nbsp;Google Drive API или переключите режим на&nbsp;ByURL и вставьте адрес таблицы.&nbsp;<br>В поле&nbsp;Sheet выберите&nbsp;From list → Меню и Товары.&nbsp;<br>Вверху нажмите&nbsp;Execute step.<\\/p><p>&nbsp;<\\/p><p>В разделе&nbsp;Output выберите вид&nbsp;Table.&nbsp;<br>Каждая строка листа — отдельный элемент (item).&nbsp;<br>Первую строку&nbsp;n8n считает заголовками, поэтому первым элементом становится&nbsp;PROD-001.<\\/p><p>Проверьте: вверху написано 30&nbsp;items;&nbsp;<br>в первой строке&nbsp;ID_Товара —&nbsp;PROD-001, Наименование — Пицца Пепперони (30 см), Категория — Пицца, Цена_Продажи_Тг — 3200.&nbsp;<br>Узел только читает данные, таблица не изменилась.<\\/p><p>Закройте окно узла.&nbsp;<br><br>Нажмите&nbsp;Execute внизу холста: оба узла получат зелёные галочки.&nbsp;<br>Дополнительно можете проверит - в левом вертикальном меню:&nbsp;<br>домик (overview) → вкладка&nbsp;Credentials:&nbsp;<br>там должен быть&nbsp;Google Sheets account.<\\/p><p>&nbsp;<\\/p><p>Результат:&nbsp;n8n читает вашу копию датасета.<\\/p>\",\"tests\":[{\"question\":\"Для чего в этом уроке нужен Node.js?\",\"answers\":[\"Это расширение браузера для перевода интерфейса n8n\",\"Это среда выполнения, в которой запускается n8n ✓\",\"Это облачный сервис для хранения таблиц для n8n\",\"Это программа для создания токенов Telegram-ботов\"],\"correct\":null},{\"question\":\"Какая команда устанавливает n8n так, чтобы его можно было запускать из любой папки?\",\"answers\":[\"node install n8n\",\"npm start n8n\",\"npm install -a n8n\",\"npm install -g n8n ✓\"],\"correct\":null},{\"question\":\"Что произойдёт с локальным n8n, если закрыть окно командной строки, в котором он запущен?\",\"answers\":[\"Сценарии продолжат выполняться на серверах Google\",\"n8n продолжит работать, потому что был установлен глобально\",\"n8n остановится, и адрес localhost:5678 перестанет открываться ✓\",\"n8n перейдёт в спящий режим и включится при следующем открытии браузера\"],\"correct\":null},{\"question\":\"Что означает адрес http:\\/\\/localhost:5678?\",\"answers\":[\"Компьютер, на котором запущен n8n, и номер порта, через который он принимает подключения ✓\",\"Адрес облачного сервера n8n и номер вашей учётной записи на нём\",\"Адрес Google Таблицы с номером листа\",\"Электронная почта владельца n8n с паролем\"],\"correct\":null},{\"question\":\"Что такое owner-пользователь, создаваемый при первом запуске n8n?\",\"answers\":[\"Облачный аккаунт n8n, который хранит ваши сценарии на сервере компании\",\"Проект в Google Cloud Console с ключами доступа\",\"Локальная учётная запись владельца с email и паролем ✓\",\"Telegram-бот, получающий уведомления о запуске\"],\"correct\":null},{\"question\":\"Зачем при подключении Google Таблиц используется механизм OAuth2?\",\"answers\":[\"Чтобы передать n8n пароль от аккаунта Google для хранения в настройках\",\"Чтобы разрешить n8n доступ к таблицам, не передавая ему пароль от аккаунта Google ✓\",\"Чтобы сохранить Google-таблицу в формате, который понимает n8n\",\"Чтобы автоматически создавать новые таблицы на Google Диске\"],\"correct\":null},{\"question\":\"Какие два API нужно включить в проекте Google Cloud, чтобы узел Google Sheets мог найти и прочитать таблицу?\",\"answers\":[\"Google Sheets API и Google Drive API ✓\",\"Gmail API и Google Sheets API\",\"Google Cloud API и Google Sheets API\",\"Google Sheets API и Cloud Storage API\"],\"correct\":null}],\"lab\":\"<p>Цель работы — самостоятельно восстановить подключение&nbsp;n8n к&nbsp;Google Таблицам после сознательного удаления.&nbsp;<br>Пошаговой инструкции нет: ориентируйтесь на теорию.&nbsp;<br>Все задачи выполняйте в сценарии «Проверка&nbsp;Google Таблиц».<\\/p><p>&nbsp;<\\/p><p><strong>Задача 1. Удаление подключения<\\/strong><\\/p><p>Удалите&nbsp;credential Google Sheets -&nbsp;delivery:&nbsp;<br>Overview → вкладка&nbsp;Credentials → откройте&nbsp;credential и найдите команду Delete.&nbsp;<br>Затем откройте сценарий, откройте узел&nbsp;GoogleSheets и нажмите&nbsp;Execute step.&nbsp;<br>Запишите, как&nbsp;n8n сообщает об отсутствии подключения.<\\/p><p>Проверьте:&nbsp;credential нет в списке, узел не может прочитать данные.<\\/p><p>&nbsp;<\\/p><p><strong>Задача 2. Новый&nbsp;OAuth-клиент<\\/strong><\\/p><p>В&nbsp;GoogleCloud Console удалите клиент&nbsp;n8n local и создайте новый с другим названием. Самостоятельно определите тип приложения и адрес перенаправления.&nbsp;<br>Решите, нужно ли заново создавать проект, включать&nbsp;API и настраивать экран согласия, и сформируйте вывод с обоснованием.<\\/p><p>Проверьте: в списке есть новый клиент, а его&nbsp;Client ID и&nbsp;ClientSecret отличаются от прежних.<\\/p><p>&nbsp;<\\/p><p><strong>Задача 3. Новое подключение<\\/strong><\\/p><p>Создайте в узле новый&nbsp;credential Google Sheets с другим названием и подключите его.<\\/p><p>Проверьте: в окне&nbsp;credential видно&nbsp;Account connected, а узел больше не показывает ошибку.<\\/p><p>&nbsp;<\\/p><p><strong>Задача 4. Чтение другого листа<\\/strong><\\/p><p>Переключите узел на лист «Заказы» и выполните его.&nbsp;<br>Определите, сколько элементов вернул&nbsp;n8n, и сверьте результат с таблицей.&nbsp;<br>Найдите первый заказ и сверьте&nbsp;ID_Клиента,&nbsp;ID_Товара, Количество и Сумма_Заказа_Тг.<\\/p><p>Проверьте: число элементов равно числу заказов на листе, значения первого заказа совпадают с таблицей.<\\/p><p>&nbsp;<\\/p><p><strong>Задача 5. Проверка после перезапуска<\\/strong><\\/p><p>Остановите&nbsp;n8n сочетанием&nbsp;Ctrl+C в окне командной строки.&nbsp;<br>Убедитесь, что адрес&nbsp;http:\\/\\/localhost:5678 не открывается.&nbsp;<br>Запустите&nbsp;n8n заново, войдите под владельцем и выполните узел чтения.<\\/p><p>Проверьте: сценарий и&nbsp;credential на месте, а данные читаются без повторной авторизации.<\\/p>\"}'),
(11, 6, '4.1. Создание экрана просмотра заказов', 'order-viewing-screen', 1, '{\"theory\":\"\",\"tests\":[],\"lab\":\"\"}'),
(12, 7, '5.1. Генерация бизнес-контента и составление промптов', 'bussines-content-generation', 1, '{\"theory\":\"\",\"tests\":[],\"lab\":\"\"}'),
(13, 8, '6.1. Создание первых диаграмм и показателей', 'first-diagramms', 1, '{\"theory\":\"\",\"tests\":[],\"lab\":\"\"}');
INSERT INTO `lessons` (`id`, `section_id`, `title_ru`, `slug`, `lesson_order`, `content`) VALUES
(14, 5, '3.2. Первый авто-сценарий: отслеживание новых заказов и уведомление в Telegram', 'first-workflow', 2, '{\"theory\":\"<p>В прошлом уроке вы установили&nbsp;n8n, запустили его на своём компьютере и подключили к нему&nbsp;Google Таблицы.&nbsp;<br>Теперь&nbsp;n8n умеет читать вашу таблицу, но сам пока ничего не делает.&nbsp;<br>В этом уроке вы соберёте свой первый автоматический сценарий.&nbsp;<br>Как только в таблице появляется новая строка с заказом, администратор сразу получает сообщение в&nbsp;Telegram.&nbsp;<\\/p><p>Никто не следит за таблицей вручную и никому не нужно ничего пересылать.<\\/p><p>&nbsp;<\\/p><p>В конце урока должна работать такая цепочка:<\\/p><p>В таблицу добавилась новая строка с заказом →&nbsp;n8n заметил это → в&nbsp;Telegram администратору пришло сообщение с именем клиента, адресом, телефоном и временем заказа.<\\/p><p>&nbsp;<\\/p><p>Для практики мы используем лист «Заказы из бота» из вашей копии датасета.&nbsp;<br>Это не исходный лист датасета.&nbsp;<\\/p><p>Вы создали его сами в уроке 2.4, и в него&nbsp;Aimylogic записывает заказы.&nbsp;<\\/p><p>Зайдите в свою копию датасета в&nbsp;Google-таблицах на своём&nbsp;Google-диске и проверьте:<br>Должен быть лист \\\"Заказы из бота\\\" (или как вы его назвали).<br>В первой строке листа должны быть заголовки:&nbsp;<\\/p><p>A1 — Имя_Клиента,&nbsp;B1 — Адрес_Доставки,&nbsp;C1 — Телефон,&nbsp;D1 — Дата_Время_Заказа. Если у вас там есть и другие столбцы, например «Комментарий», это не мешает, они просто будут лишними для нашего сообщения.<\\/p><p>&nbsp;<\\/p><p><strong>Из чего состоит сценарий в&nbsp;n8n<\\/strong><\\/p><p>В&nbsp;n8n автоматизация называется&nbsp;workflow, то есть «рабочий процесс» или сценарий.&nbsp;<br>Это схема на экране, которая собирается из кубиков.&nbsp;<br>Каждый кубик называется узлом (Node).&nbsp;<br>Узлы соединяются линиями, и данные идут по ним слева направо.<\\/p><p>&nbsp;<\\/p><p>Узлы бывают двух основных видов.<\\/p><p>Триггер (Trigger) (Переключатель) запускает весь сценарий.&nbsp;<br>Он сам ничего не делает с данными, а ждёт события.&nbsp;<br>Например, «в таблице появилась новая строка».&nbsp;<br>У сценария всегда есть начальный узел-триггер.<\\/p><p>&nbsp;<\\/p><p>Узел-действие выполняет работу после того, как триггер сработал.&nbsp;<br>Например, «отправить сообщение в&nbsp;Telegram».<\\/p><p>&nbsp;<\\/p><p>Наш сценарий состоит ровно из двух узлов:<\\/p><p>Google Sheets Trigger (следит за новыми строками) →&nbsp;Telegram (отправляет сообщение).<\\/p><p>&nbsp;<\\/p><p>Чтобы узлы могли обращаться к чужим сервисам, им нужен доступ, который называется&nbsp;credential (креденшл), то есть «учётные данные».&nbsp;<\\/p><p>Для&nbsp;Google Таблиц вы уже создали его в уроке 3.1.&nbsp;<br>Для&nbsp;Telegram мы создадим новый на основе токена бота.&nbsp;<br>Credential создаётся один раз и потом выбирается из списка в любом узле.<\\/p><p>&nbsp;<\\/p><p><strong>Зачем отдельный технический бот<\\/strong><\\/p><p>В модуле 2 вы создали клиентского бота, например&nbsp;trump_delivery_bot.&nbsp;<br>Он подключён к&nbsp;Aimylogic и общается с покупателями.&nbsp;<br>Уведомления администратору мы будем отправлять от другого бота, потому что у них разные роли.&nbsp;<br>Клиентский бот говорит с клиентами, а технический бот пишет только вам или администратору.&nbsp;<br>Так проще понять, кто кому что отправил, и токен клиентского бота не нужно переносить в другой сервис.<\\/p><p>Технический бот создаётся точно так же, как в уроке 2.1.<\\/p><p>&nbsp;<\\/p><p><strong>Создание технического бота через&nbsp;BotFather<\\/strong><\\/p><p>Если вы знаете, как открыть&nbsp;Telegram на учебном компьютере - переходите к следующему абзацу.&nbsp;<\\/p><p>Если нет, откройте браузер → в адресной строке введите&nbsp;web.telegram.org → на телефоне откройте Telegram → Настройки (Settings) → Устройства (Devices) → Подключить устройство (LinkDesktop Device) → отсканируйте&nbsp;QR-код на экране компьютера.<\\/p><p>Проверьте: в левой части окна&nbsp;Telegram виден список ваших чатов.<\\/p><p>&nbsp;<\\/p><p>Теперь создадим бота.&nbsp;<br>В поле поиска&nbsp;Telegram введите&nbsp;BotFather → выберите официальный аккаунт с синей галочкой → откройте чат → нажмите&nbsp;START → отправьте команду \\/newbot.<\\/p><p>BotFather спросит отображаемое имя.&nbsp;<br>Введите, например, \\\"Уведомления о заказах\\\" и отправьте.<\\/p><p>Затем&nbsp;BotFather спросит&nbsp;username.&nbsp;<br>Он должен заканчиваться на&nbsp;bot и не совпадать с&nbsp;username клиентского бота.&nbsp;<br>Введите, например, ваша-фамилия_notify_bot, где вместо «ваша-фамилия» подставьте фамилию маленькими английскими буквами.&nbsp;<\\/p><p>Например:&nbsp;trump_notify_bot .<br>Если имя занято,&nbsp;BotFather попросит другое.<\\/p><p>Проверьте:&nbsp;BotFather прислал сообщение со словами о том, что бот создан, а также ссылку вида&nbsp;t.me\\/ваш_бот и&nbsp;API-токен.&nbsp;<br>Токен выглядит как набор цифр, двоеточие и длинная строка букв.<\\/p><p>Скопируйте токен и временно сохраните в безопасном месте, например на телефон или на свой&nbsp;Google Диск.&nbsp;<br>Токен нельзя отправлять в общий чат и оставлять на учебном компьютере.<\\/p><p>&nbsp;<\\/p><p>Результат: создан технический бот.<\\/p><p>&nbsp;<\\/p><p><strong>Первое сообщение боту и получение&nbsp;Chat&nbsp;ID<\\/strong><\\/p><p>Бот может написать человеку только после того, как этот человек сам написал боту. Поэтому нужно открыть технического бота и начать с ним диалог.&nbsp;<br>Нажмите на ссылку&nbsp;t.me\\/ваш_бот в сообщении&nbsp;BotFather → нажмите&nbsp;START → отправьте боту любое слово, например Привет.&nbsp;<br>Ответа не будет, потому что логики у бота нет. Это нормально.<\\/p><p>Чтобы бот знал, кому писать, нужен&nbsp;Chat ID, то есть числовой номер вашего чата. Получим его так.&nbsp;<br><br>&nbsp;<\\/p><p>Откройте в браузере новую вкладку и введите адрес, заменив фрагмент ВАШ_ТОКЕН на ваш токен целиком:<\\/p><p>https:\\/\\/api.telegram.org\\/botВАШ_ТОКЕН\\/getUpdates<\\/p><p>Между словом bot и токеном пробела нет.&nbsp;<br>Получится, например: https:\\/\\/api.telegram.org\\/bot604771091:AAbWz...\\/getUpdates<\\/p><p>Нажмите&nbsp;Enter.&nbsp;<br>На странице появится текст.&nbsp;<\\/p><p><br>(Это нужно сделать сразу после того, как вы написали первое сообщение в боте в&nbsp;Telegram. Если пройдёт какое-то время (несколько часов) -&nbsp;Telegram удалит сообщение из кэша. Тогда на странице отобразится пустое сообщение (result:[] (пустой список)). Тогда нужно будет заново отправить сообщение в&nbsp;Telegram-боте и обновить страницу клавишей&nbsp;F5) .<br><br>Если в вашем браузере, вверху есть строка Автоформатировать - отметьте её галочкой - тогда информация, в&nbsp;JSON-формате, отобразится человекочитаемым образом.<\\/p><p><br>Найдите в тексте фрагмент “chat”:{“id”:&nbsp;<br>и число сразу после него, например 123456789.&nbsp;<br>Это ваш&nbsp;Chat ID.&nbsp;<br>Скопируйте только число, без кавычек и запятых.<\\/p><p>Вкладку с токеном в адресе можете, пока, оставить открытой.&nbsp;<br>Не отправляйте адрес и скриншот этой страницы другим людям, потому что в адресе виден токен.<\\/p><p>&nbsp;<\\/p><p>Результат: у вас есть&nbsp;Chat ID.<\\/p><p>&nbsp;<\\/p><p>Есть и запасной способ узнать&nbsp;Chat ID без токена.&nbsp;<br>В&nbsp;Telegram найдите бота @userinfobot, нажмите&nbsp;START, и он пришлёт ваш&nbsp;Id.<\\/p><p>&nbsp;<\\/p><p><strong>Запуск&nbsp;n8n и создание сценария<\\/strong><\\/p><p>Напомним главное правило локальной версии:&nbsp;<br>n8n работает только пока запущено окно терминала, в котором он стартовал.&nbsp;<br>Если окно закрыто, сценарии не работают.<\\/p><p>Откройте терминал (на&nbsp;Windows это&nbsp;PowerShell или командная строка) → введите команду&nbsp;n8n и нажмите&nbsp;Enter → дождитесь строки с адресом&nbsp;http:\\/\\/localhost:5678 → откройте этот адрес в браузере → войдите под вашим&nbsp;email и паролем, созданными в уроке 3.1.&nbsp;<\\/p><p>&nbsp;<\\/p><p>Если интерфейс на английском, его можно перевести встроенным переводчиком&nbsp;Chrome, как мы делали раньше.&nbsp;<br>(Но лучше оставить на английском) .<br>Ниже названия кнопок даны в двух вариантах.<\\/p><p>&nbsp;<\\/p><p>Вверху слева нажмите кнопку + →&nbsp;New workflow.<\\/p><p>Откроется пустой холст.&nbsp;<br>Вверху слева находится название сценария, по умолчанию&nbsp;My workflow (или&nbsp;My workflow 2).&nbsp;<br>Нажмите на него, введите название Оповещение о новом заказе и нажмите&nbsp;Enter.<\\/p><p>Проверьте: в верхней части окна отображается новое название, а в центре холста есть кнопка&nbsp;Add first step... (Добавить первый шаг) со знаком «+».<\\/p><p>&nbsp;<\\/p><p><strong>Первый узел:&nbsp;Google&nbsp;Sheets&nbsp;Trigger<\\/strong><\\/p><p>Нажмите на кнопку&nbsp;Add firststep...&nbsp;<br>Справа откроется панель выбора узлов.&nbsp;<br>В строке поиска введите&nbsp;GoogleSheets и выберите&nbsp;Google Sheets.&nbsp;<\\/p><p>В списке&nbsp;Triggers выберите&nbsp;On row added (При добавлении строки),<\\/p><p>Заполните поля сверху вниз.<\\/p><p>&nbsp;<\\/p><p>В поле&nbsp;Credential to connect with (Учётные данные для подключения) выберите&nbsp;credential Google Таблиц, созданный в уроке 3.1.&nbsp;<br>Название обычно начинается с&nbsp;GoogleSheets account.&nbsp;<br>Если список пуст, вернитесь к уроку 3.1 и повторите подключение.<br>Должны быть заполнены поля:<br>OAuth Redirect URL ;<br>Client ID ;<br>Client Secret .<br>И должно быть сообщение на зелёном фоне \\\"Account connected\\\" .<\\/p><p>Если всё правильно - закройте окно \\\"Google Sheets Trigger account\\\" .<\\/p><p>В блоке&nbsp;Poll Times (Частота проверки) нажмите&nbsp;AddPoll Time, если там пока ничего нет, и в поле&nbsp;Mode выберите&nbsp;Every Minute (Каждую минуту).&nbsp;<br>Это значит, что&nbsp;n8n будет заглядывать в таблицу раз в минуту.&nbsp;<br>Мгновенного срабатывания нет: уведомление придёт с задержкой до минуты, это нормально.<\\/p><p>&nbsp;<\\/p><p>В поле&nbsp;Document (Документ) выберите вариант&nbsp;From list (Из списка) и затем свою копию датасета с названием «Сервис доставки - Фамилия Имя».&nbsp;<br>Если копии нет в списке, подождите несколько секунд и откройте список снова.<\\/p><p>&nbsp;<\\/p><p>В поле&nbsp;Sheet (Лист) выберите&nbsp;From list и затем «Заказы из бота».<\\/p><p>&nbsp;<\\/p><p>В поле&nbsp;Trigger On (Событие), которое может называться&nbsp;Event, выберите&nbsp;Row Added (Добавлена строка).<\\/p><p>&nbsp;<\\/p><p>Проверьте: в окне нет красных восклицательных знаков у полей, а рядом с названием листа отображается «Заказы из бота».<\\/p><p>Результат: узел&nbsp;Google Sheets Trigger настроен.<\\/p><p>&nbsp;<\\/p><p>Теперь проверим, что узел видит вашу таблицу.&nbsp;<br>В нижней части окна нажмите&nbsp;FetchTest Event (Получить тестовое событие).&nbsp;<br>Справа, в блоке&nbsp;OUTPUT (Результат), нажмите&nbsp;Testthis trigger.<br>Должны появиться данные последней строки листа, например:<\\/p><p>Имя_Клиента: Айгерим<\\/p><p>Адрес_Доставки: ул. Сатпаева, д. 5, кв. 12<\\/p><p>Телефон: 777-777-77-77<\\/p><p>Дата_Время_Заказа: дата и время заказа<\\/p><p>У вас значения могут отличаться: это ваши тестовые заказы из урока 2.4.<\\/p><p>&nbsp;<\\/p><p>Если вместо данных вы видите сообщение, что нет данных, значит, на листе «Заказы из бота» нет ни одной строки под заголовками.&nbsp;<br>Оформите тестовый заказ через клиентского бота или впишите строку вручную в&nbsp;A2:D2 и нажмите&nbsp;Fetch Test Event снова.<\\/p><p>&nbsp;<\\/p><p>Проверьте: в результате видны ваши четыре заголовка и заполненные тестовые данные.&nbsp;<br>Закройте окно узла крестиком в правом верхнем углу.<\\/p><p>&nbsp;<\\/p><p>Результат: на холсте&nbsp;workflow отображается первый узел&nbsp;Google Sheets Trigger.&nbsp;<\\/p><p>&nbsp;<\\/p><p><strong>Второй узел:&nbsp;Telegram<\\/strong><\\/p><p>Справа от узла-триггера есть маленький кружок со знаком «+».&nbsp;<br>Нажмите на него.&nbsp;<br>В поиске введите&nbsp;Telegram.&nbsp;<br>В разделе&nbsp;Actions (Действия) выберите&nbsp;Senda text message (Отправить текстовое сообщение).<\\/p><p>Откроется окно настроек узла&nbsp;Send a text message.&nbsp;<br>Мы видим три области:&nbsp;<br>слева данные, которые пришли из триггера (INPUT), по середине настройки, справа выходные данные (OUTPUT).<\\/p><p>&nbsp;<\\/p><p>Сначала создадим credential.&nbsp;<br>В поле Credential нажмите Connect to Telegram.&nbsp;<br>Откроется окно.&nbsp;<br>В поле&nbsp;Access Token (Токен доступа) вставьте токен технического бота.&nbsp;<br>Поле&nbsp;Base URL оставьте без изменений.&nbsp;<br>Нажмите&nbsp;Save (Сохранить).<\\/p><p>&nbsp;<\\/p><p>Если токен правильный, вверху окна появится зелёная надпись&nbsp;Connection tested successfully (Соединение успешно проверено).&nbsp;<br>Закройте окно&nbsp;credential.<\\/p><p>&nbsp;<\\/p><p>Если подключение не удалось, проверьте три вещи.&nbsp;<br>Токен вставлен целиком. В начале или в конце нет пробела.&nbsp;<br>Это токен именно технического бота, а не клиентского.<\\/p><p>Проверьте: в поле&nbsp;Credential выбран ваш новый&nbsp;credential, а напротив него нет красных ошибок.<\\/p><p>&nbsp;<\\/p><p>Теперь заполните остальные поля.&nbsp;<br>В поле&nbsp;Resource должно быть&nbsp;Message, а в поле&nbsp;Operation —&nbsp;Send Message.&nbsp;<br>Они обычно уже выбраны.<\\/p><p>В поле&nbsp;Chat ID вставьте число, которое вы получили на шаге с&nbsp;getUpdates.<\\/p><p>&nbsp;<\\/p><p>В поле&nbsp;Text (Текст) мы соберём сообщение, в которое&nbsp;n8n сам подставит данные из таблицы.&nbsp;<br>Для этого нужно понять, что такое выражение (Expression).&nbsp;<\\/p><p>Выражение — это кусочек текста, который&nbsp;n8n заменяет на реальное значение из предыдущего узла.&nbsp;<\\/p><p>Оно записывается в двойных фигурных скобках.&nbsp;<\\/p><p>Например, запись {{ $json[\\\"Телефон\\\"] }} означает «возьми значение столбца Телефон из пришедшей строки».<\\/p><p>Самый простой и безошибочный способ для новичка — перетащить поле мышью.&nbsp;<\\/p><p>&nbsp;<\\/p><p>Щёлкните в поле&nbsp;Text.&nbsp;<br>Затем в левом блоке&nbsp;INPUT найдите поле Имя_Клиента, зажмите на нём левую кнопку мыши и перетащите в поле&nbsp;Text.&nbsp;<br>В поле&nbsp;Text автоматически появится выражение, а само поле переключится в режим&nbsp;Expression (на нём появится значок&nbsp;fx).&nbsp;<br>Можно и просто ввести две открывающие скобки «{{» в поле:&nbsp;n8n сам переключит его в этот режим.<\\/p><p>Соберите в поле&nbsp;Text такое сообщение.&nbsp;<br>Для перехода на новую строку нажимайте&nbsp;Enter.&nbsp;<br>Выражения вставляйте перетаскиванием или вводите вручную:<\\/p><p>Новый заказ!<\\/p><p>Имя: {{ $json[\\\"Имя_Клиента\\\"] }}<\\/p><p>Адрес: {{ $json[\\\"Адрес_Доставки\\\"] }}<\\/p><p>Телефон: {{ $json[\\\"Телефон\\\"] }}<\\/p><p>Время: {{ $json[\\\"Дата_Время_Заказа\\\"] }}<\\/p><p>Названия столбцов должны совпадать с заголовками листа буква в букву, включая подчёркивания.<\\/p><p>&nbsp;<\\/p><p>Теперь отключим подпись&nbsp;n8n.&nbsp;<br>Внизу окна нажмите&nbsp;Add Field (Добавить поле), выберите&nbsp;Append n8n Attribution (Добавить подпись&nbsp;n8n) и выключите переключатель.&nbsp;<br>Иначе в конце каждого сообщения будет приписка о том, что оно отправлено через&nbsp;n8n.<\\/p><p>Справа, в поле&nbsp;OUTPUT нажмите кнопку&nbsp;Execute Step.<br>Должен появиться результат.<\\/p><p>Закройте блок настроек крестиком справа вверху.<\\/p><p>&nbsp;<\\/p><p>Проверьте: на холсте слева находится узел&nbsp;Google Sheets Trigger, справа Send a text message (Telegram), а между ними идёт линия.&nbsp;<br>Если линии нет, наведите курсор на правую точку первого узла, зажмите левую кнопку мыши и протяните линию к левой точке второго узла.<\\/p><p>&nbsp;<\\/p><p>Результат: оба узла настроены и соединены линией на холсте.<\\/p><p>&nbsp;<\\/p><p><strong>Тестовый запуск<\\/strong><\\/p><p>Тестовый запуск проверяет, что узлы настроены правильно, но не включает автоматическую работу.<\\/p><p>Нажмите на холсте, внизу по центру, кнопку&nbsp;Execute (Выполнить).&nbsp;<br>n8n возьмёт последнюю строку таблицы, пройдёт по обоим узлам и отправит сообщение. Узлы подсветятся зелёными галочками.<\\/p><p>&nbsp;<\\/p><p>Откройте&nbsp;Telegram и перейдите в чат с техническим ботом.&nbsp;<br>Должно прийти сообщение «Новый заказ!» с данными из всех строк таблицы.<\\/p><p>Проверьте: сообщение пришло, а каждая строка содержит нужное значение, а не пустоту.<\\/p><p>&nbsp;<\\/p><p>Если сообщения нет, а узел&nbsp;Telegram помечен красным, откройте его и прочитайте текст ошибки справа.&nbsp;<br>Самая частая ошибка —&nbsp;chat not found.&nbsp;<br>Она означает, что&nbsp;Chat ID введён неверно или вы не отправили боту ни одного сообщения.&nbsp;<\\/p><p>Проверьте&nbsp;Chat ID и, напишите боту ещё раз.&nbsp;<\\/p><p>Если в ошибке сказано, что не авторизован (Unauthorized), значит, токен введён неверно: пересоздайте&nbsp;credential.<\\/p><p>Не забудьте сохранить сценарий: нажмите&nbsp;Ctrl+S или кнопку&nbsp;Save вверху справа.<\\/p><p>&nbsp;<\\/p><p><strong>Включение сценария: публикация<\\/strong><\\/p><p>Тестовый запуск сработал один раз и только потому, что вы нажали кнопку.&nbsp;<br>Чтобы сценарий следил за таблицей сам, его нужно включить.&nbsp;<br>Справа вверху нажмите кнопку&nbsp;Publish (Опубликовать).&nbsp;<br>Подтвердите публикацию в появившемся окне и дождитесь сообщения о том, что сценарий опубликован.<\\/p><p>Проверьте: Кнопка&nbsp;Publish изменилась на&nbsp;Published.&nbsp;<\\/p><p>&nbsp;<\\/p><p>Результат: сценарий работает в боевом режиме.<\\/p><p>&nbsp;<\\/p><p>Важно запомнить:&nbsp;<br>после публикации&nbsp;n8n отслеживает только новые строки.&nbsp;<br>Старые заказы, которые уже были в таблице, повторно отправляться не будут.&nbsp;<br>Правка уже существующих строк тоже не считается новой строкой.<\\/p><p>&nbsp;<\\/p><p><strong>Проверка работы в боевом режиме<\\/strong><\\/p><p>Откройте свою копию датасета и перейдите на лист «Заказы из бота».&nbsp;<br>Добавьте две новых строки двумя способами по очереди.&nbsp;<\\/p><p>Первый — оформить тестовый заказ через клиентского бота из модуля 2, и&nbsp;Aimylogic сам запишет строку.&nbsp;<\\/p><p>Второй — вручную вписать в первую пустую строку значения в столбцы&nbsp;A,&nbsp;B,&nbsp;C и&nbsp;D, например: Болат \\/ ул. Жёлтоксан, д. 3 \\/ 705-705-75-75 \\/ 14.10.2026 12:30.<\\/p><p>Подождите до одной минуты.&nbsp;<br>В&nbsp;Telegram в чат с техническим ботом должно прийти новое сообщение «Новый заказ!» с данными именно этой новой строки.<\\/p><p>Проверьте: сообщение пришло и содержит данные новой строки, а не старой.<\\/p><p>&nbsp;<\\/p><p>Теперь посмотрим журнал.&nbsp;<\\/p><p>Вернитесь в&nbsp;n8n.<br>В верхней части окна сценария откройте вкладку&nbsp;Executions (Выполнения).&nbsp;<br>Там виден список запусков.&nbsp;<br>У запуска, который произошёл автоматически, статус&nbsp;Succeeded (Успешно).<br>&nbsp;Если там красный статус&nbsp;Error, откройте запуск и посмотрите, какой узел сломался и что написано в ошибке.<\\/p><p>&nbsp;<\\/p><p>Если сообщение не приходит, проверьте по порядку.&nbsp;<br>Запущено ли окно терминала с&nbsp;n8n.&nbsp;<br>Опубликован ли сценарий.&nbsp;<br>Добавлена ли строка именно на лист «Заказы из бота», а не на другой лист.&nbsp;<br>Прошла ли минута.&nbsp;<br>Меняйте настройки по одной за раз и сразу проверяйте результат.<\\/p><p>&nbsp;<\\/p><p><strong>Что нужно запомнить<\\/strong><\\/p><p>Сценарий в&nbsp;n8n состоит из узлов, которые соединены линиями.&nbsp;<br>Первый узел — триггер, который запускает сценарий при событии.&nbsp;<br>Следующие узлы выполняют действия.<\\/p><p>Credential хранит доступ к сервису, его создают один раз и выбирают из списка.<\\/p><p>Технический бот для уведомлений создаётся через&nbsp;BotFather отдельно от клиентского бота.&nbsp;<br>Для отправки сообщений нужны его токен и&nbsp;Chat ID получателя, а получатель должен сам написать боту первым.<\\/p><p>Выражение в двойных фигурных скобках подставляет в текст данные из предыдущего узла, например значение столбца из новой строки.<\\/p><p>Тестовый запуск проверяет настройки один раз, а автоматическая работа начинается только после публикации сценария.&nbsp;<br>Локальный&nbsp;n8n работает, пока запущен терминал.<\\/p>\",\"tests\":[{\"question\":\"Что такое триггер в сценарии n8n?\",\"answers\":[\"Узел, который удаляет старые строки из таблицы\",\"Узел, который запускает сценарий при наступлении события ✓\",\"Кнопка, при нажатии на которую сценарий копируется в свой аккаунт\",\"Любой узел, расположенный на холсте правее остальных\"],\"correct\":null},{\"question\":\"Что такое credential в n8n?\",\"answers\":[\"Название сценария, которое отображается вверху холста\",\"Готовый шаблон текста для сообщения в Telegram\",\"Список строк таблицы, которые уже прочитал триггер\",\"Сохранённые данные доступа, которые узел использует для подключения к сервису ✓\"],\"correct\":null},{\"question\":\"Где новичок получает API-токен для нового Telegram-бота?\",\"answers\":[\"В чате с официальным ботом BotFather после команды \\/newbot ✓\",\"В настройках приложения Telegram в разделе «Доступ»\",\"На странице входа в локальный n8n по адресу localhost:5678\",\"В профиле Telegram в разделе «Устройства»\"],\"correct\":null},{\"question\":\"Для чего в сообщении Telegram-узла используют выражение вида {{ $json[\\\"Телефон\\\"] }}?\",\"answers\":[\"Чтобы подставить в сообщение значение столбца Телефон из пришедшей строки ✓\",\"Чтобы изменить название столбца Телефон в Google Таблице\",\"Чтобы добавить в Google-таблицу новый столбец с заголовком Телефон\",\"Чтобы запретить боту отправлять сообщения без номера телефона\"],\"correct\":null},{\"question\":\"Что произойдёт со сценарием, если закрыть окно терминала, в котором запущен локальный n8n?\",\"answers\":[\"Сценарий продолжит работать как обычно, потому что он хранится в облаке Google\",\"Сценарий автоматически переедет на сервер Telegram\",\"Сценарий перестанет выполняться, пока n8n не будет запущен снова ✓\",\"Сценарий выполнится сразу для всех строк таблицы\"],\"correct\":null},{\"question\":\"На какое событие реагирует Google Sheets Trigger с настройкой Row Added?\",\"answers\":[\"На появление новой строки в листе ✓\",\"На изменение значения в любой существующей ячейке\",\"На изменение цвета заливки ячеек\",\"На удаление строки из Google-таблицы\"],\"correct\":null},{\"question\":\"Где в n8n посмотреть историю автоматических запусков сценария и найти ошибку?\",\"answers\":[\"На вкладке «Credentials» в списке учётных данных\",\"На вкладке Executions (Выполнения) ✓\",\"В поле Chat ID внутри узла Telegram\",\"В чате с BotFather по команде \\/history\"],\"correct\":null}],\"lab\":\"<p>Цель — самостоятельно воспроизвести настройку оповещения и убедиться, что вы понимаете, как сценарий ведёт себя в разных ситуациях.&nbsp;<br>Пошаговых подсказок здесь нет: определяйте нужные узлы и настройки сами.<\\/p><p>&nbsp;<\\/p><p><strong>Задача&nbsp;1. Найдите причину ошибки<\\/strong><\\/p><p>Намеренно испортите настройку:&nbsp;<br>в узле&nbsp;Telegram замените в&nbsp;Chat ID одну цифру на любую другую.&nbsp;<br>Выполните тестовый запуск.<\\/p><p>Найдите в окне узла текст ошибки и запишите его.&nbsp;<br>Определите, к какому месту настройки он относится.&nbsp;<br>Затем верните правильный&nbsp;ChatID и повторите запуск.<\\/p><p>Проверьте: в ваших записях есть точный текст ошибки, а после исправления сообщение снова приходит.<\\/p><p>&nbsp;<\\/p><p><strong>Задача 2. Поведение триггера при нескольких новых строках<\\/strong><\\/p><p>Снимите публикацию с сценария.&nbsp;<br>Добавьте на лист «Заказы из бота» две новые строки с разными тестовыми данными, одну под другой.&nbsp;<br>После этого опубликуйте сценарий.<\\/p><p>Дождитесь результата и запишите три наблюдения:&nbsp;<br>сколько сообщений пришло, в каком порядке они пришли, и пришли ли уведомления о строках, которые были на листе раньше.<\\/p><p>Проверьте: ваши записи основаны на том, что вы увидели в&nbsp;Telegram, а не на предположениях.<\\/p><p>&nbsp;<\\/p><p><strong>Задача 3. Что происходит при остановке&nbsp;n8n<\\/strong><\\/p><p>В окне терминала остановите&nbsp;n8n сочетанием клавиш&nbsp;Ctrl+C.&nbsp;<br>Добавьте на лист «Заказы из бота» одну новую строку.&nbsp;<br>Подождите три минуты и проверьте&nbsp;Telegram.<\\/p><p>Затем снова запустите&nbsp;n8n командой&nbsp;n8n, откройте&nbsp;localhost:5678 и подождите ещё две минуты.&nbsp;<br>Запишите, пришло ли сообщение о строке, добавленной во время остановки, и когда именно.<\\/p><p>Проверьте: в ваших записях есть ответ на вопрос, продолжает ли сценарий работать после перезапуска, и вывод о том, почему окно терминала нельзя закрывать в рабочее время.<\\/p><p>&nbsp;<\\/p><p><strong>Задача 4. Разбор журнала запусков<\\/strong><\\/p><p>Откройте вкладку&nbsp;Executions сценария.&nbsp;<br>Найдите запуски за время выполнения предыдущих задач.&nbsp;<br>Для одного успешного запуска откройте подробности и найдите данные, которые пришли в узел&nbsp;Telegram.<\\/p><p>Запишите, какое имя клиента было в этих данных, и сравните время запуска из журнала со значением из столбца Дата_Время_Заказа этой же строки.&nbsp;<br>Определите, на сколько примерно минут уведомление опоздало.<\\/p><p>Проверьте: найденное имя совпадает со строкой на листе, а задержка не превышает нескольких минут.<\\/p>\"}');
INSERT INTO `lessons` (`id`, `section_id`, `title_ru`, `slug`, `lesson_order`, `content`) VALUES
(15, 5, '3.3. Автоматическая проверка условий (блок IF)', 'if-block', 3, '{\"theory\":\"<p>В прошлом уроке вы собрали сценарий из двух узлов:&nbsp;<br>n8n замечал новую строку в&nbsp;Google Таблице и отправлял уведомление в&nbsp;Telegram.<br>Такой сценарий реагирует на любую строку одинаково.&nbsp;<br>В реальной работе нужно по-разному обрабатывать разные заказы:&nbsp;<br>доставленный заказ закрыть и проставить время, отменённый пропустить, крупный пометить как срочный.<\\/p><p>&nbsp;<\\/p><p>Для этого в&nbsp;n8n есть узел&nbsp;IF (Если).&nbsp;<br>Он проверяет условие и направляет данные по одной из двух дорожек.&nbsp;<br>В этом уроке вы научитесь этим пользоваться на реальных данных листа «Заказы» вашей копии датасета.<\\/p><p>&nbsp;<\\/p><p><strong>Что такое узел&nbsp;IF и как он думает<\\/strong><\\/p><p>Узел&nbsp;IF задаёт вопрос, на который можно ответить только «да» или «нет».&nbsp;<br>Например: «Статус заказа равен Доставлено?»<\\/p><p>У узла один вход и два выхода:<\\/p><p>true (истина) — условие выполнено, ответ «да»;<\\/p><p>false (ложь) — условие не выполнено, ответ «нет».<\\/p><p>В узел обычно приходит не одна строка таблицы, а несколько.&nbsp;<\\/p><p>В&nbsp;n8n каждая строка называется элементом (item).<\\/p><p>IF проверяет каждый элемент отдельно.&nbsp;<\\/p><p>Часть элементов уходит в выход&nbsp;true, часть в выход&nbsp;false.<\\/p><p>&nbsp;<\\/p><p>Схема сценария для этого урока:<\\/p><p>Ручной запуск → Чтение строки из&nbsp;Google Таблицы →&nbsp;IF → (true) → Запись времени доставки в таблицу<\\/p><p>Если ветка&nbsp;false никуда не подключена, элементы, не прошедшие проверку, просто завершают работу.&nbsp;<br>Это нормально: «ничего не делать» тоже решение.<\\/p><p>&nbsp;<\\/p><p>Какие поля листа «Заказы» мы будем проверять<\\/p><p>Прежде чем строить условия, посмотрите на реальную структуру листа «Заказы» в своей копии датасета.&nbsp;<br>Столбцы идут так:<\\/p><p>A —&nbsp;ID_Заказа;<\\/p><p>B —&nbsp;ID_Клиента;<\\/p><p>C —&nbsp;ID_Товара;<\\/p><p>D — Количество;<\\/p><p>E — Сумма_Заказа_Тг;<\\/p><p>F — Канал_Поступления;<\\/p><p>G — Статус_Оплаты;<\\/p><p>H — Статус_Заказа;<\\/p><p>I — Курьер;<\\/p><p>J — Дата_Заказа.<\\/p><p>&nbsp;<\\/p><p>В этом уроке нас интересуют три столбца:<\\/p><p>Статус_Заказа (столбец&nbsp;H) принимает два значения:&nbsp;<br>«Доставлено» и «Отменено»;<\\/p><p>Статус_Оплаты (столбец&nbsp;G) принимает значения «Оплачено&nbsp;Kaspi», «Наличными курьеру» и «Отменено»;<\\/p><p>Сумма_Заказа_Тг (столбец&nbsp;E) — число.<\\/p><p>&nbsp;<\\/p><p>Для примеров возьмём два заказа:<\\/p><p>ORD-001 — строка 2, Статус_Заказа - «Доставлено», Статус_Оплаты - «Оплачено Kaspi», Сумма_Заказа_Тг - 6200;<\\/p><p>ORD-005 — строка 6, Статус_Заказа - «Отменено», Статус_Оплаты - «Отменено», Сумма_Заказа_Тг 1900.<\\/p><p>Проверьте это в своей таблице, прежде чем продолжать.<\\/p><p>&nbsp;<\\/p><p><strong>Какие бывают условия:&nbsp;<\\/strong><br><strong>равно, содержит, число<\\/strong><\\/p><p>Узел&nbsp;IF умеет сравнивать данные по-разному.&nbsp;<br>Выбор зависит от типа данных.<\\/p><p>Для текста (String) чаще всего нужны две проверки:<\\/p><p>is equal to (равно) — значение совпадает полностью.&nbsp;<br>«Доставлено» равно «Доставлено», но не равно «Доставлено » с пробелом на конце и не равно «доставлено», если учитывается регистр;<\\/p><p>contains (содержит) — значение включает нужный фрагмент.&nbsp;<br>Например, «Оплачено&nbsp;Kaspi» содержит слово «Kaspi».<\\/p><p>Есть и противоположные проверки:&nbsp;is notequal to (не равно) и&nbsp;does not contain (не содержит).<\\/p><p><br>Для чисел (Number) используются сравнения:&nbsp;<br>is equal to (равно), is greater than (больше), is greater than or equal to (больше или равно), is less than (меньше), is less than or equal to (меньше или равно).&nbsp;<br>Например, «Количество больше или равно 3» — это числовая проверка столбца&nbsp;D, а не текстовая.<\\/p><p>&nbsp;<\\/p><p>Важное правило: тип проверки выбирается по смыслу данных.&nbsp;<\\/p><p>Если сумму заказа сравнивать как текст, результат может быть неожиданным.&nbsp;<\\/p><p>Поэтому для столбцов с деньгами и количеством выбирайте группу&nbsp;Number.<\\/p><p>&nbsp;<\\/p><p><strong>Несколько условий в одном&nbsp;IF:&nbsp;AND и&nbsp;OR<\\/strong><\\/p><p>В одном узле&nbsp;IF можно задать несколько условий.&nbsp;<br>Они объединяются двумя способами:<\\/p><p>AND (И) — должны выполниться все условия сразу;<\\/p><p>OR (ИЛИ) — достаточно, чтобы выполнилось любое одно условие.<\\/p><p>Например, «заказ доставлен И оплачен через&nbsp;Kaspi» — это&nbsp;AND.&nbsp;<br>Под такое условие подходит&nbsp;ORD-001, но не подходит&nbsp;ORD-005.&nbsp;<br>А условие «Статус_Оплаты равен Наличными курьеру ИЛИ Статус_Заказа равен Отменено» — это&nbsp;OR.<\\/p><p>&nbsp;<\\/p><p>Если одного&nbsp;IF мало, можно поставить второй&nbsp;IF после выхода&nbsp;false первого.&nbsp;<br>Тогда проверки идут по цепочке: сначала один вопрос, затем другой только для тех элементов, которые не прошли первый.<\\/p><p>&nbsp;<\\/p><p><strong>Подготовка: запуск&nbsp;n8n и вход в рабочую область<\\/strong><\\/p><p>Нужно, чтобы&nbsp;n8n был запущен на вашем компьютере.&nbsp;<br>Помните: локальная версия&nbsp;n8n работает только пока открыто окно терминала, в котором он запущен.<\\/p><p>Для запуска - нажмите на клавиатуре&nbsp;Win +&nbsp;R → в окне «Выполнить» введите&nbsp;cmd → нажмите&nbsp;Enter.<\\/p><p>В чёрном окне введите команду:<\\/p><p>n8n<\\/p><p>и нажмите&nbsp;Enter.<\\/p><p>Подождите.&nbsp;<br>Когда в окне появится строка со словами&nbsp;Editor is now accessible via и адресом :<br>http:\\/\\/localhost:5678<br>n8n готов.<\\/p><p>Не закрывайте это окно до конца работы.<\\/p><p>&nbsp;<\\/p><p>Откройте браузер&nbsp;Chrome → в адресной строке введите&nbsp;localhost:5678 → нажмите&nbsp;Enter.<br>Если сессия авторизации потерялась - войдите с&nbsp;email и паролем, которые вы создали в уроке 3.1.<\\/p><p>Если страница не открывается, проверьте, не закрыли ли вы чёрное окно терминала.&nbsp;<br>Если закрыли, запустите&nbsp;n8n заново командой&nbsp;n8n.<\\/p><p>&nbsp;<\\/p><p>Результат: открыта главная страница&nbsp;n8n.<\\/p><p>&nbsp;<\\/p><p><strong>Подготовка таблицы: столбец для времени доставки<\\/strong><\\/p><p>В датасете нет столбца для времени доставки.&nbsp;<br>Нам нужно куда-то записывать результат работы сценария, поэтому вы создадите один дополнительный столбец самостоятельно.&nbsp;<br>Это учебное дополнение, в исходном датасете такого поля нет.<\\/p><p>&nbsp;<\\/p><p>Откройте&nbsp;Google Таблицы в браузере → откройте свою копию датасета.<\\/p><p>Внизу окна нажмите на вкладку листа «Заказы».<\\/p><p>Нажмите на ячейку&nbsp;K1 (она находится справа от столбца&nbsp;J, Дата_Заказа, и сейчас пуста).<\\/p><p>Введите: Время_Доставки<\\/p><p>Нажмите&nbsp;Enter.<\\/p><p>Важно: создавайте заголовок до настройки узлов в&nbsp;n8n.&nbsp;<br>Узел&nbsp;Google Sheets читает список столбцов в момент настройки.&nbsp;<br>Если заголовка не было, новый столбец в&nbsp;n8n не появится.&nbsp;<br>В таком случае потом нужно будет нажать значок обновления списка столбцов.<\\/p><p>&nbsp;<\\/p><p><strong>Создание сценария и узел чтения строки<\\/strong><\\/p><p>Вернитесь на вкладку&nbsp;n8n.<\\/p><p>На главной странице, вверху слева, нажмите кнопку &nbsp;+ &nbsp;и выберите&nbsp;New workflow.&nbsp;<br>Откроется пустая рабочая область (холст) с кнопкой +&nbsp;Add firststep… в центре.<\\/p><p>Вверху слева замените название (типа&nbsp;My workflow 2) на: Проверка статуса<\\/p><p>Нажмите&nbsp;Enter.<\\/p><p>&nbsp;<\\/p><p>Нажмите на холсте кнопку&nbsp;Add firststep (Добавить первый шаг).<\\/p><p>В поле поиска введите&nbsp;Manual → выберите&nbsp;Trigger manually (Запуск вручную).<\\/p><p>Результат: на холсте появился узел «When clicking Execute workflow» (Когда клик на «Выполнить сценарий»).<\\/p><p>&nbsp;<\\/p><p>Справа от этого узла нажмите значок + на конце линии.<\\/p><p>В поиске введите&nbsp;Google Sheets → нажмите на&nbsp;Google Sheets → в списке действий выберите&nbsp;Get row(s)&nbsp;in sheet (Получить строки из листа).<\\/p><p>Откроется окно настройки узла.&nbsp;<\\/p><p>Заполните по порядку:<\\/p><p>Credential to connect with (Учётная запись для подключения) — выберите подключение&nbsp;Google Sheets, созданное в уроке 3.1.&nbsp;<br>Если в списке пусто, значит&nbsp;credential не сохранён, вернитесь к уроку 3.1.<\\/p><p>Resource (Ресурс) — оставьте Sheet Within Document.<\\/p><p>Operation (Операция) — оставьте Get Row(s).<\\/p><p>Document (Документ) — в выпадающем списке выберите режим&nbsp;From list (Из списка) → выберите имя вашего датасета (вероятно: «Сервис доставки - Фамилия Имя») .<\\/p><p>(если&nbsp;появится&nbsp;надпись: \\\"The credential \\\"Google Sheets account\\\" needs to be reconnected.\\\"&nbsp;(Необходимо повторно подключить учетные данные для \\\"учетной записи Google Sheets\\\".) - вернитесь в поле&nbsp;Credential→ нажмите карандаш (редактирование) → нажмите&nbsp;Disconnect → и пройдите процедуру входа в аккаунт&nbsp;Google заново, отметив галочками все разрешения) .<\\/p><p>Sheet (Лист) — в режиме&nbsp;Fromlist выберите «Заказы».<\\/p><p>&nbsp;<\\/p><p>В поле&nbsp;Filters (Фильтры) и нажмите&nbsp;Add Filter (Добавить фильтр).<\\/p><p>В поле&nbsp;Column (Столбец) выберите&nbsp;ID_Заказа.<\\/p><p>В поле&nbsp;Value (Значение) введите&nbsp;ORD-001.<\\/p><p>Вверху окна нажмите кнопку&nbsp;Execute step (Выполнить шаг) в окне узла.<\\/p><p>(Если&nbsp;n8n просит доступ к&nbsp;Google, вернитесь к настройке&nbsp;credential из урока 3.1.)<\\/p><p>&nbsp;<\\/p><p>Проверьте: в правой панели&nbsp;Output (Выходные данные) в режиме&nbsp;Table (Таблица) виден 1 элемент. В нём&nbsp;ID_Заказа равен&nbsp;ORD-001, Статус_Заказа равен Доставлено, Сумма_Заказа_Тг равна 6200.<\\/p><p>&nbsp;<\\/p><p>Если элементов 0, проверьте, нет ли пробела в значении&nbsp;ORD-001 и выбран ли правильный лист.&nbsp;<br>Если появилась ошибка о документе, перепроверьте поле&nbsp;Document.<\\/p><p>Закройте окно узла: нажмите на крестик или на пустое место холста.<\\/p><p>&nbsp;<\\/p><p>Результат: узел прочитал одну строку.<\\/p><p>&nbsp;<\\/p><p><strong>Добавление узла&nbsp;IF и настройка условия «Равно»<\\/strong><\\/p><p>Справа от узла&nbsp;Google Sheets нажмите значок +.<\\/p><p>В поиске введите&nbsp;If → выберите узел&nbsp;If .<\\/p><p>Откроется окно узла&nbsp;IF.&nbsp;<br>Слева в панели&nbsp;Input (Входные данные) видны данные из предыдущего узла, справа панель&nbsp;Output.<\\/p><p>&nbsp;<\\/p><p>Настройте условие:<\\/p><p>По середине окна, в разделе&nbsp;Conditions (Условия) найдите первое пустое поле&nbsp;value 1 (значение 1).<\\/p><p>Из левой панели&nbsp;Input в режиме&nbsp;Table возьмите мышкой заголовок столбца Статус_Заказа и перетащите его в поле&nbsp;value 1.&nbsp;<br>В поле появится выражение вида {{ $json[\\\"Статус_Заказа\\\"] }}.&nbsp;<br>Фигурные скобки — это признак того, что здесь подставляется значение из данных. Вводить их вручную не надо.<\\/p><p>Правее нажмите на выпадающий список операторов → выберите группу&nbsp;String → пункт&nbsp;is equal to (равно).&nbsp;<br>(скорее всего - это выбрано по умолчанию) .<\\/p><p>В поле&nbsp;value 2 введите вручную: Доставлено<\\/p><p>Нажмите&nbsp;Execute step.<\\/p><p>&nbsp;<\\/p><p>Проверьте: в правой панели видны две вкладки или раздела:&nbsp;True Branch (Ветка истины) и&nbsp;False Branch (Ветка лжи).&nbsp;<br>В&nbsp;True Branch стоит 1 элемент (ORD-001), в&nbsp;False Branch 0 элементов.<\\/p><p>&nbsp;<\\/p><p>Если элемент оказался в&nbsp;False Branch, проверьте три вещи:&nbsp;<br>в поле&nbsp;value 2 нет лишнего пробела;&nbsp;<br>слово написано с большой буквы «Доставлено»;&nbsp;<\\/p><p>в&nbsp;value 1 именно столбец Статус_Заказа, а не Статус_Оплаты.&nbsp;<\\/p><p>В нижней части окна есть раздел&nbsp;Options (Параметры) с опцией&nbsp;Ignore Case (Игнорировать регистр):&nbsp;<br>она позволяет не различать большие и маленькие буквы.<\\/p><p>&nbsp;<\\/p><p>Результат: узел проверил один элемент.<\\/p><p>&nbsp;<\\/p><p>Закройте окно узла (крестиком в правом верхнем углу).<\\/p><p>&nbsp;<\\/p><p>На холсте вы увидите, что у узла&nbsp;If два выхода: сверху&nbsp;true, снизу&nbsp;false.<\\/p><p>&nbsp;<\\/p><p><strong>Действие на ветке&nbsp;true: запись времени доставки<\\/strong><\\/p><p>Теперь научим сценарий делать работу, когда условие выполнено.<\\/p><p>Нажмите значок + у выхода&nbsp;true узла&nbsp;If.<\\/p><p>В поиске введите&nbsp;Google Sheets → выберите&nbsp;Google Sheets → выберите действие&nbsp;Updaterow in sheet (Обновить строку в листе).<\\/p><p>&nbsp;<\\/p><p>Настройте узел:<\\/p><p>Credential — то же подключение&nbsp;GoogleSheets.<\\/p><p>Document — From list → Имя&nbsp;вашего&nbsp;датасета.<\\/p><p>Sheet — From list → «Заказы».<\\/p><p>В поле:&nbsp;Column to match on (Столбец для сопоставления) — выберите&nbsp;ID_Заказа.&nbsp;<br>Это столбец, по которому&nbsp;n8n найдёт нужную строку в таблице.<\\/p><p>В поле&nbsp;Mapping Column Mode (Режим сопоставления столбцов) оставьте (или выберите)&nbsp;MapEach Column Manually (Сопоставить каждый столбец вручную).<\\/p><p>Появятся поля столбцов.&nbsp;<br>В поле&nbsp;ID_Заказа (using to match) перетащите из левой панели&nbsp;Input столбец&nbsp;ID_Заказа. Должно получиться {{ $json[\'ID_Заказа\'] }}.<\\/p><p>В поле Время_Доставки (самое нижнее) введите выражение:<\\/p><p>{{ $now.toFormat(\'dd.MM.yyyy HH:mm\') }}<\\/p><p>Здесь $now — текущие дата и время, а&nbsp;toFormat задаёт вид результата: день.месяц.год часы:минуты.&nbsp;<br>Остальные поля (имена столбцов из таблицы) - удалите (значок корзины), чтобы не затереть данные в таблице:&nbsp;<br>Нажмите&nbsp;Execute step.<\\/p><p>&nbsp;<\\/p><p>Проверьте: в правой панели&nbsp;Output видна строка с&nbsp;ID_Заказа&nbsp;ORD-001 и заполненным полем Время_Доставки.&nbsp;<br>Затем откройте&nbsp;Google Таблицу, лист «Заказы»:&nbsp;<br>в ячейке&nbsp;K2 появилась дата и время в формате вроде 16.10.2026 14:35, а значения в столбцах&nbsp;A–J строки 2 остались прежними.<\\/p><p>Если время отличается от вашего на несколько часов, это настройка часового пояса сценария.&nbsp;<br>Исправить можно так:&nbsp;<br>вверху справа нажмите три точки →&nbsp;Settings (Настройки) → поле&nbsp;Timezone (Часовой пояс) → выберите&nbsp;Asia\\/Aqtobe →&nbsp;Save (Сохранить).<\\/p><p>Если появилась ошибка о том, что столбец не найден, вернитесь к подготовке таблицы: заголовок Время_Доставки в ячейке&nbsp;K1 должен существовать, а список столбцов в&nbsp;n8n нужно обновить значком обновления рядом с полем.<\\/p><p>&nbsp;<\\/p><p>Результат:&nbsp;n8n обновил строку заказа&nbsp;ORD-001.<\\/p><p>&nbsp;<\\/p><p><strong>Проверка ветки&nbsp;false на отменённом заказе<\\/strong><\\/p><p>Важно убедиться, что сценарий не трогает заказы, которые не прошли проверку.<\\/p><p>Откройте на холсте первый узел&nbsp;Google Sheets (Getrow(s)&nbsp;in sheet) двойным щелчком.<\\/p><p>В фильтре замените значение&nbsp;ORD-001 на&nbsp;ORD-005.<\\/p><p>Нажмите&nbsp;Execute step.&nbsp;<br>Убедитесь, что в&nbsp;Output один элемент: у него Статус_Заказа равен Отменено.<\\/p><p>Закройте окно и нажмите внизу холста кнопку&nbsp;Execute (Выполнить).<\\/p><p>&nbsp;<\\/p><p>Проверьте: на узле&nbsp;If рядом с выходом&nbsp;false (нижним) написано 1&nbsp;item, а рядом с&nbsp;true ничего не написано, и узел обновления строки не запустился (он остался без зелёной галочки).&nbsp;<br>Откройте таблицу: в ячейке&nbsp;K6 (строка заказа&nbsp;ORD-005) пусто.<\\/p><p>Так и должна работать развилка:&nbsp;<br>отменённый заказ не получил время доставки.<\\/p><p>&nbsp;<\\/p><p>Сделайте&nbsp;двойной&nbsp;клик&nbsp;по&nbsp;узлу&nbsp;Google Sheets (Get row(s) in sheet).<\\/p><p>Верните значение фильтра&nbsp;ORD-001, чтобы продолжить.<\\/p><p>Закройте узел.<\\/p><p>&nbsp;<\\/p><p>Результат: сценарий отработал полностью.<\\/p><p>&nbsp;<\\/p><p><strong>Условие «Содержит»<\\/strong><\\/p><p>Условие «Равно» требует полного совпадения.&nbsp;<br>Если нужно найти фрагмент, используйте&nbsp;contains.<\\/p><p>Для примера проверим способ оплаты&nbsp;ORD-001.&nbsp;<br>Его Статус_Оплаты равен «Оплачено&nbsp;Kaspi».<\\/p><p>&nbsp;<\\/p><p>Откройте узел&nbsp;If двойным щелчком.<\\/p><p>В поле&nbsp;Conditions сотрите условие (выражение) сделанное на предыдущем этапе&nbsp;<\\/p><p>{{ $json[\\\"Статус_Заказа\\\"] }}<\\/p><p>и значение условия \\\"Доставлено\\\" .<\\/p><p>В освободившееся поле&nbsp;value 1 перетащите из левой панели столбец Статус_Оплаты.<\\/p><p>В выпадающем списке операторов выберите&nbsp;String →&nbsp;contains (содержит).<\\/p><p>В&nbsp;value 2 введите:&nbsp;Kaspi .<br>Убедитесь, что в панели&nbsp;INPUTслева, в&nbsp;ID заказа содержится ORD-001.<\\/p><p>Нажмите&nbsp;Execute step.<\\/p><p>Результат:&nbsp;ORD-001 прошёл проверку.<\\/p><p>Проверьте: в&nbsp;True Branch 1 элемент.<\\/p><p>&nbsp;<\\/p><p>Теперь замените в&nbsp;value 2 слово \\\"Kaspi\\\" на слово \\\"Налич\\\" и снова нажмите&nbsp;Execute step.&nbsp;<br>Слово «Наличными курьеру» содержит «Налич», а «Оплачено&nbsp;Kaspi» нет.&nbsp;<br>Элемент уйдёт в&nbsp;False Branch.<\\/p><p>Типичная ошибка новичка: использовать «равно» вместо «содержит».&nbsp;<br>«Kaspi» не равно «Оплачено&nbsp;Kaspi», хотя слово там есть.<\\/p><p>&nbsp;<\\/p><p>Верните исходное условие, чтобы сценарий оставался прежним:&nbsp;<br>Статус_Заказа,&nbsp;is equal to, Доставлено.&nbsp;<\\/p><p>Выполните&nbsp;Execute step.<br>Проверьте: элемент снова в&nbsp;TrueBranch.<\\/p><p>&nbsp;<\\/p><p><strong>Как заставить сценарий работать автоматически<\\/strong><\\/p><p>Пока сценарий запускается вручную кнопкой.&nbsp;<br>По плану урока нужно, чтобы он срабатывал сам, когда в таблице меняется статус заказа.&nbsp;<br>Для этого вместо ручного запуска ставят&nbsp;Google Sheets Trigger, как в уроке 3.2.<\\/p><p>&nbsp;<\\/p><p>Общая схема автоматического варианта:<\\/p><p>Google Sheets Trigger (событие: строка обновлена) →&nbsp;If (Статус_Заказа равен Доставлено) →&nbsp;Update row (проставить Время_Доставки)<\\/p><p>&nbsp;<\\/p><p>Основные настройки триггера:<\\/p><p>Event (Событие) —&nbsp;Row Updated (Строка обновлена);<\\/p><p>Document и&nbsp;Sheet — ваша копия, лист «Заказы»;<\\/p><p>Poll Times (Время опроса) —&nbsp;Every Minute (каждую минуту);<\\/p><p>Columns to Watch (Отслеживаемые столбцы) — Статус_Заказа (если такая настройка есть в вашей версии).<\\/p><p>Для работы триггера сценарий нужно включить переключателем&nbsp;Inactive\\/Active (Неактивен\\/Активен) вверху справа.&nbsp;<br>Триггер проверяет таблицу раз в минуту.&nbsp;<br>Поэтому после изменения статуса в таблице нужно подождать до минуты.&nbsp;<br>Также&nbsp;n8n должен быть запущен на компьютере.<\\/p><p>&nbsp;<\\/p><p>Чтобы не усложнять учебный сценарий и не создавать лишних записей в таблице, в этом уроке мы остановимся на ручном запуске.&nbsp;<br>Принцип останется тем же: триггер подаёт строку,&nbsp;IF решает её судьбу.<\\/p><p>Если вы всё же замените ручной запуск на триггер, то узел&nbsp;Get row(s) в сценарии больше не нужен - триггер сам передаёт данные изменённой строки.&nbsp;<br>Узел&nbsp;If тогда подключается сразу после триггера.<\\/p><p>&nbsp;<\\/p><p><strong>Что нужно запомнить<\\/strong><\\/p><p>- Узел&nbsp;IF проверяет условие для каждого элемента и отправляет его в выход&nbsp;true или&nbsp;false.<\\/p><p>- Для текста используются проверки «равно» и «содержит», для чисел группа&nbsp;Number со сравнениями «больше», «меньше» и другими.<\\/p><p>- Тип проверки нужно выбирать по смыслу данных: для денег и количества&nbsp;Number, для статусов&nbsp;String.<\\/p><p>- Несколько условий в одном&nbsp;IF объединяются через&nbsp;AND (все сразу) или&nbsp;OR (любое).<\\/p><p>- Чтобы продолжить проверку для тех, кто не прошёл первый&nbsp;IF, подключайте второй&nbsp;IF к выходу&nbsp;false.<\\/p><p>- Если ветка не подключена, элементы этой ветки просто завершают работу.<\\/p><p>- Для обновления строки в таблице используется действие&nbsp;Update row и столбец для сопоставления, например&nbsp;ID_Заказа.<\\/p><p>- Новые столбцы нужно создавать в таблице до настройки узла в&nbsp;n8n.<\\/p>\",\"tests\":[{\"question\":\"Что делает узел IF в сценарии n8n?\",\"answers\":[\"Объединяет несколько таблиц в одну\",\"Проверяет условие и направляет данные в ветку true или false ✓\",\"Проверяет, если сценарий запущен - отправляет сообщение в Telegram\",\"Удаляет из таблицы строки, которые не прошли проверку\"],\"correct\":null},{\"question\":\"Какие два выхода есть у узла IF?\",\"answers\":[\"true и false ✓\",\"start и stop\",\"success и error\",\"first и second\"],\"correct\":null},{\"question\":\"Какой оператор нужно выбрать, чтобы проверить, что значение в ячейке совпадает с нужным словом полностью?\",\"answers\":[\"contains\",\"is empty\",\"is equal to ✓\",\"starts with\"],\"correct\":null},{\"question\":\"Что проверяет оператор contains в текстовом условии?\",\"answers\":[\"Что значение полностью совпадает с заданным словом\",\"Что в ячейке вообще есть какой-нибудь текст\",\"Что длина текста больше заданного числа\",\"Что заданный фрагмент входит в состав значения ✓\"],\"correct\":null},{\"question\":\"Почему для сравнения сумм заказа и количества товара нужно выбирать группу Number, а не String?\",\"answers\":[\"Потому что String не позволяет писать цифры\",\"Потому что числа нужно сравнивать как числа, а не как текст ✓\",\"Потому что Number автоматически сохраняет результат в таблицу\",\"Потому что String работает только с английскими буквами\"],\"correct\":null},{\"question\":\"Что означает связка двух условий через AND?\",\"answers\":[\"Достаточно выполнения любого одного условия\",\"Условия проверяются по очереди, а лишнее удаляется\",\"Первое условие обязательно, а второе только записывается в таблицу\",\"Элемент проходит дальше, только если выполнены оба условия ✓\"],\"correct\":null},{\"question\":\"Что произойдёт с элементами, попавшими в выход false, если к нему ничего не подключено?\",\"answers\":[\"Они просто завершат работу, не вызвав действий дальше ✓\",\"Сценарий остановится с ошибкой для всех элементов\",\"Они вернутся на вход узла IF и будут проверены снова\",\"Они автоматически попадут в выход true\"],\"correct\":null}],\"lab\":\"<p>Цель лабораторной работы — самостоятельно построить сценарий, который находит крупные заказы и помечает их как срочные.&nbsp;<br>Вы будете обрабатывать сразу весь лист «Заказы», а не одну строку.<\\/p><p>Крупным считается заказ с суммой не менее 8000 тг.&nbsp;<br>Помечать нужно только доставленные заказы:&nbsp;<br>отменённый заказ срочной доставки не требует.<\\/p><p>&nbsp;<\\/p><p>Откройте&nbsp;Google Таблицы, свою копию датасета и&nbsp;n8n (если нужно, запустите&nbsp;n8n командой&nbsp;n8n в терминале).&nbsp;<br>Создайте в&nbsp;n8n новый сценарий и назовите его:&nbsp;<br>Крупные заказы<\\/p><p>&nbsp;<\\/p><p><strong>Задача 1. Подготовьте столбец для пометки<\\/strong><\\/p><p>На листе «Заказы» самостоятельно определите свободную ячейку первой строки справа от уже заполненного столбца&nbsp;K (Время_Доставки) и создайте в ней заголовок Пометка.&nbsp;<br>Этот столбец вы создаёте сами, в исходном датасете его нет.<\\/p><p>&nbsp;<\\/p><p><strong>Задача 2. Прочитайте весь лист заказов<\\/strong><\\/p><p>Соберите начало сценария:&nbsp;<br>ручной запуск и узел чтения листа «Заказы».&nbsp;<br>Самостоятельно решите, какие фильтры нужны, чтобы&nbsp;n8n прочитал все заказы сразу.<\\/p><p>Проверьте: в&nbsp;Output узла чтения 100 элементов (по числу заказов в датасете).<\\/p><p>&nbsp;<\\/p><p><strong>Задача 3. Опишите условие «крупный доставленный заказ» (на сумму не менее 8000)<\\/strong><\\/p><p>Добавьте узел&nbsp;If.&nbsp;<br>Самостоятельно определите, какие столбцы нужно проверить, какой тип проверки выбрать для каждого, как объединить условия и какие значения ввести.<\\/p><p>Проверьте: после запуска в&nbsp;True Branch находятся 6 элементов, а в&nbsp;False Branch 94.&nbsp;<br>Среди элементов&nbsp;True Branch есть&nbsp;ORD-046 (сумма 13600) и&nbsp;ORD-004 (сумма 9600). Заказа&nbsp;ORD-088 там быть не должно:&nbsp;<br>его сумма 11700 тг (т.е. больше 8000), но он отменён.<\\/p><p>Если у вас получилось другое число, проверьте тип проверки суммы (она должна сравниваться как число), условие объединения и написание статуса.<\\/p><p>&nbsp;<\\/p><p><strong>Задача 4. Запишите пометку в таблицу<\\/strong><\\/p><p>На выходе&nbsp;true подключите узел для записи данных в таблицу.&nbsp;<br>Самостоятельно выберите нужное действие и столбец для сопоставления, чтобы каждая пометка попала в строку именно своего заказа.&nbsp;<br>В столбец Пометка должно записываться значение:&nbsp;<br>Срочная доставка<\\/p><p>&nbsp;<\\/p><p>Проверьте: в&nbsp;Google Таблице пометка «Срочная доставка» появилась ровно в 6 строках: 5 (ORD-004), 14 (ORD-013), 15 (ORD-014), 47 (ORD-046), 62 (ORD-061) и 94 (ORD-093).&nbsp;<br>В остальных строках столбец «Пометка» пуст, а значения в столбцах&nbsp;A–K остались без изменений.<\\/p><p>&nbsp;<\\/p><p><strong>Задача 5. Проверьте устойчивость сценария<\\/strong><\\/p><p>Запустите сценарий ещё раз.<\\/p><p>Проверьте: количество строк с пометкой по-прежнему равно 6.&nbsp;<br>Новых строк в таблице не появилось, пометки не продублировались, а значения в других столбцах не пропали.<\\/p><p>&nbsp;<\\/p><p><strong>Задача 6. Обработайте отменённые заказы<\\/strong><\\/p><p>Подключите к выходу&nbsp;false первого узла&nbsp;If ещё один узел&nbsp;If.&nbsp;<br>Самостоятельно определите условие, которое выделит из оставшихся заказов отменённые.&nbsp;<br>Для отменённых заказов запишите в столбец Пометка - значение: Отменён<\\/p><p>Проверьте: во втором&nbsp;If TrueBranch содержит 14 элементов.&nbsp;<br>Это все отменённые заказы датасета, включая&nbsp;ORD-005 и&nbsp;ORD-088.&nbsp;<br>После запуска в столбце Пометка в этих 14 строках записано «Отменён», а 6 строк с пометкой «Срочная доставка» не изменились.<\\/p><p>&nbsp;<\\/p><p>После завершения работы верните датасет в исходное состояние: удалите добавленные вами столбцы&nbsp;K и&nbsp;L на листе «Заказы» (правый щелчок по букве столбца →&nbsp;Delete column) или получите заново копию исходного датасета.&nbsp;<br>Остановить&nbsp;n8n можно, закрыв окно терминала или нажав в нём&nbsp;Ctrl +&nbsp;C.<\\/p>\"}'),
(16, 5, '3.4. Сквозная интеграция: Telegram-бот, Google Таблицы и n8n', 'bot--sheets--n-eight-n', 4, '{\"theory\":\"<p>В предыдущих уроках каждый сервис мы настраивали отдельно.&nbsp;<br>В модуле 2&nbsp;Telegram-бот на&nbsp;Aimylogic принимал заказ и записывал его в&nbsp;Google Таблицу.&nbsp;<br>В уроках 3.1–3.3&nbsp;n8n научился читать таблицу и отправлять сообщения.&nbsp;<br>Теперь соединим всё в одну систему и проверим её целиком.<\\/p><p>&nbsp;<\\/p><p>Готовая цепочка выглядит так:<\\/p><p>Клиент оформляет заказ в&nbsp;Telegram-боте →&nbsp;Aimylogic записывает новую строку на лист «Заказы из бота» →&nbsp;n8n замечает новую строку → технический бот отправляет сообщение в&nbsp;Telegram-группу курьеров Петропавловска.<\\/p><p>&nbsp;<\\/p><p><strong>Как данные идут по цепочке ?<\\/strong><\\/p><p>Разберём цепочку по станциям.<\\/p><p>&nbsp;<\\/p><p>Станция 1. Клиентский бот в&nbsp;Aimylogic.&nbsp;<br>Клиент вводит имя, адрес, телефон и нажимает «Подтвердить заказ».&nbsp;<br>Бот работает на серверах&nbsp;Aimylogic, ваш компьютер ему не нужен.<\\/p><p>&nbsp;<\\/p><p>Станция 2.&nbsp;Google Таблица.&nbsp;<br>Блок «Интеграция с&nbsp;Google-таблицами» с действием «Сохранить в строку» добавляет новую строку на лист «Заказы из бота»:&nbsp;<\\/p><p>A — Имя_Клиента,&nbsp;B — Адрес_Доставки,&nbsp;C — Телефон,&nbsp;D — Дата_Время_Заказа.<\\/p><p>&nbsp;<\\/p><p>Станция 3. Сценарий&nbsp;n8n на вашем компьютере.&nbsp;<br>Узел&nbsp;Google Sheets Trigger раз в минуту проверяет лист и ищет новые строки.&nbsp;<br>Он работает, только пока открыто окно терминала с&nbsp;n8n и пока сценарий опубликован.<\\/p><p>&nbsp;<\\/p><p>Станция 4. Технический бот и группа курьеров.&nbsp;<br>Узел&nbsp;Telegram подставляет значения из новой строки в текст и отправляет сообщение в группу, где состоит технический бот.<\\/p><p>&nbsp;<\\/p><p>Главная идея урока:&nbsp;Aimylogic и&nbsp;n8n ничего не знают друг о друге.&nbsp;<br>Aimylogic только пишет в таблицу, а&nbsp;n8n только читает таблицу.&nbsp;<br>Таблица здесь место встречи.&nbsp;<br>Отсюда три правила.<\\/p><p>&nbsp;<\\/p><p>Первое.&nbsp;<br>Оба сервиса должны работать с одним документом и одним листом.&nbsp;<br>Бот пишет в лист «Заказы из бота» вашей копии датасета, и именно этот лист должен быть выбран в триггере&nbsp;n8n.<\\/p><p>&nbsp;<\\/p><p>Второе.&nbsp;<br>Заголовки столбцов служат договором между станциями.&nbsp;<br>Выражение {{ $json[\\\"Телефон\\\"] }} найдёт значение, только если заголовок&nbsp;C1 называется именно Телефон.&nbsp;<br>Если переименовать заголовок, сообщение придёт с пустым местом.<\\/p><p>&nbsp;<\\/p><p>Третье.&nbsp;<\\/p><p>Каждую станцию можно проверить отдельно.&nbsp;<\\/p><p>Если новая строка появилась в таблице, станции 1 и 2 исправны, и причину нужно искать дальше по цепочке.<\\/p><p>&nbsp;<\\/p><p>Про скорость.&nbsp;<\\/p><p>В плане курса цепочка названа «мгновенной», но таблица не посылает&nbsp;n8n сигнал.&nbsp;<br>n8n сам заглядывает в неё по расписанию.&nbsp;<\\/p><p>Мы выставим проверку раз в минуту, поэтому сообщение приходит с задержкой до минуты.&nbsp;<\\/p><p>Это нормальная работа системы, а не ошибка.<\\/p><p>&nbsp;<\\/p><p><strong>Что должно быть готово перед началом ?<\\/strong><\\/p><p>Из предыдущих уроков вам понадобятся:<\\/p><p>Клиентский бот из модуля 2:&nbsp;<br>сценарий «Оформить заказ» опубликован в&nbsp;Aimylogic,&nbsp;<br>Telegram подключён (уроки 2.1 и 2.4).<\\/p><p>Лист «Заказы из бота» в вашей копии датасета с заголовками&nbsp;A1 Имя_Клиента,&nbsp;B1 Адрес_Доставки,&nbsp;C1 Телефон,&nbsp;D1 Дата_дата_Время_Заказа, записанными так же, как в уроке 2.4.&nbsp;<br>Дополнительные столбцы справа (например, «Комментарий») не мешают.<\\/p><p>Технический бот из урока 3.2: его токен сохранён, а в&nbsp;n8n есть&nbsp;credential Telegram.<\\/p><p>В n8n есть credential Google Sheets (урок 3.1).<\\/p><p>Если чего-то не хватает, вернитесь к соответствующему уроку.<\\/p><p>&nbsp;<\\/p><p>Шаг 1. Проверяем станции 1 и 2: от бота до таблицы<\\/p><p>Прежде чем строить новое, убедитесь, что уже построенное работает.<\\/p><p>Откройте&nbsp;Chrome → в адресной строке введите&nbsp;web.telegram.org →&nbsp;Enter.&nbsp;<br>Если&nbsp;Telegram не авторизован - на телефоне откройте Настройки (Settings) → Устройства (Devices) → Подключить устройство (Link Desktop Device) → отсканируйте&nbsp;QR-код на экране компьютера.<\\/p><p>&nbsp;<\\/p><p>В поиске&nbsp;Telegram введите&nbsp;username клиентского бота (например,&nbsp;trump_delivery_bot, - подставьте свой) → откройте чат → нажмите три вертикальные точки справа вверху → «Очистить историю» → подтвердите.<\\/p><p>Введите \\/start → нажмите «На главное меню» → «Оформить заказ».&nbsp;<br>На вопросы бота ответьте:<\\/p><p>имя: Алия ;<\\/p><p>адрес: ул. Конституции Казахстана, д. 20, кв. 4 ;<\\/p><p>телефон: 707-707-70-70 .<\\/p><p>&nbsp;<\\/p><p>Если вы добавляли вопросы в лабораторной работе урока 2.4, ответьте и на них:&nbsp;<br>нашей цепочке они не мешают, она использует только столбцы&nbsp;A–D.<\\/p><p>Нажмите «Подтвердить заказ».<\\/p><p>Ожидаемый результат: сообщение «Спасибо! Ваш заказ принят...».<\\/p><p>&nbsp;<\\/p><p>Откройте свою копию датасета → вкладка «Заказы из бота».<\\/p><p>Проверьте: в первой свободной строке появились Алия, адрес, телефон и дата со временем в столбце&nbsp;D.&nbsp;<br>Если бот показал сообщение об ошибке или строки нет, вернитесь к разделу:&nbsp;<br>«Если запись не появилась в таблице» урока 2.4:&nbsp;<br>чаще всего причина в названии листа или в порядке полей блока записи.<\\/p><p>&nbsp;<\\/p><p>Результат: станции 1 и 2 работают.<\\/p><p>&nbsp;<\\/p><p><strong>Шаг 2. Создаём&nbsp;Telegram-группу для курьеров<\\/strong><\\/p><p>Курьеры должны получать сообщения в общую группу - тогда уведомление увидят все сразу, а нового курьера достаточно добавить в группу.&nbsp;<br>В учебной работе группа будет состоять из вас и технического бота.<\\/p><p>В&nbsp;Telegram Web нажмите, в левом верхнем углу, иконку бургера (главное меню&nbsp;Telegram) →&nbsp;New Group (Новая группа).<\\/p><p>В поле названия введите: Курьеры → нажмите&nbsp;Next (Далее).<\\/p><p>В строке поиска участников введите&nbsp;username технического бота из урока 3.2&nbsp;<br>(например,&nbsp;trump_notify_bot) → добавьте найденного технического бота в участники группы → нажмите кнопку Создать (Create).<\\/p><p>Проверьте: в списке чатов появилась группа, а в списке её участников есть технический бот.<\\/p><p>&nbsp;<\\/p><p><strong>Получаем&nbsp;Chat&nbsp;ID группы<\\/strong><\\/p><p>Бот пишет в чат группы по его числовому номеру.&nbsp;<br>У группы номер отрицательный, он начинается со знака минус.&nbsp;<\\/p><p>Чтобы получить номер группы&nbsp;Telegram, нужно отправить первое (стартовое) сообщение от бота.<br>В поле ввода группы напишите сообщение начинающееся на \\/start@ и, далее,&nbsp;username_вашего_бота.&nbsp;<br>Например:<br><code>\\/start@trump_delivery_notify_bot<\\/code>&nbsp;<br>Отправьте это сообщение.<\\/p><p>&nbsp;<\\/p><p>В&nbsp;Chrome откройте новую вкладку и введите адрес, заменив ВАШ_ТОКЕН на токен технического бота (токен есть в сообщении&nbsp;BotFather из урока 3.2):<\\/p><p><code>https:\\/\\/api.telegram.org\\/botВАШ_ТОКЕН\\/getUpdates<\\/code><\\/p><p>(Между словом&nbsp;bot и токеном пробела нет).&nbsp;<br>Нажмите&nbsp;Enter.&nbsp;<br>Если вверху страницы есть галочка «Автоформатировать», отметьте её.<\\/p><p>Найдите блок, где рядом стоят название вашей группы и «type”: “group”.&nbsp;<br>Перед ними будет фрагмент <code>“chat”:{“id”:<\\/code> и число, например <code>-4012345678<\\/code> .&nbsp;<\\/p><p>(В списке будет и ваш личный чат из урока 3.2, он нам не нужен - ищите именно группу.)<br>Скопируйте число целиком вместе со знаком минус и куда ни будь запишите (на гугл диск или отправьте на свой телефон в whatsapp).<\\/p><p>(Если результат пустой (result: []), напишите в группе боту ещё раз и обновите страницу клавишей&nbsp;F5.)&nbsp;<br>&nbsp;<\\/p><p>Результат: у вас есть&nbsp;Chat ID группы курьеров.<\\/p><p>&nbsp;<\\/p><p><strong>Шаг 3. Запускаем&nbsp;n8n и снимаем с публикации workflow<\\/strong><\\/p><p>Нажмите&nbsp;Win+R → введите&nbsp;cmd →&nbsp;Enter. В чёрном окне введите&nbsp;n8n и нажмите&nbsp;Enter. Дождитесь строки «Editor is nowaccessible via:&nbsp;http:\\/\\/localhost:5678».&nbsp;<br>Окно закрывать нельзя.&nbsp;<br>Откройте&nbsp;Chrome →&nbsp;localhost:5678 → войдите с&nbsp;email и паролем владельца.<\\/p><p>&nbsp;<\\/p><p>Теперь важная проверка.&nbsp;<br>Если опубликованы сразу два сценария, которые следят за одним листом, каждый заказ придёт в&nbsp;Telegram дважды.&nbsp;<\\/p><p>Поэтому снимите с публикации сценарии прошлых уроков.&nbsp;<\\/p><p>На главной странице приложения, списке ваших&nbsp;workflow, на каждом&nbsp;workflow, справа, нажмите … (три точки) и нажмите&nbsp;Unpublish (Снять с публикации).<\\/p><p>&nbsp;<\\/p><p><strong>Шаг 4. Собираем сценарий для курьеров<\\/strong><\\/p><p>Нажмите кнопку «+» вверху слева →&nbsp;New workflow.&nbsp;<br>Нажмите на название «My workflow..» → введите Заказы для курьеров →&nbsp;Enter.<\\/p><p>&nbsp;<\\/p><p>Первый узел. Нажмите&nbsp;Add firststep... → в поиске введите&nbsp;Google Sheets → выберите&nbsp;Google Sheets → в разделе&nbsp;Triggers выберите&nbsp;On row added (При добавлении строки).&nbsp;<br>Заполните:<\\/p><p>В поле&nbsp;Credential -&nbsp;Google Sheets Trigger account<\\/p><p>(Чтобы убедится, что ваш&nbsp;Google-аккаунт подключен - справа от поля&nbsp;Credential - нажмите карандаш - в окне&nbsp;Google Sheets Trigger account - должна быть надпись на зелёном фоне&nbsp;Account connected).<\\/p><p>Poll Times (время&nbsp;опроса) → Add Poll Time → Mode: Every Minute (режим:&nbsp;каждую&nbsp;минуту).<\\/p><p>Document →&nbsp;From list → ваша копия датасета «Сервис доставки - Фамилия Имя».<\\/p><p>(если ваша копия датасета не отображается - пройдите заново процедуру входа в&nbsp;Google-аккаунт.)<\\/p><p>Sheet →&nbsp;From list → «Заказы из бота».<\\/p><p>Trigger On → Row Added.<\\/p><p>В&nbsp;окне&nbsp;слева&nbsp;нажмите: Fetch Test Event.&nbsp;<br>Проверьте: в&nbsp;Output появились данные последней строки (Алия, адрес, телефон, время).&nbsp;<br>Если данных нет, лист пуст под заголовками - повторите проверку шага 1.&nbsp;<br>Закройте окно крестиком.<\\/p><p>&nbsp;<\\/p><p>Второй узел.&nbsp;<br>Нажмите «+» справа от узла → в поиске введите&nbsp;Telegram → выберите&nbsp;Telegram → в разделе&nbsp;Actions выберите&nbsp;Send a text message.&nbsp;<br>Заполните:<\\/p><p>Credential —&nbsp;credential технического бота из урока 3.2.&nbsp;<br>Новый создавать не нужно - выберите его в списке.<\\/p><p>Resource — Message,&nbsp;<br>Operation — Send Message.<\\/p><p>Chat ID — вставьте номер группы вместе со знаком минус.<\\/p><p>Text — соберите сообщение, как объясняется далее.&nbsp;<br>Надёжнее перетаскивать поля мышью из панели&nbsp;INPUT слева, как в уроке 3.2, а название и двоеточие дописывать руками.<\\/p><p>Итак, в поле&nbsp;Text введите:<\\/p><p><code>Новый заказ на доставку!<\\/code><\\/p><p><code>Клиент: {{ $json[\\\"Имя_Клиента\\\"] }}<\\/code><\\/p><p><code>Адрес: {{ $json[\\\"Адрес_Доставки\\\"] }}<\\/code><\\/p><p><code>Телефон: {{ $json[\\\"Телефон\\\"] }}<\\/code><\\/p><p><code>Заказ оформлен: {{ $json[\\\"Дата_Время_Заказа\\\"] }}<\\/code><\\/p><p>Внизу окна нажмите&nbsp;Add Field →&nbsp;Append n8n Attribution → выключите переключатель, чтобы не было приписки «отправлено через&nbsp;n8n».<\\/p><p>&nbsp;<\\/p><p>Справа в блоке&nbsp;OUTPUT нажмите&nbsp;Execute Step.&nbsp;<br>Откройте&nbsp;Telegram -&nbsp;<br>в группе должно появиться сообщение с данными вашей последней строки.<\\/p><p><br>Проверьте: в сообщении нет пустых мест после двоеточий.&nbsp;<br>Если пусто, название столбца в выражении не совпало с заголовком листа буква в букву.<\\/p><p>Если вместо сообщения красная ошибка&nbsp;chat not found, проверьте&nbsp;Chat ID:&nbsp;<br>есть ли минус и не попал ли пробел.&nbsp;<br>Если ошибка говорит, что бот не состоит в группе, добавьте его в участники.<\\/p><p>&nbsp;<\\/p><p>Закройте окно узла.&nbsp;<\\/p><p>Проверьте, что между узлами есть линия.&nbsp;<br>Если её нет, протяните её мышью от правой точки первого узла к левой точке второго.<\\/p><p>Нажмите&nbsp;Execute внизу холста.&nbsp;<br>Проверьте: оба узла с зелёными галочками, в группе пришло сообщение.<\\/p><p>&nbsp;<\\/p><p>Теперь включите автоматическую работу.&nbsp;<br>Нажмите&nbsp;Publish справа вверху → подтвердите.&nbsp;<br>Проверьте: кнопка стала&nbsp;Published.<\\/p><p>Результат: сценарий работает в боевом режиме и наблюдает за листом.<\\/p><p>&nbsp;<\\/p><p><strong>Шаг 5. Сквозной тест всей системы<\\/strong><\\/p><p>Откройте две вкладки:&nbsp;<br>Telegram Web и вашу копию датасета с листом «Заказы из бота».&nbsp;<br>В&nbsp;Telegram откройте клиентского бота → очистите историю → \\/start → «На главное меню» → «Оформить заказ».&nbsp;<br>Введите:<\\/p><p><code>имя: Данияр ;<\\/code><\\/p><p><code>адрес: ул. Букетова, д. 31, кв. 9 ;<\\/code><\\/p><p><code>телефон: 705-705-75-75<\\/code><\\/p><p>Нажмите «Подтвердить заказ» и запомните время нажатия.<\\/p><p>&nbsp;<\\/p><p>Дальше наблюдайте по порядку.&nbsp;<br>Сначала клиентский бот присылает «Спасибо! Ваш заказ принят...».&nbsp;<br>Затем на листе в новой строке появляются данные Данияра.&nbsp;<br>После этого откройте группу курьеров и подождите до минуты.<\\/p><p>Проверьте: в группе пришло сообщение «Новый заказ на доставку!» с данными Данияра, а не Алии, и они совпадают с введёнными в боте и со строкой в таблице.&nbsp;<br>В&nbsp;n8n откройте вкладку&nbsp;Executions:&nbsp;<br>там новый запуск со статусом&nbsp;Succeeded.<\\/p><p>Результат:&nbsp;<br>система работает от нажатия кнопки клиентом до сообщения курьерам.<\\/p><p>&nbsp;<\\/p><p>Если цепочка оборвалась - определяем станцию<\\/p><p>Не меняйте несколько настроек сразу.&nbsp;<br>Определите по симптому, где рвётся цепочка.<\\/p><p>&nbsp;<\\/p><p>Бот не отвечает или клиент видит сообщение об ошибке.&nbsp;<br>Сбой на станциях 1–2.&nbsp;<br>Проверьте, что сценарий опубликован,&nbsp;Telegram подключён, а название листа в блоке записи совпадает с вкладкой «Заказы из бота» буква в букву.<\\/p><p>&nbsp;<\\/p><p>Клиент получил «Спасибо!», но строки в таблице нет.&nbsp;<br>Откройте блок записи в&nbsp;Aimylogic - проверьте: порядок полей и название листа.&nbsp;<br>Обратите внимание, что вы смотрите нужную копию датасета.<\\/p><p>&nbsp;<\\/p><p>Строка в таблице есть, сообщения нет.&nbsp;<\\/p><p>Сбой на станции 3.&nbsp;<\\/p><p>Запущено ли окно терминала с&nbsp;n8n, опубликован ли сценарий, выбран ли в триггере именно лист «Заказы из бота», прошла ли минута.&nbsp;<br>Если вкладка&nbsp;Executions показывает красный запуск, прочитайте текст ошибки в узле. Если&nbsp;Google просит войти заново, нажмите&nbsp;Sign in withGoogle в&nbsp;credential:&nbsp;<br>в режиме тестирования доступ&nbsp;Google отзывает примерно через 7 дней.<\\/p><p>&nbsp;<\\/p><p>Запуск зелёный, но в группе пусто, или ошибка&nbsp;chat not found.&nbsp;<br>Сбой на станции 4.&nbsp;<\\/p><p>Проверьте&nbsp;Chat ID (знак минус) и то, что технический бот состоит в группе.&nbsp;<br>Если вы превратили группу в супергруппу, её номер изменился: получите его заново.<\\/p><p>&nbsp;<\\/p><p>Сообщения приходят дважды.&nbsp;<br>Опубликованы два сценария, следящих за одним листом.&nbsp;<br>Снимите лишний с публикации.<\\/p><p>&nbsp;<\\/p><p><strong>Что важно знать при работе в реальном бизнесе<\\/strong><\\/p><p>Пока&nbsp;n8n работает на обычном компьютере, уведомления идут только пока компьютер включён, а окно терминала открыто.&nbsp;<br>В группу курьеров добавляйте только сотрудников:&nbsp;<br>в сообщениях есть телефоны клиентов.&nbsp;<br>Токен технического бота и ключи&nbsp;Google нельзя показывать в общих чатах.<\\/p><p>&nbsp;<\\/p><p><strong>Что нужно запомнить<\\/strong><\\/p><p>✓&nbsp;Aimylogic и&nbsp;n8n связаны только через таблицу:&nbsp;<br>первый записывает строки, второй их читает.<\\/p><p>✓&nbsp;Документ, лист и заголовки столбцов должны совпадать на всех станциях.<\\/p><p>✓&nbsp;Триггер&nbsp;n8n проверяет таблицу по расписанию, поэтому сообщение приходит с задержкой до минуты.&nbsp;<\\/p><p>✓&nbsp;Chat&nbsp;ID группы&nbsp;Telegram отрицательный, а бот должен быть участником группы.<\\/p><p>✓&nbsp;Сквозная проверка нужна потому, что каждое звено может работать по отдельности, а данные теряются на стыках.&nbsp;<\\/p><p>✓&nbsp;При сбое определяйте станцию: &nbsp;<br>бот, таблица,&nbsp;n8n или&nbsp;Telegram.<\\/p>\",\"tests\":[{\"question\":\"Какую роль выполняет Google Таблица в цепочке «бот — таблица — n8n»?\",\"answers\":[\"Хранит токены ботов и передаёт их сервисам при запуске\",\"Показывает клиенту сообщения вместо Telegram-бота\",\"Служит общим местом: один сервис записывает в неё данные, а другой их читает ✓\",\"Автоматически отправляет уведомления курьерам в Telegram\"],\"correct\":null},{\"question\":\"Почему в такой системе Aimylogic и n8n не обмениваются данными напрямую?\",\"answers\":[\"Каждый из них связан только с таблицей и ничего не знает о другом ✓\",\"Потому что Aimylogic умеет работать только с токеном технического бота\",\"Потому что Telegram запрещает двум сервисам работать с одним ботом\",\"Потому что n8n принимает данные только от сервисов Google\"],\"correct\":null},{\"question\":\"Чем объясняется задержка до минуты между появлением строки в таблице и сообщением курьерам?\",\"answers\":[\"Aimylogic, по умолчанию, откладывает отправку заказа на минуту\",\"Telegram ограничивает отправку сообщений в группы раз в минуту\",\"Триггер n8n проверяет таблицу по расписанию раз в минуту ✓\",\"Сообщение отправляется только после ручного подтверждения в n8n\"],\"correct\":null},{\"question\":\"Что должно совпадать, чтобы триггер n8n увидел заказ, записанный ботом?\",\"answers\":[\"Название сценария n8n и название проекта в Aimylogic\",\"Название группы курьеров и имя клиентского бота\",\"Номер телефона курьера и Chat ID курьера\",\"Лист, в который пишет бот, и лист, выбранный в триггере ✓\"],\"correct\":null},{\"question\":\"Какой признак отличает Chat ID группы в Telegram?\",\"answers\":[\"Это отрицательное число со знаком минус ✓\",\"Он начинается со знака @ и совпадает с username бота\",\"Он всегда совпадает с номером телефона создателя группы\",\"Он состоит только из букв названия группы\"],\"correct\":null},{\"question\":\"Что необходимо, чтобы технический бот мог отправлять сообщения в группу курьеров?\",\"answers\":[\"Бот должен быть участником группы ✓\",\"Каждый курьер должен отдельно написать боту в личные сообщения\",\"Нужно вставить в узел токен клиентского бота вместо технического\",\"Бот должен получить права администратора в Aimylogic\"],\"correct\":null},{\"question\":\"Клиент получил «Спасибо! Ваш заказ принят», строка в таблице появилась, но курьеры ничего не получили. Где в первую очередь искать причину?\",\"answers\":[\"В тексте приветствия клиентского бота\",\"В настройках BotFather клиентского бота\",\"В названии кнопки «Подтвердить заказ» в Aimylogic\",\"Со стороны n8n: запущен ли он, опубликован ли сценарий, что показывает вкладка Executions ✓\"],\"correct\":null},{\"question\":\"Зачем проводят сквозную проверку, если каждое звено уже проверено отдельно?\",\"answers\":[\"Чтобы заново создать все credentials и токены\",\"Чтобы удалить тестовые строки из таблицы автоматически\",\"Чтобы проверить, что клиентский бот отвечает быстрее минуты\",\"Чтобы убедиться, что данные не теряются на стыках между звеньями ✓\"],\"correct\":null},{\"question\":\"В каком порядке движутся данные в готовой системе?\",\"answers\":[\"Клиент → Telegram-бот в Aimylogic → Google Таблица → n8n → Telegram-группа курьеров ✓\",\"Клиент → n8n → Google Таблица → Aimylogic → Telegram-группа курьеров\",\"Таблица → клиент → Aimylogic → Telegram-группа курьеров → n8n\",\"Клиент → Telegram-группа курьеров → Google Таблица → n8n → Aimylogic\"],\"correct\":null}],\"lab\":\"<p>Цель работы:&nbsp;<br>самостоятельно воспроизвести ключевую часть настройки и проверить систему на типичных и нетипичных ситуациях.&nbsp;<\\/p><p>Подробных шагов здесь нет, ориентируйтесь на теорию.&nbsp;<br>Результаты записывайте, они понадобятся в задаче 6.<\\/p><p>&nbsp;<\\/p><p><strong>Задача 1. Вторая группа курьеров<\\/strong><\\/p><p>Создайте новую&nbsp;Telegram-группу «Курьеры-2» с участием технического бота. Самостоятельно получите её&nbsp;ChatID и переключите узел&nbsp;Telegram вашего сценария на эту группу.&nbsp;<br>Определите, нужно ли заново создавать&nbsp;credential и сам сценарий.<\\/p><p>Проверьте: после запуска сценария сообщение приходит в новую группу, а в прежнюю не приходит.<\\/p><p>&nbsp;<\\/p><p><strong>Задача 2. Контрольный заказ и замер задержки<\\/strong><\\/p><p>Оформите через клиентского бота заказ с любыми данными.&nbsp;<br>Запишите три момента: время нажатия «Подтвердить заказ», время из столбца Дата_Время_Заказа новой строки и время получения сообщения в группе.<br>Определите, сколько минут заняла каждая часть пути и какая из них зависит от настройки&nbsp;Poll Times.<\\/p><p>Проверьте: данные в сообщении полностью совпадают с введёнными, а общая задержка не превышает двух минут.<\\/p><p>&nbsp;<\\/p><p><strong>Задача 3. Отменённый заказ<\\/strong><\\/p><p>Пройдите оформление до экрана проверки данных и нажмите «Отменить заказ». Выясните три факта:&nbsp;<br>появилась ли новая строка на листе, пришло ли сообщение в группу, появился ли новый запуск на вкладке&nbsp;Executions.&nbsp;<br>Объясните в одном-двух предложениях, почему результат именно такой.<\\/p><p>&nbsp;<\\/p><p><strong>Задача 4. Переименованный лист<\\/strong><\\/p><p>Смоделируйте типичную ошибку:&nbsp;<br>в таблице переименуйте вкладку «Заказы из бота», добавив в конец любую букву. Оформите заказ через бота.&nbsp;<br>Запишите, что увидел клиент, что произошло в таблице и в группе, что показывает вкладка&nbsp;Executions.&nbsp;<br>Определите, на какой станции возник сбой и почему он виден клиенту.<\\/p><p>Верните исходное название вкладки точно, без пробелов.&nbsp;<br>Проведите контрольный заказ.<\\/p><p>Проверьте: после возврата названия заказ снова доходит до группы курьеров, а в записях есть описание симптомов каждой станции.<\\/p>\"}');

